// generated from VOA Learning English, Let's Learn English (public domain, credit learningenglish.voanews.com)
const VOA = [{"g":"Уровень 1","t":"Lesson 1: Welcome!","u":"/a/lets-learn-english-lesson-one/3111026.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/5/5f/5f00c78a-0f84-41e6-949d-bd808bcadf50.mp4?cb=edc3e5eec","a":"https://voa-audio.voanews.eu/vle/2016/02/08/49485bf8-4277-47f6-9abe-617ee2473f8c.mp3","l":[["Pete","Hi! Are you Anna?"],["Anna","Yes! Hi there! Are you Pete?"],["Pete","I am Pete."],["Anna","Nice to meet you."],["Anna","Let's try that again. I'm Anna. Nice to meet you."],["Pete","I'm Pete. \"Anna\" Is that A-N-A?"],["Anna","No. A-N-N-A"],["Pete","Well, Anna with two \"n's\"... Welcome to... 1400 Irving Street!"],["Anna","My new apartment! Yes!"]]},{"g":"Уровень 1","t":"Lesson 2: Hello, I'm Anna!","u":"/a/lets-learn-english-lesson-2-hello/3113733.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/4/42/4298a2ba-d665-4b1c-aaa1-502bbcb9b88d.mp4?cb=edc3e6218","a":"https://voa-audio.voanews.eu/vle/2016/02/10/56246d7b-5fa4-42d2-90b0-d403e6b46227.mp3","l":[["Jonathan","Hey, Pete! Who's your friend?"],["Pete","She is Anna. She is new to D.C."],["Jonathan","Where are you from?"],["Anna","I am from a small town."],["Jonathan","Well, welcome to D.C."],["Anna","Thank you."],["Jonathan","I am Jonathan. I am in apartment B4."],["Anna","I am in apartment C2. Marsha is my roommate."],["Jonathan","I know Marsha. She is nice."],["Pete","And I am in Apartment D7. I have to go now."],["Anna","Oh!"],["Pete","Remember to call Marsha at work. Tell her you're here."],["Anna","Right, thanks, Pete. Nice to meet you!"],["Jonathan","You too, Bye."],["Anna","Apartment C2, here I come!"]]},{"g":"Уровень 1","t":"Lesson 3: I'm Here!","u":"/a/lets-learn-english-lesson-3-i-am-here/3126527.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2016/05/0/02/027f8fdd-e9b0-409c-8618-45be49fcefe8_hq.mp4?cb=ecfb9e14d","a":"https://voa-audio.voanews.eu/vle/2016/02/18/a82baaf4-0a91-4d43-8ab6-78f72cef8fce.mp3","l":[["Anna","I am in my new apartment! Great!"],["Man","Hello."],["Anna","Hello. Is this Marsha? It is Anna."],["Man","I am sorry. You have the wrong number."],["Anna","Oh. Is this 555-8986?"],["Man","No. This is 555-8689."],["Anna","Oh. Excuse me!"],["Man","Okay. 'Bye."],["Anna","One more time. 555-8986. Please be Marsha."],["Marsha","Hello. This is Marsha."],["Anna","Yes, Marsha. I want to cook dinner."],["Marsha","Excuse me? Anna? Is that you?"],["Anna","Oh, yes. I am here!"],["Marsha","Good. You are there."],["Anna","I want to find a supermarket."],["Marsha","Oh, okay. The supermarket is at 1500 Irving Street. It is near the apartment."],["Anna","Great! Goodbye!"],["Marsha","Goodbye, Anna."],["Anna","There is a big supermarket on our street. And Marsha says I am a good cook! Until next time! Bye!"]]},{"g":"Уровень 1","t":"Lesson 4: What Is It?","u":"/a/lets-learn-english-lesson-4/3168920.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2016/05/c/c8/c829a13b-9764-4b89-ad70-1edbdc3d8013_hq.mp4?cb=ecfb9e17b","a":"https://voa-audio.voanews.eu/vle/2016/02/26/af0324f6-67c5-4c0c-ab42-abb0cd33817c.mp3","l":[["Anna","Pete, hi! Hi, we are here!"],["Pete","Hi, Anna! Hi, Marsha!"],["Anna","Hi!"],["Pete","How are you two?"],["Marsha","I am great!"],["Anna","You know, Pete, I am new to D.C. The city is big."],["Pete","Yeah. But you learn a little more every day. How's the new apartment?"],["Anna","The new apartment is great! Let's get coffee!"],["Marsha","Anna, do you have a pen?"],["Anna","Yes. I have a pen in my bag."],["Anna","I have a …"],["Pete","It is not a pen. It is a book. It is a big book."],["Anna","Yes. Yes it is, Pete. I know I have a pen, though…"],["Anna","I have a...."],["Marsha","It is not a pen, Anna... a toy?"],["Anna","I have a...."],["Pete","And it is a pillow!"],["Anna","Pete, Marsha, I know I have a pen."],["Marsha","Anna, it is a map."],["Pete","Why do you have a map of the world?"],["Anna","Pete, Marsha. Now I know I have a pen."],["Pete","And now you have a lamp."],["Marsha","Anna."],["Anna","I have a pen! Let's get coffee!"]]},{"g":"Уровень 1","t":"Lesson 5: Where Are You?","u":"/a/lets-learn-english-lesson-5-where-are-you/3168971.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2016/05/c/ce/ce630bdd-1ffd-4c63-aca7-4bdff50fc7ba_hq.mp4?cb=ed0a575e6","a":"https://voa-audio.voanews.eu/vle/2016/03/01/ab9c2944-eddc-4806-9296-290bfa8c6ff2.mp3","l":[["Anna","Hello, everyone! Today my friend Marsha is at her friend's house. She says it is beautiful. I want to see this house! Here we are!"],["Anna","Marsha, I am in the kitchen! It is a beautiful kitchen!"],["Marsha","It is beautiful. We cook in the kitchen."],["Anna","I eat in the kitchen."],["Marsha","We relax in the living room."],["Anna","I relax in the living room. Marsha, let's go upstairs!"],["Marsha","Anna? Where are you?"],["Anna","Marsha, I am in the bathroom! I wash in the bathroom."],["Marsha","I am in the bedroom. We sleep in the bedroom."],["Anna","I sleep in the bedroom!"]]},{"g":"Уровень 1","t":"Lesson 6: Where Is the Gym?","u":"/a/lets-learn-english-lesson-6-where-is-the-gym/3225958.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2016/05/1/17/17b61020-32a1-4021-9575-adbf9ee76979_hq.mp4?cb=ecfb9e2bf","a":"https://voa-audio.voanews.eu/vle/2016/03/10/66b63229-1dc5-40ab-886d-1f4b891adf6b.mp3","l":[["Anna","Hi there! I'm Anna and I live in Washington, D.C. Every day I learn more about this great city. People in Washington like to work out! Oh, hi, Pete. How's it going?"],["Pete","Hi, Anna. It's going great. How's it going with you?"],["Anna","Things are awesome! Pete, I want to work out. Where is the gym?"],["Pete","The gym is across from the lounge. It's next to the mailroom. Go that way."],["Anna","Thanks, Pete!"],["Pete","No, Anna! Not that way! Go that way!"],["Anna","Oh, Pete. This is not the gym."],["Pete","That's right, Anna. This is the mailroom."],["Anna","The gym is across from … what?"],["Pete","The gym is across from the lounge."],["Anna","Across from the lounge. Right. Thanks!"],["Anna","Pete! This is not the gym!"],["Pete","The gym is across from the lounge. It is behind the lobby."],["Anna","Right. Right. See you."],["Pete","See you, Anna!"],["Anna","See you."],["Pete","See you, Anna."],["Anna","This is not the gym. This is a parking garage."],["Anna","Hello? Pete?"],["Anna","This is not a gym. This is a rooftop."],["Anna","Pete! Pete?"],["Pete","I want to work out too! Join me!"],["Anna","I'm good."]]},{"g":"Уровень 1","t":"Lesson 7: What Are You Doing?","u":"/a/lets-learn-english-lesson-7-what-are-you-doing/3240468.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2016/05/5/54/54ebe82e-9578-4c39-9ca9-42dae639be4f_hq.mp4?cb=ecfb9e2d5","a":"https://voa-audio.voanews.eu/vle/2016/03/16/5d724fbc-a907-4a48-9221-c1813d248168.mp3","l":[["Caty","Come in."],["Caty","Well, Anna, welcome."],["Anna","Thank you."],["Caty","I am your boss, Caty Weaver. But, please call me Caty."],["Anna","Thank you, Ms. Weaver."],["Caty","Just Caty."],["Anna","Sure thing, Ms. Weaver."],["Caty","Okay then. Are you excited?"],["Anna","Yes, I am excited!"],["Caty","So sorry, but I am busy. Please meet your co-workers. But remember, they are busy working."],["Anna","Sure. Thanks, Ms. Weaver."],["Anna","Hi there! I'm Anna."],["Anne","Hi, Anna. I'm Anne."],["Anna","Nice to meet you. What are you doing?"],["Anne","Um, I'm writing."],["Anna","You are writing! You are writing a lot!"],["Anna","(Spills papers) Oh! Oh dear."],["Anne","No! No! That's okay."],["Anna","I am sorry!"],["Anne","That's okay. Really."],["Anna","I am sorry!"],["Anne","Please. Please. Please stop. Please."],["Anna","Sorry. Sorry."],["Jonathan","(in the studio) \"and people all around the world are waiting to hear news about the next president…\""],["Anna","Jonathan, hi! Remember me? I live in your building."],["Jonathan","Oh. Uh. Hi, Anna."],["Anna","What are you doing?"],["Jonathan","I am doing my show!"],["Anna","Oh, sorry. Are you recording?"],["Jonathan","Yes! And, now I have to record again!"],["Anna","Sorry. Have a good show."],["Jonathan","Thank you."],["Anna","Sorry."],["Amelia","The word of the day is social. Social -"],["Anna","Oh! Hi!"],["Amelia","- is an adjective."],["Anna","Hi! I'm Anna!"],["Amelia","Hi. I'm Amelia."],["Anna","Nice to meet you!"],["Anna","What are you doing?"],["Amelia","I'm reading."],["Anna","Are you reading the news? Hi!"],["Amelia","No, I'm reading for my show."],["Amelia","(to camera person) Can I read again?"],["Anna","Sorry."],["Anna","This day is not going well."],["Caty","Anna! Hi! What're you doing?"],["Anna","I am bothering people, Ms. Weaver."],["Caty","Let's go to my office and talk."],["Anna","I like to talk with you, Ms. Weaver."],["Caty","It's Caty."],["Anna","Right. Thanks... Ms. Weaver"]]},{"g":"Уровень 1","t":"Lesson 8: Are You Busy?","u":"/a/lets-learn-english-lesson-8-are-you-busy/3253185.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2016/05/e/ee/ee277d1c-017b-4b98-9491-8de08a76122e_hq.mp4?cb=ecfb9e192","a":"https://voa-audio.voanews.eu/vle/2016/03/25/ae6c5055-13ae-485b-995d-b347125ecf10.mp3","l":[["Anna","Hello, everyone. Here I am at my new job! Yesterday at my first day of work … Well, let's not talk about yesterday. Today is a new day! Today I want to apologize to my co-workers."],["Anna","Hi, Anne. Are you busy?"],["Anne","Hi, Anna. Yes. At 10 a.m. I am writing. Every day I do my morning show. Sorry!"],["Anna","Okay. See you later, maybe."],["Anne","Maybe I'll see you later."],["Anna","Hi, Jonathan. Are you busy?"],["Jonathan","Yes, I'm busy. When the studio light is on, I am recording my evening show."],["Anna","Right. Sorry about yesterday."],["Jonathan","No worries."],["Anna","May I see the studio?"],["Jonathan","Um, maybe another time? Right now I am busy."],["Anna","Sure. Okay, 'bye."],["Jonathan","‘Bye."],["Anna","Hi, Amelia! Are you busy?"],["Amelia","I'm a little busy."],["Anna","I want to say I'm sorry for yesterday."],["Amelia","It's okay, Anna."],["Anna","Well, I am sorry."],["Amelia","It's okay, Anna. Come by this afternoon."],["Anna","Okay."],["Caty","Anna."],["Anna","Yes, Ms. Weaver."],["Caty","Are you busy?"],["Anna","Yes, Ms. Weaver. I am busy."],["Caty","My office. 5:00 p.m."],["Anna","5:00 p.m."],["Caty","Come in."],["Anna","A party! Awesome! And I still have my job! Phew!* Until next time!"]]},{"g":"Уровень 1","t":"Lesson 9: Is It Cold?","u":"/a/lets-learn-english-lesson-9-is-it-cold/3261789.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2016/05/4/44/44b5b429-02aa-45c0-ac5a-cde704945b4b_hq.mp4?cb=ecfb9e1a6","a":"https://voa-audio.voanews.eu/vle/2016/04/01/fe67e651-87d0-4b62-9c68-749b2d3c2f21.mp3","l":[["Anna","Oh, hi, everyone! Here in Washington, DC, the weather changes often. One day is cold and windy. But the next day is warm and sunny! So, every day I check the forecast. Hello, Phone? What is today's temperature?"],["Phone","Today it is 18 degrees..."],["Anna","Eighteen degrees! That is cold!"],["Phone","… eighteen degrees Celsius."],["Anna","Oh, Celsius. That is 65 degrees Fahrenheit. That's warm."],["Phone","Yes, Anna. It is warm."],["Anna","Excuse me, Phone. Is it windy today?"],["Phone","No, it is not windy today."],["Anna","Is it sunny today?"],["Phone","Yes, Anna. It is sunny."],["Anna","Excuse me, Phone?"],["Phone","Yes, Anna."],["Anna","Is it snowy today?"],["Phone","No, Anna. It is not snowy."],["Anna","Thank you, Phone!"],["Anna","Today the weather is warm and sunny -- great for seeing Washington, D.C."],["Anna","Phone! It is not warm and sunny! It is cold and windy and snowy!"],["Phone","Anna, it is not cold, windy, or snowy. It is warm and sunny … in Mexico City, Mexico."],["Anna","Oh. I see. Mexico."],["Anna","Washington weather changes often. Remember to check the forecast -- the right forecast."],["Phone","Yes, Anna. Next time remember to check the right fore…"],["Anna","Okay, thank you Phone. Goodbye, Phone."],["Anna","Until next time!"]]},{"g":"Уровень 1","t":"Lesson 10: Come Over to My Place","u":"/a/lets-learn-english-lesson-10/3285228.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2016/06/3/3e/3ec2bbef-f064-4545-bbdd-74f2a695e141_hq.mp4?cb=ecfb9e2ea","a":"https://voa-audio.voanews.eu/vle/2016/04/14/442a6a50-693e-411f-8cff-99e40d16614c.mp3","l":[["Anna","Hi! Today, my friend Ashley, is coming over. I am showing her my new apartment! Oh! That's Ashley calling."],["Anna","Hi Ashley!"],["Ashley","Hi Anna! I'm coming to your apartment. Where is your apartment?"],["Anna","My apartment is near the Columbia Heights Metro."],["Ashley","It is near the Columbia Heights Metro?"],["Anna","Yes. Exit the Metro and turn right. Then at the bus station turn left. Then walk straight ahead."],["Ashley","Okay. Exit Metro, turn right, turn left, then go straight ahead?"],["Anna","Yes. My apartment is near a coffee shop."],["Ashley","Okay. See you soon!"],["Anna","Hi, Ashley."],["Ashley","Anna, Which coffee shop? There are three coffee shops."],["Anna","Okay, my apartment is across from a big department store."],["Ashley","A big department store? Ah, I see it!"],["Anna","Okay! Bye, Ashley. See you soon!"],["Ashley","Okay. See you soon."],["Anna","Ashley! Ashley! Ashley! Over here! It's Anna! It's Anna! Hi!"],["Anna","I love having my friends over. Come on!"],["Ashley","Great!"]]},{"g":"Уровень 1","t":"Lesson 11: This Is My Neighborhood","u":"/a/lets-learn-english-lesson-11-this-is-my-neighborhood/3293986.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2016/05/9/93/932ae001-a462-4158-8e25-399289a46ec9_hq.mp4?cb=ecfb9e1b9","a":"https://voa-audio.voanews.eu/vle/2016/04/20/de238e35-97b9-4c21-81e3-e3c26fbeccaa.mp3","l":[["Anna","Hello! DC is a city for walking. In our neighborhood, I can do all my errands. Marsha, before we get ice cream, I need to return three books to the library. Where is the library?"],["Marsha","It is on this street on the corner."],["Anna","Awesome!"],["Marsha","Let's go!"],["Anna","Marsha, I can return the books here."],["Marsha","Anna, what are those in the books?"],["Anna","Marsha, these are letters to my family and friends back home … four letters! Is there a post office near here?"],["Marsha","Um, no. The post office is far from here. But there is a mailbox across from the store."],["Anna","Awesome! Let's go!"],["Anna","Marsha, now I need to buy stamps."],["Marsha","Do you have cash?"],["Anna","No. Is there a bank near here?"],["Marsha","There is a bank behind you."],["Anna","Thanks, Marsha. You know our neighborhood so well."],["Anna","Now I have cash. I can buy stamps."],["Marsha","That store sells stamps."],["Anna","Wait here."],["Anna","I have stamps."],["Marsha","Wow, you're fast."],["Anna","Thank you, thank you letters, for sending my words… my love … to my family and friends -"],["Marsha","Do you have more cash?"],["Anna","I do!"],["Marsh and Anna","Ice cream!!"],["Anna","I love my new neighborhood! Everything is near our apartment! Even hair salons*, and ice cream!"],["Anna","Until next time!"]]},{"g":"Уровень 1","t":"Lesson 12: Meet My Family","u":"/a/lets-learn-english-lesson-12-meet-my-family/3301733.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2016/05/6/67/671fbaf2-668e-49a3-9828-a0639d1ce3d5_hq.mp4?cb=ecfb9e304","a":"https://voa-audio.voanews.eu/vle/2016/04/28/d1527ef7-587d-45b5-b3cc-fecbe37167ab.mp3","l":[["Anna","Hello! Washington, D.C. has many beautiful parks. In fact, this park reminds me of my home very far away."],["Marsha","Anna, here's your coffee."],["Anna","Thanks, Marsha."],["Marsha","What's wrong?"],["Anna","I'm thinking about my family. I'm feeling homesick."],["Marsha","Do you want to talk about it?"],["Anna","Sure! I have some photos."],["Marsha","Yes. Yes, you do!"],["Anna","Photos really help."],["Anna","This is my mother and this is my father. They are rodeo clowns."],["Marsha","What do rodeo clowns do?"],["Anna","They make jokes at a rodeo. They make people laugh."],["Marsha","That-That';s very different."],["Marsha","Who is that woman in the picture?"],["Anna","That is my Aunt Lavender. She is my mom's sister. She loves gardening and makes spoons."],["Marsha","She makes spoons?"],["Anna","Of course."],["Marsha","That, too, is very different."],["Anna","Oh! This is my Uncle John. He is my father's brother."],["Marsha","What does Uncle John do?"],["Anna","He's a chicken farmer. And makes guitars. He's awesome, and I'm his favorite niece."],["Marsha","Who are they?"],["Anna","They are my cousins. They are my Uncle John's daughter and son."],["Marsha","What do they do?"],["Anna","They raise sheep and make sweaters."],["Marsha","Yeah, that's not a surprise."],["Marsha","Thanks for showing me your family photos. Your family is very different."],["Anna","I do feel better. Thanks for listening. I have many more photos!"],["Marsha","Yeah. Yeah, you do."],["Anna","Washington, DC is my new home. But I like remembering my old home, too."]]},{"g":"Уровень 1","t":"Lesson 13: Happy Birthday, William Shakespeare!","u":"/a/lets-learn-english-lesson-13-happy-birthday-william-shakespeare/3312239.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/7/73/73103ed5-8133-4a1a-9219-cfef86973f25.mp4?cb=edc3fa7ae","a":"https://voa-audio.voanews.eu/vle/2016/05/05/a7673055-e023-4593-9372-06d61ee8afd9.mp3","l":[["Anna","Hello! In Washington D.C. there are many things to do on a Sunday afternoon. I like to exercise. I like to shop. I like to garden. But today I feel bored. When I feel bored I always look for something unusual to do! I hear music. Let's go see! What is going on here?"],["Rebecca","It's a big birthday party for the writer William Shakespeare."],["Anna","This is a party for William Shakespeare?"],["Rebecca","Yes!"],["Anna","Awesome!"],["Rebecca","Awesome!"],["Anna","This is a drum band. I never listen to a drum band. But today I am listening to a drum band because it's Shakespeare's birthday!"],["Anna","This is a puppet show. I never watch puppet shows. But today I am watching a puppet show because it's Shakespeare's birthday!"],["Anna","My clothes are usual. His clothes are unusual."],["Anna","In Washington, D.C. seeing a politician or even the President is usual. Seeing the Queen of England is very unusual! Your majesty!"],["Anna","This is sword fighting. I never sword fight. But today I am sword fighting because it's Shakespeare's birthday!"],["Anna","There are many things to do in Washington, D.C. -- some usual, some unusual."],["Anna","Today, I am not bored because … it is William Shakespeare's birthday!"]]},{"g":"Уровень 1","t":"Lesson 14: How About This?","u":"/a/lets-learn-english-lesson-14-how-about-this/3323771.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/3/3d/3d8d63a8-2984-4469-9737-d34b0d519506.mp4?cb=edc3fa9f5","a":"https://voa-audio.voanews.eu/vle/2016/05/11/f3b56fb5-23f9-4668-bae1-d98ab8967e50.mp3","l":[["Anna","Hi, there! In Washington, D.C. people do many things in the evening. They go listen to music. They eat at a restaurant. They go to the theater."],["Anna","Tonight I am going to the theater with my friends. But I don't know what clothes to wear. Maybe this magazine can help."],["Anna","Her clothes are beautiful! I really want a friend like her to help me."],["Anna","Who are you?"],["Genie","I am Genie! You want help. I am here to help you find the right clothes!"],["Anna","Awesome! How about jeans and a t-shirt?"],["Genie","No! Jeans and a t-shirt are too casual. How about something more formal?"],["Anna","Sure!"],["Anna","Wow! Genie, this dress is beautiful. But it's not the right size. It's too small."],["Genie","Yes, it is too small. But green looks great on you."],["Anna","Thanks."],["Genie","Take off the green dress. Let's try a green shirt and a skirt."],["Anna","Oh, Genie! This green shirt is too large and this orange skirt is too orange."],["Genie","Yes, the right size for you is medium. Let's try again."],["Anna","Oh, I don't like this outfit."],["Genie","No. That does not match."],["Anna","Nothing."],["Anna","These clothes are formal: a suit jacket, a dress shirt and a tie! They look great!"],["Genie","Those clothes look great … for a man! Something is wrong."],["Anna","Let me see."],["Anna","There. Now try."],["Genie","Oh. Thanks! Now these clothes look great on you!"],["Anna","They do! Um, Genie, can you put on a gold belt?"],["Genie","Sure!"],["Genie","That looks great."],["Anna","Can you put on a jacket?"],["Genie","Why not?"],["Anna","I love the jacket! How about a hat?"],["Genie","Why not?"],["Genie","Mm, take off the hat. That's better."],["Anna","Genie, these clothes look and feel great! Let's go to the theater!"],["Genie","Sorry, Anna. I have to help other friends. Go to the magazine if you want me to help again."],["Anna","Thanks, Genie. Sure thing. Goodbye!"],["Genie","Goodbye!"],["Anna","There are many places in DC to go for a great evening out! And it's nice to have a friend to help me look my best. Until next time! Bye!"]]},{"g":"Уровень 1","t":"Lesson 15: I Love People-Watching!","u":"/a/lets-learn-english-lesson-15-i-love-people-watching/3343720.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/b/b0/b07eac5a-cc3a-4f3e-821c-ecae337b5415.mp4?cb=edc3fab67","a":"https://voa-audio.voanews.eu/vle/2016/05/31/b08ceeac-8274-4e2d-b678-2cd30ba31f4f.mp3","l":[["Anna","Hello! People from all over the world come to Washington, D.C. When I'm at work, I love eating lunch outside. I like to watch people walking by. They all look very different. Today, my friend Ashley is eating lunch with me."],["Anna","Ashley, today the weather is beautiful, isn't it?"],["Ashley","Yes, it is. Ahh. Ooh, we have to return to work!"],["Anna","No, we have time! Let's people-watch a little more."],["Ashley","Okay."],["Anna","Oh, I know her. She works in my office! Keyana, hi! Come and join us!"],["Keyana","Hi Anna, how are you?"],["Anna","I'm doing great! Keyana, this is my friend Ashley."],["Keyana","Hi, Ashley!"],["Anna","We need to return to work. But the weather is beautiful and people-watching is fun!"],["Keyana","I love people-watching too!"],["Anna","Well, have a seat! It is fun to see how people are different or the same."],["Keyana","It is. For example, Anna, you are tall. But Ashley and I are short."],["Anna","And Keyana, you and Ashley have brown eyes; I have blue eyes."],["Keyana","You two have light skin and I have dark skin."],["Anna","Ashley, you have straight hair. Keyana and I have curly hair."],["Ashley","You have very curly hair, Anna."],["Keyana","I need to return to work. See you, Anna! Nice to meet you Ashley!"],["Ashley","Bye, Keyana!"],["Ashley","Anna, I have to go, too. Are you returning to work?"],["Anna","I still have time. And this sun feels so good!"],["Ashley","Um, Anna, what does your boss look like?"],["Anna","She is short. She has straight, light hair."],["Ashley","Does she wear glasses?"],["Anna","Yes. Yes, she does."],["Ashley","Is she wearing a blue sweater today?"],["Anna","How do you know that?"],["Ashley","She's coming this way."],["Anna","Oh no! Hide me!"],["Ashley","Um, bye, Anna. Call me later."],["Anna","Bye, Ashley! Talk to you later!"],["Caty","Anna? Is that you?"],["Anna","Ms. Weaver! Hi!"],["Caty","What are you doing behind that bench?"],["Anna","I am looking for my, my … stick. Here it is."],["Anna","I am people-watching. Oh! But it's time to return to work!"],["Caty","No need to hurry. I love people-watching too! Let's sit!"],["Anna","Sure! Ahh."],["Caty","It's a beautiful day, isn't it?"],["Anna","Yes. Yes, it is, Ms. Weaver."],["Anna","People-watching in D.C. is fun. It makes me forget the time!"],["Anna","Until next time! Ahh."]]},{"g":"Уровень 1","t":"Lesson 16: Where Are You From?","u":"/a/lets-learn-english-lesson-16-where-are-you-from/3355849.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/d/dd/ddc153c2-e1b2-4d09-b8ba-67172e1f88fe.mp4?cb=edc3faf05","a":"https://voa-audio.voanews.eu/vle/2016/06/02/869a701e-1242-4c34-a679-7a9454a770f1.mp3","l":[["Anna","Hello! Washington, D.C. has many tourists! People from different countries come here. Today, my job is to interview tourists. I have to learn why they come here. This is very exciting! Excuse me. I'm Anna Matteo from The News. Do you have time for an interview?"],["Sabrina","Sure, I have time."],["Anna","What is your name?"],["Sabrina","My name is Sabrina."],["Anna","What country are you from?"],["Sabrina","I'm from Bangladesh."],["Anna","So, you are Bangladeshi."],["Sabrina","That's right! My nationality is Bangladeshi."],["Anna","Do you like Washington, D.C.?"],["Sabrina","Yes! The city is very beautiful!"],["Anna","What do you like to do in Washington D.C.?"],["Sabrina","I like history. So, I like walking around and looking at all the monuments and memorials. They make history come alive!"],["Anna","Washington has many monuments and memorials. The Washington Monument is behind us! Which is your favorite?"],["Sabrina","I really like Lincoln Memorial. It is very beautiful. And it feels like Abraham Lincoln is still alive."],["Anna","Awesome. Thank you for your time, Sabrina!"],["Sabrina","You're welcome."],["Anna","Let's find another tourist."],["Anna","Oh! Excuse me. I am Anna Matteo from The News. Do you have time for a couple of questions?"],["Louis","Sure!"],["Anna","Are you from Washington, D.C.?"],["Louis","No, I'm not."],["Anna","What is your name and where are you from?"],["Louis","My name is Louis. And I'm from China."],["Anna","What languages do you speak?"],["Louis","I speak Chinese and English."],["Anna","What do you like about Washington DC?"],["Louis","I like the museums. I really like the art museums."],["Anna","Many of the museums are free."],["Louis","I like that too!"],["Anna","Awesome! Thanks for your time, Louis."],["Louis","You're very welcome. Bye!"],["Anna","Now, let's find another tourist!"],["Anna","Hello! I am Anna Matteo from The News. Do you have time to answer a couple of questions?"],["Mehrnoush","Sure!"],["Anna","What is your name and where're you from?"],["Mehrnoush","My name is Mehrnoush. I am from Iran. I'm Iranian."],["Anna","What language do they speak in Iran? Is it Persian?"],["Mehrnoush","They speak Farsi."],["Anna","What do you like to do in Washington DC?"],["Mehrnoush","Well, I like learning about government and politics."],["Anna","Washington has many politicians!"],["Mehrnoush","It does! I want to see the U.S. Capitol."],["Anna","Look, you are very near."],["Mehrnoush","I am!"],["Anna","Have fun!"],["Mehrnoush","Thanks!"],["Anna","There you have it. Tourists from all over the world come to Washington, D.C. They all like doing and seeing different things in the city. This is Anna Matteo reporting for The News. Until next time!"],["Anna","Is that okay? Awesome! Now, I want to do my favorite thing in the city … ride the carousel!"]]},{"g":"Уровень 1","t":"Lesson 17: Are You Free on Friday?","u":"/a/are-you-free-on-friday-lets-learn-english/3355785.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/f/fb/fbb85647-eaa9-4ca4-801e-c4c085593d89.mp4?cb=edc3fb114","a":"https://voa-audio.voanews.eu/vle/2016/06/07/3cb6442c-001f-4fd7-bf37-7507a49e89e4.mp3","l":[["Anna","This city is very interesting, I really like my job, and I have some good friends! Speaking of friends … I see one now! Marsha! Hi!"],["Marsha","Hi, Anna. What's going on?"],["Anna","Not much. How about you?"],["Marsha","Busy as usual. Hey, do you wanna see a movie with me?"],["Anna","Sure! I never have time to see a movie. When?"],["Marsha","Are you busy this Thursday at 6pm?"],["Anna","Let's see …. I'm busy. I am going to tap dance with my friends Thursday night."],["Marsha","Tap dancing? That sounds fun!"],["Anna","I'm still learning. But it is fun!"],["Anna","Are you busy on Friday night?"],["Marsha","Yes. Friday nights are when I visit my parents."],["Anna","What do you and your family do together?"],["Marsha","We always eat dinner together and sometimes we play board games."],["Anna","Playing board games is fun, too! The word game Scrabble is my favorite."],["Marsha","I like Connect Four!"],["Anna","I'm not busy Monday night. Are you?"],["Marsha","I am busy on Monday night. I'm going to jog in the park with my friend. Do you jog?"],["Anna","Oh! I always jog. Well, sometimes I jog. Okay, I never jog. But I will try because it is good for you."],["Marsha","I always feel great after I jog."],["Marsha","How about on Wednesday night?"],["Anna","Wednesday night I am not busy. Oh, no, wait. This Wednesday night I will be busy."],["Marsha","What are you doing?"],["Anna","I'm going to teach children how to play the ukulele."],["Anna","Now, children, play \"C.\" Good. I like your \"C.\""],["Marsha","The world does need more ukulele players."],["Anna","Marsha, it looks like we'll never have time to see a movie."],["Anna","Wait a minute. Are you busy now?"],["Marsha","It's Saturday afternoon. This is always when I do my errands."],["Anna","Okay, but the new Star Wars movie is gonna start in 30 minutes."],["Marsha","I'll do my errands on Sunday. Let's go!"],["Anna","Most days of the week, people are really busy. But it's important to find time to be with your friends!"],["Anna","Until next time!"]]},{"g":"Уровень 1","t":"Lesson 18: She Always Does That","u":"/a/lets-learn-english-lesson-18-she-always-does-that/3357748.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/a/aa/aa81937e-fc02-4d62-9f34-e8b432538615.mp4?cb=edc3fb36f","a":"https://voa-audio.voanews.eu/vle/2016/06/15/6581d80f-fd20-40f9-b363-3f998c3f1142.mp3","l":[["Anna","Hello, from Washington, D.C.! Today at work I am reading the news for the first time. I am really nervous. But my boss, Ms. Weaver, is here to help me."],["Caty","Now, Anna, remember. When we read the news we are always reading facts. We never show our feelings."],["Anna","Sure thing, Ms. Weaver."],["Caty","Great. Are you ready?"],["Anna","Yes."],["Caty","Okay, let's try the first story!"],["Anna","Hello, and welcome to The News."],["Anna","A new book is very popular with children and families. This is it."],["Anna","It is about a lost duckling. The duck's mother cannot find him."],["Caty","Stop! Anna, when you say the words \"duck\" and \"duckling\" you look really sad."],["Anna","I do?"],["Caty","Yes. Sad is a feeling."],["Anna","Sad is not a fact. Sorry. Let me try again."],["Caty","Okay, she's trying again! And go."],["Anna","Hello, and welcome to The News. A new book is very popular with children and families. This is it."],["Anna","It is about a lost duckling. The duck's mother can not find ‘im. But a family gives him a home."],["Caty","Stop! Anna, you are doing it again."],["Anna","This story is very sad."],["Caty","I have an idea. Let's read the second story. She's reading the second story. And … go!"],["Anna","Hello, and welcome to The News. In Indiana, a grandmother is the first 80-year-old woman to win The Race Car 500."],["Anna","That is awesome!"],["Caty","Stop! Stop! Anna, please -- no feelings."],["Anna","Right. But it is awesome that an 80-year-old grandmother wins a car race."],["Caty","Just the facts, Anna."],["Anna","Right."],["Anna","Hello, and welcome to The News. In Indiana, a grandmother is the first 80-year-old woman to win The Race Car 500."],["Anna","She rarely talks to reporters. But when she does, she often says, \"Nothing can stop me now!\""],["Anna","I am very happy for her!"],["Caty","Stop, stop, stop!! Anna, you cannot say you are happy."],["Anna","But I am happy."],["Caty","But you can't say it."],["Anna","Why?"],["Caty","This is the News. Happy and sad are feelings. You can't have them in The News."],["Anna","Okay. I got it."],["Caty","Okay. Let's try the third story. She's reading the third story!"],["Anna","Hello and welcome to The News."],["Anna","What?! That makes me very angry."],["Caty","No, no, no! Anna, you cannot say you are angry! This is The News!!!"],["Anna","What can I do, Ms. Weaver? Take out my feelings and put them here … on the news desk?"],["Caty","Yes. Yes. That's right! Now you've got it!"],["Caty","Let's repeat the first story."],["Anna","This is going to be a very long day."],["Anna","Until next time!"]]},{"g":"Уровень 1","t":"Lesson 19: When Do I Start?","u":"/a/lets-learn-english-lesson-19-when-do-you-start/3357760.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/8/87/87817c7f-1ceb-47ae-9e56-c90081179223.mp4?cb=edc3fb68f","a":"https://voa-audio.voanews.eu/vle/2016/06/20/11279270-a48f-4bca-851e-e6477329717b.mp3","l":[["Anna","Hi there! Summer in Washington, D.C. is hot and sunny. I always ride the Metro to work. Riding the Metro is cool and fast. But today it's closed. So, I am walking to work."],["Caty","That's too bad. It's really hot today."],["Anna","Yes it is."],["Caty","When you arrive, please come to my office. I have important news to tell you."],["Anna","Of course. Good-bye. My boss has news for me. The question is: Is it good news or bad news?"],["Anna","Hello, Ms. Weaver."],["Caty","Anna, I have good news and I have bad news. Which do you want to hear first?"],["Anna","The good news. No … okay, the bad news."],["Caty","The bad news is you are not good at reading the news."],["Anna","Oh. I am very sorry to hear that."],["Caty","So, starting next month you will not read the news."],["Anna","Next month is July. You are firing me in July."],["Caty","No. I am not firing you in July … or in August or in September. That is the good news."],["Anna","Okay. You are not firing me. I am not reading the news. What will I be doing?"],["Caty","Well, you are good at asking questions. You are good at talking to people. You are good at showing your feelings. And you are great at being silly."],["Anna","Thank you, Ms. Weaver. But what does all that mean?"],["Caty","I have a new assignment for you! Your skills are perfect for a new show … a children's show."],["Anna","A children's show... That is awesome! When do I start?"],["Caty","You start next month. Start thinking of ideas for the show."],["Anna","I have tons of ideas! I can show children what it's like in outer space..."],["Caty","Great …"],["Anna","… or in the deep, dark ocean …"],["Caty","Those are great ideas, Anna. Please go think of more … at your desk."],["Anna","Yes. What other things can I show them? Mt. Everest! Everyone has different skills. You have skills. I have skills. The important thing is to know what you are good at. Until next time!"]]},{"g":"Уровень 1","t":"Lesson 20: What Can You Do?","u":"/a/lets-learn-english-lesson-20-what-can-you-do/3384429.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2016/06/5/5d/5d078c81-3fa1-4101-9d0f-9cbab2c671ce_hq.mp4?cb=ecfb9e1dc","a":"https://voa-audio.voanews.eu/vle/2016/06/29/8225db0f-179b-453f-92bb-50f548175c42.mp3","l":[["Anna","Hi, there! Washington, D.C. is a great place to work. Many people here work in government and politics. But there are many other jobs. You can work at a hospital; a university. You can work in a coffee shop. Wait a minute, I think I see a friend of mine. Pete? Is that you?"],["Pete","Hi, Anna."],["Anna","You look different. Your beard … is really big."],["Pete","You don't like it, do you?"],["Anna","No, no. You just look … different."],["Pete","I don't have a job."],["Anna","Sorry, I can't hear you."],["Pete","I do not have a job!"],["Anna","Oh. I'm sorry to hear that, Pete."],["Pete","I don't have a skill."],["Anna","Everyone has a skill. You need to find yours."],["Pete","I don't know, Anna."],["Anna","Pete, I am good at asking questions. Let me ask you some."],["Pete","Really, Anna? Can you help me?"],["Anna","Yes, I can. Let me help."],["Pete","Sure, Anna. Maybe you can help."],["Anna","Can you write code?"],["Pete","Sure, c-o-l-d. How is this going to help?"],["Anna","No, not \"cold.\" Code; you know, for making phone apps, or websites. You can make tons of money writing code."],["Pete","Tons of money? But I can't code."],["Anna","Next question. Can you drive?"],["Pete","Do you mean drive a race car? It's really hard to be a race car driver. First, you need a race car..."],["Anna","No, I mean drive a taxi or drive a bus."],["Pete","No, I always fall asleep when I drive."],["Anna","Oh, that's not good. Next question. Can you teach? You can be a teacher in a school."],["Pete","No, I cannot teach."],["Anna","Can you cook? You can be a chef in a restaurant."],["Pete","No, I can't code! I can't teach! I can't cook! Anna, I can't do anything. This is sad. I'm gonna write about my feelings in my blog."],["Anna","You write a blog?"],["Pete","Yeah, I write a blog."],["Anna","How many followers do you have?"],["Pete","I don't know … 59,538."],["Anna","Pete, that's a lot of followers! You can make money writing!"],["Pete","Writing is easy. Everyone can write."],["Anna","Not everyone can write well. You can be a writer!"],["Pete","I can be a writer. I can be a writer! I can be a writer! Thanks, Anna."],["Marsha","Hi, Pete. Hi, Anna."],["Pete","Hi, Marsha. Excuse me, I have to go."],["Marsha","Where are you going?"],["Pete","I'm going to be a writer!"],["Marsha","Good luck, Pete!"],["Anna","There are many different jobs you can have in Washington, D.C. Pete wants to be a writer. I wish him luck. Lots of luck. Until next time!"]]},{"g":"Уровень 1","t":"Lesson 21: Can You Come to the Party?","u":"/a/lets-learn-english-lesson-21-can-you-come-to-the-party/3406732.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/3/38/38946ff6-eee8-4acc-a3fc-759121fd6313.mp4?cb=edc3fbab8","a":"https://voa-audio.voanews.eu/vle/2016/07/11/e0c9e4c4-584b-4bd7-a4d5-a4b1f7bdfa8f.mp3","l":[["Anna","Hi there! Washington, D.C. has some great coffee shops. My favorite is this one -- Busboys & Poets."],["Anna","Actually it's more than a coffee shop. It's also a bookstore, a restaurant and a theater!"],["Anna","Marsha and I love coming here."],["Marsha","Hey, Anna, my friend is having a party on Saturday. Can you come with me?"],["Anna","Sorry, I can't come with you. I have to get my driver's license."],["Marsha","Will you be busy all day?"],["Anna","I don't know. First, I have to take a test on the computer. Then I have to take a test in the car."],["Marsha","But you have to take the test during the day, don't you?"],["Anna","Yes."],["Marsha","The party is at night."],["Anna","Oh. Then I can come with you to the party on Saturday night."],["Marsha","Great! I have to help my friend with the party. Can you help me?"],["Anna","Sure. That sounds like fun."],["Marsha","Everyone has to bring something or do something. You can bring food, or you can perform."],["Anna","Really, I can perform?"],["Marsha","You can! Can you?"],["Anna","Yes! I can recite poetry. (Anna is in a club reciting a poem)"],["Marsha","In this country, nobody recites poetry at parties. Um … can you do anything else?"],["Anna","Hmm, yes. I can do a card trick. (Anna is doing a card trick)"],["Marsha","Anna, maybe you can just bring food."],["Anna","No, I can't cook. And I really want to perform. You know, there is one thing I can do. (Anna plays a song on the ukulele and sings)"],["Marsha","That's it! You can sing at the party. Now, I have to go shopping for food."],["Anna","Can I help? I'm not busy right now."],["Marsha","Sure, let's go!"],["Anna","We have to go. I have to help Marsha shop. And I have to practice my song! Trouble in mind. I'm blue..."],["Anna","Until next time!"]]},{"g":"Уровень 1","t":"Lesson 22: Next Summer...","u":"/a/lets-learn-english-lesson-22/3397314.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/6/6f/6f09d624-a8a7-4ce8-a972-1a7bfed06679.mp4?cb=edc3fc2cc","a":"https://voa-audio.voanews.eu/vle/2016/07/25/2dc70acb-f8c2-4e93-9e8d-e3d37348d819.mp3","l":[["Anna","Washington, D.C. has four seasons: winter, spring, summer and autumn or fall. My favorite season is summer because of summer vacation!Hey, that will be a great subject for my new work assignment -- the children's show. I can teach what families in the U.S. do during summer vacation.Today, I'm planning the show with Amelia. This is the first time we are working together. I hope we can work well together. Hi, Amelia!"],["Amelia","Hi, Anna! So, what are we going to talk about on the first show?"],["Anna","I want to talk about summer vacation."],["Amelia","That will be fun! Are you going on vacation this summer?"],["Anna","No. This summer I am too busy."],["Amelia","That's too bad."],["Anna","It's okay. I can go on vacation next summer. This show will be a lot of fun too!"],["Amelia","So, Anna, what's the plan for the show?"],["Anna","First, we're going to introduce the subject. Then we can show pictures and video."],["Amelia","We can show tons of video!"],["Anna","Right! We can interview children and have guests, too."],["Amelia","Kids can ask us questions."],["Anna","Great idea! Finally, we can read the questions and tell them where to learn more."],["Amelia","Okay, let's try it!"],["Anna","Let's do it!"],["Anna","Hi there! And welcome to … Amelia, we don't have a name for the show."],["Amelia","We'll think of a name later. For now, we'll call it \"The Show.\""],["Anna","Great. Hi there! And welcome to \"The Show.\""],["Anna","Today we are going to take you on a summer vacation! You will see popular things to do on vacation!"],["Anna","One is camping. When you go camping, you cook, sleep and play outdoors!"],["Amelia","When I go camping, Anna, I like to go hiking and fishing."],["Anna","Me, too. Those are fun things to do when you go camping!"],["Anna","These people are hiking."],["Amelia","Okay, let's talk about the next vacation."],["Anna","Another popular summer vacation is going to an amusement park. At an amusement park, you go on rides and eat lots of fun food!"],["Amelia","I love cotton candy …!"],["Amelia","This show is going to be a lot of fun."],["Anna","I know!"],["Anna","This is riding a rollercoaster!"],["Amelia","Whoooo! What is the last vacation?"],["Anna","One of the most popular vacations is … going to the beach!"],["Anna","When I see that blue ocean, I want to leave Washington, D.C. immediately and go to the beach!"],["Anna","Maybe next summer."],["Amelia","But right now, it's time to work!"],["Anna","Right. Until next time..."]]},{"g":"Уровень 1","t":"Lesson 23: What Do You Want?","u":"/a/lets-learn-english-lesson-23-what-do-you-want/3413753.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/e/e7/e7759765-b3e3-4624-a927-0cc2326eb311.mp4?cb=edc3fc3cf","a":"https://voa-audio.voanews.eu/vle/2016/07/27/f5ba9389-58a1-4643-9ec4-3bbfcd8c96e6.mp3","l":[["Anna","Washington, D.C. has great food from all over the world."],["Anna","Today I'm having lunch with my boss. Ms. Weaver says we're going on a trip around the world. But she knows I only have an hour for lunch! Silly woman."],["Jonathan","Hi, Anna!"],["Anna","Hi Jonathan! Hey, we are meeting Ms. Weaver for lunch at noon, aren't we?"],["Jonathan","Yes."],["Anna","What time is it now?"],["Jonathan","11:50."],["Anna","11:50! We have to go!"],["Anna","So, where is this world food restaurant?"],["Caty","We're not eating at a restaurant."],["Anna","Where are we eating?"],["Caty","We are eating at... food trucks!"],["Anna","Food trucks … awesome! What's a food truck?"],["Caty","These are food trucks!"],["Anna","Wow!"],["Jonathan","Whoa!"],["Caty","Okay, Jonathan, you will buy the first dish. Here is $10. Surprise us!"],["Jonathan","Okay, I'll be back in 15 minutes."],["Anna","What country do I want to visit?"],["Caty","Anna, you pick the second country. Here is $10."],["Anna","I want chicken."],["Caty","The food truck, over there, has great chicken."],["Anna","Awesome!"],["Caty","After you buy your food, meet me here."],["Jonathan","Excuse me, I'll have the shrimp."],["Jonathan","Oh, you're out of shrimp. Okay, I'll have the beef then."],["Anna","Hello. I want the chicken dish."],["Truck worker","We're out of chicken."],["Anna","You're out of chicken."],["Worker","Yep."],["Anna","I'll try another food truck. Thanks!"],["Worker","You're welcome."],["Jonathan","Okay, here is your change. The dish is $7. So, here is 1, 2, 3 dollars back from your 10."],["Caty","Great."],["Jonathan","Where's Anna? Is she dancing by that food truck?"],["Caty","Yes. Yes, she is."],["Anna","Ms. Weaver, here is your change. The dish costs $5. So - $5 back."],["Caty","Thanks, Anna. But where is the food?"],["Anna","I'm eating it. The Peruvian chicken is delicious! Try some!"],["Caty","Well, we still have $8! What do you want now?"],["Anna","We can buy dessert!"],["Caty","I'll buy dessert."],["Anna","In Washington, D.C., you can travel around the world … with food trucks! And it does not cost a lot."],["Anna","Until next time!"]]},{"g":"Уровень 1","t":"Lesson 24: Yesterday Was Amazing!","u":"/a/lets-learn-english-lesson-24-yesterday-was-amazing/3439164.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/2/24/240be8a1-701d-4fd2-b6f0-5fa9dda5d188.mp4?cb=edc3fc52e","a":"https://voa-audio.voanews.eu/vle/2016/07/29/7202578e-98dd-4e93-8a9b-166c72f520ea.mp3","l":[["Anna","Yesterday was the most amazing day. I want to tell my friend back home about it. So, I am writing her a letter!"],["Anna","Dear Penelope,"],["Anna","I said, \"Yesterday started like a usual work day.\""],["Anna's voice","I was at work. And I wanted a break. So, I walked and walked … and walked. Then, I saw something! It was a festival -- a big festival!"],["Anna","It is the Smithsonian Folklife Festival."],["Anna's voice","Yes. It was the Smithsonian Folklife Festival. Every year the festival shows different cultures. This year one of the cultures was the Basque culture."],["Anna","I am dancing a traditional Basque dance."],["Anna's voice","At the festival, I danced a traditional Basque dance!"],["Anna","They are cooking traditional Basque food."],["Anna's voice","They cooked a lot of traditional Basque food."],["Anna","They are playing a game. It's a kind of handball. What do they call it? They call it pilota!"],["Anna's voice","They played a game with their hands and a small ball. It's a kind of handball. But this game is called pilota."],["Anna","This is beautiful! This is traditional Basque art."],["Anna","They are making a traditional Basque ship. This festival is a lot of fun!"],["Anna's voice","The whole day was a lot of fun!"],["Anna","Who said that? I want to write my friends and tell them about my day!"],["Anna","… So, I wanted to tell you about my day! Please, my friend, come visit Washington, D.C. soon. There is a lot to do! Until next time … Anna."]]},{"g":"Уровень 1","t":"Lesson 25: Watch Out!","u":"/a/lets-learn-english-lesson-25-watch-out/3431138.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/3/35/35095de1-0ff5-48bf-815c-5dab66a55a2f.mp4?cb=edc3fc754","a":"https://voa-audio.voanews.eu/vle/2016/08/16/c98eed28-bb2e-4055-9d08-6f7834b85aa9.mp3","l":[["Anna","Hello from Washington, DC! This city has many monuments and memorials."],["Anna","Today I am visiting the ones built in memory of our Presidents: Washington, Jefferson, Lincoln and Roosevelt."],["Anna","I want to learn more about them."],["Anna","Hey! Watch out!"],["Dan","Sorry! I didn't see you."],["Anna","You were not looking. You should be more careful."],["Dan","I know I should be more careful. But this game is really fun."],["Anna","What kind of game?"],["Dan","You have to find things that aren't really there."],["Anna","How can you find things that aren't really there?"],["Dan","They're in your phone. See?"],["Anna","I see. It's like a scavenger hunt."],["Dan","That's right!"],["Anna","I don't have time for games. I want to learn about U.S. presidents."],["Dan","Then you should play this game! When you find an American symbol, you win points and a Fun Fact about a U.S. President."],["Anna","I have time for this game!"],["Dan","Here are the symbols that I caught: the Statue of Liberty for 20 points, Uncle Sam for 40 points and the American flag for 60 points."],["Anna","What symbol are you looking for now?"],["Dan","I am looking for the bald eagle. That is 100 points! It should be near the Washington Monument."],["Anna","This game is awesome."],["Dan","You ought to buy the app right now. It's called \"Catch Americana.\""],["Anna","Got it. Catch Americana."],["Anna","Thanks! Good luck!"],["Dan","Good luck to you too!"],["Anna","This is the Jefferson Memorial. I know that Thomas Jefferson signed the Declaration of Independence! Now, where is that symbol?"],["Anna","Here it is! My first one. It's an American flag! I won 60 points!"],["Anna","An American flag works well for Thomas Jefferson*. I see lots of American flags on Independence Day!"],["Anna","Where is my Jefferson Fun Fact?"],["Voice","In his lifetime, Thomas Jefferson wrote about 19,000 letters!"],["Anna","I did not know that. Where is the next symbol?"]]},{"g":"Уровень 1","t":"Lesson 26: This Game Is Fun!","u":"/a/lets-learn-english-lesson-26-this-game-is-fun/3457248.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/b/b9/b9ddf673-07ec-4557-b33d-37cf6315e3e3.mp4?cb=edc3fc9d6","a":"https://voa-audio.voanews.eu/vle/2016/08/21/5085086e-5053-401a-9f9c-826aabe8abcb.mp3","l":[["Anna","This is the Roosevelt Memorial. Where is the symbol?"],["Anna","Yay! I found Uncle Sam and I won another 40 points! What is the Fun Fact?"],["Voice","Franklin Roosevelt was the first to fly in a plane as president!"],["Anna","I didn't know that. This is a really beautiful memorial."],["Anna","This is the Lincoln Memorial! Where is the symbol?"],["Anna","I found it! The Statue of Liberty! Please give me my Fun Fact."],["Voice","Abraham Lincoln was a great wrestler!"],["Anna","I didn't know that. Lincoln wanted freedom for all people. So, the Statue of Liberty works well."],["Anna","And I won 20 points! Time to find the next symbol."],["Dan","Hey! Look out!"],["Anna","Sorry. Hey, it's you! Now, I should be more careful."],["Dan","That's okay."],["Anna","This game is a lot of fun. Hey, what's your name?"],["Dan","Dan. What's yours?"],["Anna","Anna."],["Dan","Like Americana!"],["Anna","Yeah, I guess so."],["Dan","Did you find any symbols?"],["Anna","Yes, I found three and won 120 points!"],["Dan","Me too. But, did you find the bald eagle?"],["Anna","No. Did you?"],["Dan","No."],["Anna","First one to find it wins?"],["Dan","Anna, look out for that tree!"],["Anna","I learned a lot about presidents with this game. But I ought to be more careful. Until next time …!"]]},{"g":"Уровень 1","t":"Lesson 27: I Can't Come In","u":"/a/lets-learn-english-lesson-27-i-cant-come-in/3457316.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/0/00/0025af70-3442-45fb-8417-f12d5592761a.mp4?cb=edc3fcb90","a":"https://voa-audio.voanews.eu/vle/2016/08/30/4b0918a8-33b1-4b9d-8d88-f54d8a1be9ea.mp3","l":[["Anna","Hello! I am sure that today, in Washington, D.C,. there are a lot of great things to do. But I am not doing any of them. I am sick. Right now, I'm going to call my boss and tell her I cannot come in to work."],["Caty","Hello?"],["Anna","Ms. Weaver, Hi. I can't come to work today."],["Caty","Why not? What is wrong?"],["Anna","Well, yesterday I felt fine."],["Anna","In the morning, I painted for hours. In the afternoon, I cut wood. Then, I built a fire."],["Caty","Anna, what do you mean? Why can't you come to work today?"],["Anna","I do not feel well. I think I'm sick."],["Caty","I'm sorry to hear that. I was sick last week, too. I had the flu."],["Anna","(sneezes) What did you do?"],["Caty","I slept a lot and I drank a lot of water. Do you have a doctor?"],["Anna","Yes, I do."],["Caty","You should call your doctor. And get lots of rest!"],["Anna","Thanks, Ms. Weaver. I'll call right now. I'm calling my doctor."],["Dr. Bennett","(to herself) Now, where does this thing go?"],["Dr. Bennett","Hello. This is Dr. Bennett. How can I help you?"],["Anna","Hello, Dr. Bennett. This is Anna."],["Dr. Bennett","Oh, Hi, Anna. How can I help you?"],["Anna","I think I'm sick."],["Dr. Bennett","Let me ask you a couple of questions. Do you have a sore throat?"],["Anna","Yes. I have a sore throat."],["Dr. Bennett","Do you have a cough?"],["Anna","Yes. I have a cough."],["Dr. Bennett","When did you start feeling sick?"],["Anna","This morning. Yesterday I felt great. In the morning I painted, for hours - in the afternoon I cut wood -"],["Dr. Bennett","Excuse me, Anna. But I don't need to know all that. Do you have a fever?"],["Anna","Oh. My thermometer says 125 degrees?! What??"],["Dr. Bennett","Yeah, that's not right."],["Anna","Oh. Wait. The thermometer was in my hot cup of coffee."],["Dr. Bennett","Please take it again, Anna."],["Anna","Okay, the thermometer says 100.5 degrees."],["Dr. Bennett","100.5 degrees is not too high. I want you to drink lots of water. Rest in bed and get lots of sleep."],["Anna","That is what my boss said to do. Um, Dr. Bennett, when can I go to work?"],["Dr. Bennett","Don't go to work for a couple of days."],["Anna","Yes! I mean, I don't want to make my co-workers sick."],["Dr. Bennett","That's right. Call me back in a couple of days."],["Anna","I will, Dr. Bennett. And thanks."],["Anna","Well, you heard the doctor – no work for a couple of days. I need water, sleep and um … lots of movies! Well, the doctor didn't say anything about movies. But it can't hurt! Until next time!"]]},{"g":"Уровень 1","t":"Lesson 28: I Passed It!","u":"/a/lets-learn-english-lesson-28-i-passed-it/3487865.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/d/d2/d2a1c2bf-0655-4eab-b4dc-60e15cd64ed9.mp4?cb=edc3fcd85","a":"https://voa-audio.voanews.eu/vle/2016/09/08/a087a1f8-4939-4f40-8612-e99605e88caf.mp3","l":[["Anna","Hello! Guess what this is? This is my driver's license! I passed my driving test!"],["Marsha","Anna, did you get your driver's license?"],["Anna","I did! But it was not easy."],["Marsha","Why? What happened?"],["Anna","Well, you know, I can drive farm equipment really well. But I was really nervous driving in Washington, D.C. traffic!"],["Marsha","Did you pass the test the first time?"],["Anna","Well…no. But I did pass the second time."],["Marsha","What happened during the first test?"],["Anna","It started fine."],["John","Okay … Anna. Is your seatbelt buckled?"],["Anna","Yes, sir!"],["John","Great. Please start the car."],["Anna","(to herself) Okay, Anna, start the car.Started the car. Good job, Anna."],["John","Why are you talking to yourself?"],["Anna","I am a little nervous. When I'm nervous, I talk to myself."],["John","You don't need to be nervous."],["Anna","Listen to that engine!"],["John","Please, stop pushing the gas pedal!"],["Anna","Sorry."],["John","Okay, when you are ready, turn."],["Anna","Great!"],["John","Not now! You almost hit that car!"],["Anna","You said \"turn!\""],["John","Look first! There were cars in the street."],["Anna","Please don't yell at me!"],["John","I'm sorry! I was afraid."],["Anna","You were yelling."],["John","Look out for that car! Brake! Brake!!"],["Anna and John","Ahhh!"],["Anna","Why is everyone honking at us?"],["John","You were driving too slow! Anna, stay on the street!"],["John","Hands on the wheel, Anna."],["Anna","What's that sound?"],["John","That, Anna, is the police."],["Marsha","That sounds awful."],["Anna","Yes, it did not go well. But, I practiced and passed the second time!"],["Marsha","Do you know where you want to take your first drive in Washington, D.C.?"],["Anna","Yes! Let's go!"],["Anna","There it is … the White House!"],["Marsha","Anna, you do know you can't drive up to the White House, don't you?"],["Anna","Yes. No. I didn't know. I guess we walk from here!"],["Anna","Sometimes you can see more of Washington, D.C. in a car. If you want to see the White House, you need to walk. Until next time …!"]]},{"g":"Уровень 1","t":"Lesson 29: A Long Time Ago","u":"/a/lets-learn-english-lesson-29-a-long-time-ago/3509519.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/4/44/4448c192-ea38-4ddd-a68b-dc1adf515180.mp4?cb=edc3fcffb","a":"https://voa-audio.voanews.eu/vle/2016/09/15/e7c6ba11-8320-4bcc-8fc5-27fa4e385e23.mp3","l":[["Anna","Hello! In Washington, D.C., there are many places that bring history to life. But people who live here often do not have time to see them. They are too busy with work -- like me. Hi, Marsha!"],["Marsha","Hi, Anna! Have a seat."],["Anna","Thanks. This was a good idea. Working outdoors is nice."],["Marsha","Um-hum, it is."],["Anna","I am tired. Today was a busy day at work. And I still have work to do!"],["Marsha","Hmm, that's too bad."],["Anna","How are you these days?"],["Marsha","I'm really busy too, Anna. Let's get to work."],["Anna","Marsha, look! That bus has a photo of Abraham Lincoln!"],["Marsha","That's an advertisement for Ford's Theatre. They have a new show."],["Anna","They have shows where Abraham Lincoln died?"],["Marsha","Yeah, it's a working theater and a museum."],["Anna","I love Lincoln. You know, Marsha, that advertisement reminds me of something."],["Marsha","Um-hum. What's that?"],["Anna","When I was a little girl … When I was a little girl … I was not like other children."],["Marsha","Um-hum, I can believe that."],["Anna's voice","I was a tall, serious child. At the playground the other children played silly games. They played with dart guns. They played on the swings, the slide and the teeter-totter. They also played ball But not me. I loved to read serious books about U.S. presidents."],["Anna","In fact, I wanted to be … don't laugh … President of the United States."],["Marsha","(laughs)"],["Anna","Stop! I know it's a silly childhood dream."],["Marsha","I'm sorry. It's not silly. Guess what I wanted to be?"],["Anna","What?"],["Marsha","I wanted to be... an astronaut."],["Anna","Really?"],["Marsha's Voice","When I was a kid, I studied the stars and planets. I wanted to fly into outer space!"],["Anna","You know, Marsha, childhood dreams are really important."],["Marsha","They are. And it's good to remember them."],["Anna","Hey! I have an idea. Let's go."],["Marsha","Go where?"],["Anna","Let's go make our childhood dreams come true."],["Marsha","We're going to the Air & Space Museum! Yes!"],["Anna","No. We're going to see a show at Ford's Theatre just like Abraham Lincoln did when he died! It's not far from here."],["Marsha","Uh huh. That is your childhood dream."],["Anna","Good point. Okay, next week, we'll come here and be astronauts."],["Marsha","Honestly?"],["Anna","Honestly."],["Anna","Tonight we are seeing a show at Ford's Theatre, where a man shot President Abraham Lincoln. This is history come to life … and a childhood dream come true! Until next time..."]]},{"g":"Уровень 1","t":"Lesson 30: Rolling on the River","u":"/a/lets-learn-english-lesson-30-rolling-river/3522798.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/c/cc/cc4d97ac-b23a-4c71-a915-205f1bac86fc.mp4?cb=edc40d53c","a":"https://voa-audio.voanews.eu/vle/2016/09/27/a8dbb32b-ada5-4441-a2d1-340924241a4b.mp3","l":[["Anna","Hello! Washington, D.C. sits on the Potomac River. This river is important to the history and culture of the city. Today, I am at an outdoor seafood market near the Potomac River. Some say it is the oldest outdoor seafood market in the United States! I am here to buy seafood. Let's see what they have!"],["Anna","Excuse me. Can you help me?"],["Pete","Sure! What do you need?"],["Anna","Pete!"],["Pete","Anna!"],["Anna","What are you doing here?"],["Pete","I work here. You know, it's not easy to be a writer."],["Anna","Yeah, I heard that. Sorry."],["Pete","But this job is great. I work outside by the river. And I can eat all the free seafood I want!"],["Anna","That is great, Pete. In fact, I am here to buy some seafood for my dinner party."],["Pete","You came to the right place. They have the freshest seafood in town. How much money can you spend?"],["Anna","I can only spend $50."],["Pete","Okay. What do you want?"],["Anna","First, I want to buy some shrimp."],["Pete","Sure thing. Follow me. How much shrimp do you want?"],["Anna","How much do I need for five people?"],["Pete","(yells to co-worker) Give her a pound of shrimp!"],["Anna","Ok, now I want to buy some crabs."],["Pete","The crabs here are delicious! They are the best because they come from the nearby Chesapeake Bay! Walk this way."],["Pete","How many crabs do you want?"],["Anna","I want a dozen crabs."],["Pete","You should get the larger crabs. They have the most meat."],["Anna","Then I want a dozen large crabs, please!"],["Pete","Is that everything you need?"],["Anna","Let's see … I have shrimp and crabs. And a friend is bringing a salad and many ears of corn-on-the-cob."],["Pete","Is that all the seafood that you need?"],["Anna","Yes."],["Pete","That'll be $49.95. Cash or credit?"],["Anna","Credit, please."],["Pete","Anna, you love to eat seafood. Did you grow up on the water?"],["Anna","No, I didn't. But I love the water. And I love being on the water."],["Pete","You know how to sail?"],["Anna","Well … this afternoon I am going on a boat."],["Pete","You are full of surprises. What kind of boat? Is it a motorboat or a sailboat?"],["Anna","It's a special boat, Pete. Well, thanks for your help. See you later!"],["Pete","See you, Anna! Wow, Anna's a sailor! Who knew?"],["Anna","Yes, rivers are important to the history and culture of Washington, D.C. And now I am part of this city's interesting waterfront culture. Until next time!"]]},{"g":"Уровень 1","t":"Lesson 31: Take Me Out to the Ball Game","u":"/a/lets-learn-english-lesson-31-take-me-out-to-the-ball-game/3535235.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/2/2f/2f34a0bc-9aad-45d3-b918-748706bad539.mp4?cb=edc40d617","a":"https://voa-audio.voanews.eu/vle/2016/10/06/81890cf1-5a16-4426-87db-fdb240c750cc.mp3","l":[["Anna","Hi, there, sports fans! Baseball is America's sport. Today, I am going to Nationals Park. It is home to Washington, D.C.'s baseball team -- the Washington Nationals!"],["Anna","Hi, Jonathan!"],["Jonathan","Hi, Anna! Where are you going?"],["Anna","I am taking a bus to a Nationals baseball game!"],["Jonathan","Don't take the bus. A taxi is faster than a bus."],["Anna","Oh, good idea. You know I love baseball."],["Jonathan","That's great. Have fun."],["Anna","In fact, I wanted to be a baseball player."],["Jonathan","Is this one of your memories? I'm really busy."],["Anna","This won't take long. I can see it now... I am at home plate. I wait for the pitch. The ball comes. I swing. It's a hit! I run to first base, second base, third base, then home plate. It's a home run! The crowd cheers! Woo hoo!"],["Jonathan","You really love baseball. Have fun at the game, Anna."],["Anna","Thanks, Jonathan.Taxi!"],["Ashley","Hi, Anna. Where are you going?"],["Anna","Hi, Ashley. I am going to see a Nationals baseball game!"],["Ashley","What time is the game?"],["Anna","7 o'clock."],["Ashley","Do you have a ticket?"],["Anna","No, not yet."],["Ashley","Anna, you should go a lot earlier than 7 o'clock."],["Anna","That is why I'm taking a taxi. Taxi!"],["Ashley","Anna, Anna, that's not a good idea. A bicycle is faster than a taxi."],["Anna","Oh, Ashley. Ashley, Ashley, Ashley. A car is faster than your bicycle."],["Ashley","In D.C. traffic sometimes a bicycle is faster than a car. And right now, there is a lot of traffic."],["Anna","Good point. But I don't have a bicycle."],["Ashley","Okay, Anna, you can use my bicycle."],["Anna","Thanks! I really want to learn how to ride one."],["Ashley","What do you mean, learn how to ride a bike? Oh, Anna! Anna, Anna!"],["Ashley","You know, Anna, the Metro is faster than a taxi and a bicycle. You ought to take the Metro. It's that way."],["Anna","Good idea."],["Ashley","OK."],["Anna","See you later!"],["Ashley","Bye, Anna!"],["Anna","Bye!"],["Anna","The Metro was a lot faster than a bus, taxi or bike. And now I'm at Nationals Park! Look at all these fans! So many people like to watch baseball. There's the ticket window. What? The tickets are sold out? Nooooooo!Nooooooo! But I really want to watch a baseball game. Does anyone have an extra ticket?"],["Fan","Next time, you should buy your ticket online."],["Anna","Thanks. Thanks a lot. It is good advice. Being early is better than being late. Until next time …"]]},{"g":"Уровень 1","t":"Lesson 32: Welcome to the Treehouse!","u":"/a/lets-learn-english-lesson-32-welcome-treehouse/3547306.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/8/8e/8e1a9678-e224-4d51-b9ac-fa05d9991d16.mp4?cb=edc40d74a","a":"https://voa-audio.voanews.eu/vle/2016/10/13/054d9504-47b3-4cc2-80d1-cb66fff404e4.mp3","l":[["Anna","Hello! Today is a big day. My first children's show is on television! Woo-hoo! I'm excited and nervous."],["Ms. Weaver","Hello, Anna."],["Anna","Hello, Ms. Weaver!"],["Ms. Weaver","Some people are going to watch your children's show. After they watch it, they'll tell me what they liked, and what they didn't like."],["Anna","Oh, dear."],["Ms. Weaver","They're in the conference room. They're in the conference room."],["Anna","Hello, everyone. I'm Anna, and thanks for coming!"],["Anna","Today you are going to watch my new show. I hope you like it"],["Anna","It's a children's show."],["Anna","This children's show is different. I hope."],["Anna","Shhh, please. The show is starting!"],["Anna","Oh, hi! Just give me one minute ….oops! Oh well. I can fix that later."],["Anna","Hello, I'm Anna! Welcome to \"The Time Traveling Treehouse!\" This is not a usual treehouse. It can time travel! That is why it's called \"The Time Traveling Treehouse.\""],["MINDY","Anna, do not forget me."],["Anna","Of course not! This is my partner, MINDY!"],["MINDY","My name means Massive Information Navigation Device, for You!"],["Anna","That means we can travel to many places and learn many things. Kids from all over the world ask us questions. We find them answers!"],["MINDY","Woo-hoo! That is right, Anna."],["Anna","MINDY, what is our first question?"],["MINDY","Layla asks us this question."],["Layla","Hello, Anna! Hello, MINDY! I'd like to know -- how do you play baseball?"],["Anna","That is a great question! MINDY, we need to find her an answer!"],["MINDY","I know that we can find it, Anna!"],["Anna","Where am I now? MINDY, now I am on a snowy mountain!"],["MINDY","That is a good place to learn how to ski."],["Anna","Yes, MINDY, but it cannot teach us about baseball! And I don't know how to ski!"],["MINDY","Sorry, Anna. Let's try again."],["Anna","Where I am now!? MINDY, I am in the ocean! An ocean cannot teach us about baseball!"],["MINDY","Please don't yell, Anna. The ocean can teach us about surfing."],["Anna","Yes, MINDY, it can teach us about surfing … and sharks! Ahhh!"],["MINDY","Anna, please wait. I need to fix my navigation device"],["Anna","MINDY, please fix it faster. And get me out of here … now!"],["Announcer","Whoa! Is Anna going to be lost forever? Next week, you can watch part two of \"The Time Traveling Treehouse!\""],["Anna","So, you liked it?"],["Coworkers","Yes!"],["Anna","Well, you can watch the ending next week!"],["Coworkers","Noooooo!"],["Anna","Don't forget to watch next week!"]]},{"g":"Уровень 1","t":"Lesson 33: Learning America's Sport","u":"/a/lesson-33-learning-americas-sport/3555047.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/0/0c/0c930ce2-1638-4d5d-a528-a4390e235a16.mp4?cb=edc40d992","a":"https://voa-audio.voanews.eu/vle/2016/10/21/f7144253-3403-4acd-9e09-9c31443113f7.mp3","l":[["Announcer","Last time on \"The Time Traveling Treehouse,\" Anna was lost, really lost. She wants to learn about baseball. But her computer, MINDY, sent her to many wrong places."],["Anna","MINDY! Help me! I am in the ocean with a shark!"],["MINDY","I will try one more time, Anna."],["Anna","Please try harder, MINDY!"],["Anna","Now, where am I? I am at a playground with a baseball field! Yes! I can teach children about baseball here! MINDY, MINDY, it took you a long time. But you did it!"],["MINDY","Thanks, Anna. Give me a call when you find the answer."],["Anna","Okay. Come with me. Let's learn how to play baseball! This is a baseball field. This is a pitcher's mound. This is first base! This is second base! This is third base! This is home plate!"],["Anna","To play baseball, you really only need a bat, a ball and a glove. Each team has many players."],["Anna","First, the pitcher pitches the ball to the batter. The batter bats the ball. Then, the runner runs to first base."],["Anna","Each time a batter bats, the runners run around the bases. Each time a runner runs across home plate, they score a run! There are nine innings in a game. The team with the most runs at the end of nine innings wins the game!"],["Anna","MINDY, MINDY, we found the answer! It's time to return to the treehouse."],["MINDY","Good job! That was fast."],["Anna","Yeah, time travel is so silly. Thanks, goodbye. Bye, thank you."],["Anna","Hello, MINDY? Are you there?"],["MINDY","Hello, Anna."],["Anna","MINDY, I want to go to China! Until next time …"]]},{"g":"Уровень 1","t":"Lesson 34: What Will I Do?","u":"/a/lets-learn-english-lesson-34-what-will-i-do/3566043.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2016/10/5/58/58320812-fc3c-4304-9a00-f2a54f99bc1a_mobile.mp4?cb=edc40e3aa","a":"https://voa-audio.voanews.eu/vle/2016/10/26/a9095f28-b489-4110-98fd-7ce6be485793.mp3","l":[["Anna","Hello! Halloween is very popular in the United States."],["Anna","Children trick-or-treat. They ask people for candy. Children and adults wear costumes and go to parties!"],["Anna","In fact, there is a Halloween party tonight. I need my friend, Genie. Genie!"],["Anna","Hi!"],["Genie","Hi, Anna! What do you need?"],["Anna","Tonight, there is a Halloween party."],["Genie","I love Halloween! Are you going?"],["Anna","I might go. I might not go. I don't have a costume. Can you help me?"],["Genie","Dress as a genie!"],["Anna","Great idea! I can do a genie trick like read minds!"],["Genie","Anna, be careful. Things might go wrong."],["Anna","What can go wrong?"],["Genie","Okay."],["Anna","Hey, look! I'm a genie! This is going to be fun!"],["Genie","Remember, Anna. Be careful!"],["Anna","Don't worry, Genie! I will!"],["Rebecca","Excuse me, are you really a mind reader?"],["Anna","I might be."],["Rebecca","Okay, tell me what I am thinking."],["Anna","Sure! First, what do you do?"],["Rebecca","I study. I'm a junior in college."],["Anna","What do you study?"],["Rebecca","I study journalism."],["Anna","Okay. Wait. You are thinking … you will graduate from college in about one year."],["Rebecca","Well, yeah. That's the plan. I told you, I'm a junior in college."],["Anna","Right, um, wait. There's more. You are thinking … you might get a job writing the news."],["Rebecca","I MIGHT get a job writing the news? I MIGHT! That means I might not. And I'm studying really hard."],["Anna","No, no, no, no. Uh, no, you will! You WILL get a job writing the news."],["Rebecca","I will?"],["Anna","You will."],["Rebecca","I will. I think."],["Anna","'Bye. Happy to help!"],["Kaveh","Can you really read minds?"],["Anna","I might."],["Kaveh","Well, today, I will ask my girlfriend to marry me. What am I thinking?"],["Anna","Wait. Wait, you are thinking... you might have a wedding very soon!"],["Kaveh","Might? MIGHT? She won't say \"no,\" will she?"],["Anna","No, no! She WILL say \"yes\"!"],["Kaveh","I will have a wedding, won't I?"],["Anna","You will. You will!"],["Kaveh","Thanks. I think."],["Anna","Good luck!"],["Anna","This is hard. Genie! Genie!"],["Genie","Anna, what's wrong?"],["Anna","I don't want to be a genie for Halloween. I might not go to the party."],["Genie","Of course you will go. I have another costume for you!"],["Anna","I'm a rock star! You read my mind!"],["Genie","No. You told me you like rock music."],["Anna","Oh, right. Well, I love it!"],["Genie","Have fun, Anna!"],["Anna","Thanks, Genie!!"],["Anna","I am ready for the Halloween party! But I am not going to read minds. I might play some rock music! Or I might not. Until next time …"]]},{"g":"Уровень 1","t":"Lesson 35: Let’s Make Dinner!","u":"/a/lets-learn-english-lesson-35-lets-make-dinner/3571922.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/9/96/961080a9-4397-411e-a79f-dfa874e4c5ca.mp4?cb=edc43ab4c","a":"https://voa-audio.voanews.eu/vle/2016/11/02/0c67a47c-b66d-4d36-85f5-41dca2d12bde.mp3","l":[["Anna","Hi there! Washington, D.C. has many fun places to eat. But, sometimes it's more fun to cook. In fact, tonight Marsha and I are cooking for friends. Well, she is cooking. I am doing the shopping."],["Marsha","Hi, Anna. Do you have the shopping list?"],["Anna","Yes, I told you: I have the shopping list. Can you hear it?"],["Marsha","Okay, good. I hear the list. Anna, please buy all the ingredients on the list."],["Anna","Yes, Marsha, I will."],["Marsha","And do not spend too much time shopping."],["Anna","No, Marsha, I won't. See you later."],["Anna","Sometimes, Marsha worries too much. I love shopping! And, I did not spend too much money. Oh, no! But I did spend too much time! I have to return home now!"],["Marsha","Anna, what took you so long? Our guests will be here soon!"],["Anna","Don't worry, Marsha. I bought everything on the list."],["Marsha","Let me see. You bought a bunch of bananas, a box of pancake mix, a bag of coffee … Anna, this is all wrong!"],["Anna","What do you mean wrong? I bought a jar of peanut butter and a loaf of bread … no, wait … two loaves of bread."],["Marsha","Anna, these are the wrong ingredients!"],["Anna","These ingredients are all on the list! I took this list from the counter."],["Marsha","Anna, this is the shopping list for breakfast. I said, take the shopping list - on the refrigerator - for dinner!"],["Anna","Marsha, there was no shopping list - on the refrigerator - for dinner!"],["Marsha","Oh no! It's on the floor!!"],["Marsha","What are we going to do?"],["Anna","When do our guests arrive?"],["Marsha","They arrive in 30 minutes!"],["Anna","I can fix this. Do you trust me?"],["Marsha","Do I have to?"],["Anna","Yes."]]},{"g":"Уровень 1","t":"Lesson 36: I Can Fix This!","u":"/a/lets-learn-english-lesson-36-i-can-fix-this/3568962.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/6/6f/6f867a3f-a8f1-4a89-b18c-892f85e60d35.mp4?cb=edc43ad5a","a":"https://voa-audio.voanews.eu/vle/2016/11/14/65b768cd-1b20-4074-beb4-3279d8f8e715.mp3","l":[["Anna","Last time on Let's Learn English, Marsha and I invited friends to a dinner party but I shopped with the wrong list. Guests are coming soon. Marsha is worried but I have a plan. Let's see what it is."],["Anna","I just need a couple of ingredients. Marsha, please hand me the flour."],["Marsha","Anna, where is the flour? It's not in the cabinets."],["Anna","I put the flour inside the refrigerator."],["Marsha","Why?"],["Anna","It's cold and dry in the refrigerator. See, it says: \"Put in a cold, dry place.\" Okay, now, Marsha, please hand me the eggs."],["Marsha","Anna, where are the eggs?"],["Anna","The eggs are inside the cabinet under the sink."],["Marsha","Anna, why are the eggs in here?"],["Anna","On the farm, we always put the eggs there. How else can the chickens see them? Okay. You clean the living room. I will make dinner."],["Marsha","What are you going to make with these ingredients?"],["Anna","I have a plan."],["Marsha","Okay, the apartment is clean. The kitchen is not. What are you cooking?"],["Anna","I made my favorite recipe: peanut-butter-banana pancakes!"],["Marsha","You made breakfast."],["Anna","Yes! I call it let's-eat-breakfast-for-dinner dinner!"],["Marsha","Anna! Mmm! Hey, this tastes good! Anna, you made it work!"],["Anna","That's our guests!"],["Marsha","I'll answer the door."],["Anna","I'll finish here."],["Anna","Like I said, sometimes Marsha worries too much. When something goes wrong with your plan, just change the plan! Till next time!"]]},{"g":"Уровень 1","t":"Lesson 37: Let's Agree to Disagree","u":"/a/lets-learn-english-lesson-37-lets-agree-to-disagree/3574029.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/4/46/4619beb2-18dd-45cb-a55a-42989d3beeec.mp4?cb=edc43aeeb","a":"https://voa-audio.voanews.eu/vle/2016/11/17/a0f8f1e0-4d24-425c-8db5-0322d86f3de9.mp3","l":[["Anna","You know, I am from the country and sometimes I miss it. But I really like life in the city! I love the city. Oh, look. Someone lost a bag. Maybe it's theirs. Excuse me. Is this bag yours?"],["Dr. Jill","No. It's not mine. It might be hers."],["Anna","Excuse me. Is this bag yours?"],["Sarah","No. It's not mine. It might be his."],["Anna","Thank you. Hello. Is this bag yours?"],["Phil","Yes, that's mine. These are all my travel things. Thank you, thank you!"],["Anna","Are you okay? You seem... nervous."],["Phil","Well, this is my first visit to Washington, D.C. I'm from a small town in the country. I feel a little lost."],["Anna","I am from the country too! And I understand. When I first came here, I felt lost... all the time."],["Phil","So, do you like living in the country or in the city?"],["Anna","I like to live in the city."],["Phil","Why?"],["Anna","The city is exciting! It has more culture than the country. There are many museums and restaurants. Every night, there is theater and music. And, there are more jobs. That is why I'm here."],["Phil","Well, I agree. There is more culture in the city and there might be more jobs. But the country has more nature! It's peaceful and beautiful. There are more trees and mountains. The air is clean. You can go hiking and camping. The city is not beautiful. It's noisy and dirty."],["Anna","I disagree. I think all the different buildings are beautiful. And I like to watch all the different people."],["Phil","That's another thing that is different. People in the country are friendly. They always say \"hello!\" Here, no one says \"hello.\" I think city people are rude."],["Anna","Well, I agree. Country people are friendly. But I don't think city people are rude. I think they're just busy."],["Phil","That's a good point."],["Anna","Look at me. I live in the city and I said \"hello\" to you."],["Phil","But you are from the country."],["Anna","I have an idea. Let's say \"hello!\" to people -- to many people!"],["Phil","What? Why?"],["Anna","Well, if we say \"hello,\" maybe they will say \"hello\" to other people... Hello!"],["Anna","Come on. Let's go say \"hello\" to people."],["Anna","We don't have to agree with people. They have their opinions. We have ours. And as we like to say, you can always agree to disagree! Until next time...! Hello!"]]},{"g":"Уровень 1","t":"Lesson 38: She's My Best Friend!","u":"/a/lets-learn-english-lesson-38-shes-my-best-friend/3591967.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/1/1d/1d74e0d6-82c0-4782-bebd-e5bbd65a8057.mp4?cb=edc43b190","a":"https://voa-audio.voanews.eu/vle/2016/12/01/7b357de6-9247-45fd-8e49-77197599f6d5.mp3","l":[["Anna","Hello! I have great news. My best friend from my hometown is coming here -- to Washington, D.C.! I can't wait to catch up with her! Oh! I gotta go. Her train arrives in 10 minutes!"],["Anna","Penelope!"],["Penelope","Anna! I am really happy to see you!"],["Anna","Me too! How was your trip?"],["Penelope","It was fine."],["Anna","Let me help you with your bags."],["Penelope","I'm really excited to be in Washington, D.C.! I can't wait to hear about … everything!"],["Anna","I have so much to tell you. Let's go to my apartment. We can talk over a hot cup of tea."],["Penelope","I love your apartment building, Anna. Is your rent expensive?"],["Anna","Well, I have a roommate. So, we split the rent."],["Penelope","Oh, that's right. Is your roommate nice?"],["Anna","Marsha is the nicest person I know in this city. Sometimes she worries too much. And she says I'm the messiest cook she knows. But we are great roommates."],["Penelope","So, Anna, is it hard to make friends in D.C.?"],["Anna","At first it was hard. But now, Marsha is a good friend. And there's Pete. Of all the people I know in D.C., Pete is the most serious and also the silliest."],["Penelope","He sounds … interesting."],["Anna","Jonathan and Ashley are two other good friends of mine. In the city, they are the friendliest people I know. They always help me when I need it."],["Penelope","Your friends sound great! So, tell me about your job."],["Anna","I love my work! I make a children's show called the \"Time Traveling Treehouse.\""],["Penelope","Anna, that is the best job for you! Do you remember when we were little? We played in that old treehouse behind my family's house for hours!"],["Anna","I forgot about that! We thought it really time traveled! It is really good to talk to you. New friends are good. But old friends are the best."],["Penelope","I know. Our hometown isn't the same now. You are not there."],["Anna","No crying. No crying. Penelope, why don't you move here and live with me and Marsha?"],["Penelope","Anna, I can't leave our hometown. You forget -- I love my job, too."],["Anna","I didn't forget. You are the most famous turkey farmer I know!"],["Penelope","Thanks, Anna."],["Anna","Come on. Let's go eat dinner at one of D.C.'s most famous restaurants."],["Penelope","Awesome!"],["Anna","I have a great apartment. I love my work. And I have awesome friends. I am the luckiest woman in Washington, D.C."],["Anna","Until next time?"]]},{"g":"Уровень 1","t":"Lesson 39: It’s Unbelievable!","u":"/a/lets-learn-english-lesson-39-its-unbelieveable/3598920.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/0/08/088b68c0-58b8-46dc-9796-d6c542e3d44e.mp4?cb=edc43b603","a":"https://voa-audio.voanews.eu/vle/2016/12/02/5fd0aa74-ef38-40c2-85fb-47f536c14e28.mp3","l":[["Anna","Hello! Winter weather in Washington, D.C. can be really windy. And wind messes up my hair. It is really windy today. Look at my hair. Will it be windy this weekend? I'll listen to the news. I am tired of my untidy hair."],["Pete","Are you tired of your untidy hair?"],["Anna","Yes. Yes, I am. And it's … uncomfortable."],["Pete","Is it … uncomfortable?"],["Anna","Yes. Yes, it is! Hey, is that … Pete?"],["Pete","Hi. I'm Pete. And I have the perfect product for you -- Hair Be Good!"],["Pete","Just spray Hair Be Good on your hair … wrap in a towel … and you are done! Hair Be Good works and it's inexpensive. One can costs only $10! So, go online and order your Hair Be Good today!"],["Anna","Hair Be Good sounds perfect! And I can trust Pete! I am buying some right now. Okay, I will order one can of Hair Be Good for $10. I'll pay with a credit card. My delivery will arrive in 2 days. Awesome!"],["Anna","It arrived! I'll use it before I go to work. Okay, Hair Be Good, make my untidy hair tidy! No, make it … fabulous!"],["Amelia","Hi, Anna."],["Anna","Hello, Amelia!"],["Amelia","Anna, you look … different."],["Anna","Thanks! I used a new product called Hair Be Good."],["Amelia","Well, it's not."],["Anna","It's not what?"],["Amelia","Good. Your hair does not look good."],["Anna","Oh, no! This is not good."],["Amelia","Why don't you go home and take care of … this."],["Anna","Good idea."],["Pete","Hi, Anna!"],["Anna","Hello, Pete."],["Pete","Is something wrong?"],["Anna","This is wrong!"],["Pete","What did you do to your hair?"],["Anna","Hair Be Good did this to my hair."],["Pete","Ah, you bought it!"],["Anna","Yes, I bought it. You said in your ad it was a perfect product. This is not perfect. This is imperfect!"],["Pete","It's unbelievable!"],["Anna","I believed your ad, Pete. It was dishonest!"],["Pete","Anna, you don't believe everything you see in ads, do you?"],["Anna","No, Pete. Just the ones with my friends."],["Pete","Your hair will be okay. Just wash it... a couple of times."],["Anna","Thanks. Thanks a lot, Pete! Here, here's your product! You should call it \"Hair Be Really, Really Bad!\" Until next time, Pete! Till next time."]]},{"g":"Уровень 1","t":"Lesson 40: The Woods Are Alive","u":"/a/lets-learn-english-lesson-40-the-woods-are-alive/3630341.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/a/ac/ac4d5f85-718e-433f-a4e6-989e842db20a.mp4?cb=edc43b8b5","a":"https://voa-audio.voanews.eu/vle/2016/12/29/b24ae633-80a3-46e9-afc8-5e2719ed1fa7.mp3","l":[["Anna","Happy New Year! Some people, at the start of a new year, make a resolution -- a promise to yourself to be better. I thought about my resolution carefully. I want to be an actor on the stage! Today I will audition for a show called \"The Woods Are Alive!\" Wish me luck!"],["Director","Next! What is your name?"],["Anna","My name is Anna Matteo."],["Director","Are you ready to audition?"],["Anna","(warms up voice) Yes."],["Director","Great. Let's begin on page 1. Here is the story. You are lost in the woods. You are searching desperately for a way out. Suddenly, you hear something."],["Director","Now, say your line."],["Anna","'What was that? Hello. Is someone there?'"],["Director","Anna, you are speaking too softly. Can you speak more loudly and a little more, um, seriously?"],["Anna","Yes, of course I can. 'What was that? Hello. Is someone there?' Is that loud enough?"],["Director","Yes, that is loud enough. Let's turn to page 25. In this scene, you are moving slowly and quietly through the woods."],["Director","Anna. Anna! You are walking quickly and loudly. Walk slowly and quietly."],["Anna","I'm walking slowly and quietly. I am walking…"],["Director","Anna. Anna. You don't need to say \"slowly\" and \"quietly.\" Alright, let's try the last scene. Turn to page 48. I say my line first, then you say your line."],["Director","'You will never get out of these woods alive! Mwa-ha-ha-ha-ha Mwa-ha-ha-ha-ha!'"],["Anna","'Yes, I will.'"],["Director","Okay, Anna, you said that line -- you said that line really late. You need to say it earlier."],["Anna","Sorry. Sorry. Let me try again."],["Director","'You will never …'"],["Anna","'Yes, I will.'"],["Director","'… get out of the woods alive.'"],["Anna","I was too early, wasn't I?"],["Director","Yes. Yes, you were."],["Anna","Director, how am I doing?"],["Director","You know, Anna. I think that I have the perfect part for you."],["Director","The costume is in the back. Please go try it on."],["Anna","Awesome! (Anna returns as a tree.)"],["Director","Oh, Anna, that fits you perfectly!"],["Anna","I'm a tree. I'm a tree in … \"The Woods Are Alive!\" Yes!"],["Anna","My new year is starting awesomely! Excuse me, Director! I have a great idea for my tree. Oh, wait! Until next time!"]]},{"g":"Уровень 1","t":"Lesson 41: Teamwork Works Best With a Team","u":"/a/lets-learn-english-lesson-41-teamwork/3635015.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/b/bb/bb252e9e-dc85-4281-9e24-133f65290c88.mp4?cb=edc43bac9","a":"https://voa-audio.voanews.eu/vle/2017/01/05/64e9d749-33ff-4b41-934d-9f44e81cfea0.mp3","l":[["Anna","Hi. I am walking to work. Today my boss will tell me what she thinks of my work. Is it good? Or is it bad? Okay, time for work. I am going right now. Okay, okay, I'm going!"],["Ms. Weaver","Anna, hello."],["Anna","Hello."],["Ms. Weaver","Sit down. As you know, at the start of a new year we have a work review."],["Anna","Yes. It's time for mine."],["Ms. Weaver","Yes. Anna, this chart shows the audience of The Time Traveling Treehouse. If you look at it, you will see something bad. Your audience is going down, down, DOWN!"],["Anna","Ms. Weaver, I think the chart is upside down."],["Anna","Here, let's flip that around. Now, it's right-side up."],["Ms. Weaver","Oh. If you look at this chart, you will see something good. Your audience is big."],["Anna","Good!"],["Ms. Weaver","But not big enough."],["Anna","Not good."],["Ms. Weaver","I want to see these numbers go up, and up, and UP!"],["Anna","How?"],["Ms. Weaver","I have something -- idea posters!"],["Anna","(whispers) Idea posters."],["Ms. Weaver","You really ought to think seriously about them. I like this one. Please read it."],["Anna","\"If at first you SUCCEED; you will be a success.\" Well, it's a cute cat."],["Ms. Weaver","Here's another one. I like it."],["Anna","\"WORKING HARD looks hard because it really is hard.\" I see. It's another cute cat."],["Ms. Weaver","This is my favorite."],["Anna","\"TEAMWORK works best with a team.\" A team of cats. Look at all those cats!"],["Ms. Weaver","So, Anna, do you understand what I want?"],["Anna","Yes, Ms. Weaver. I understand."],["Anna","Okay, team. There is a problem in the Treehouse."],["Amelia","Problem? What's the problem?"],["Anna","Our audience is big."],["Bryan","But that's a good thing."],["Anna","No, it is not big enough."],["Anna","Please don't worry. I know what Ms. Weaver wants. Here's the plan. (whispers)"],["Bryan","Is that what she wants?"],["Amelia","Are you sure?"],["Anna","Yes. Let's get to work!"],["Anna","Good job, team. This is exactly what Ms. Weaver wants!"],["Anna","Welcome to The Time Traveling Treehouse! Today you will learn about a very popular pet … cats!"],["MINDY","Anna. Did I give you enough cats?"],["Anna","I don't know, MINDY. I think we need more cats!"]]},{"g":"Уровень 1","t":"Lesson 42: I Was Minding My Own Business","u":"/a/lets-learn-english-lesson-42-i-was-minding-my-own-business/3647264.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/e/e7/e7e1cf42-37e1-440d-b1fa-de80ec67283d.mp4?cb=edc43be94","a":"https://voa-audio.voanews.eu/vle/2017/01/12/51393a0f-7412-4703-8f47-866cfd57955c.mp3","l":[["Guy","Hello. I'm Guy Newsman with News Channel XYZ. I'm here in Washington, D.C. at the scene of a crime."],["Guy","We are talking with this woman."],["Guy","She saw the crime during her lunch break. It looks like she hurt herself while she was trying to stop the crime."],["Guy","Tell us your name."],["Anna","Hi, Guy. I'm Anna."],["Guy","Anna, what did you see and what happened to your arm?"],["Anna","Guy, I was minding my own business. See, I work over there."],["Guy","Um-hum"],["Anna","I left work to get some lunch. Then suddenly, I heard a woman yelling. She was yelling like this... \"Help! Help!\""],["Guy","Um-hum"],["Anna","Two robbers were grabbing her bag like this. She was hitting them with her umbrella."],["Guy","Is that when you hurt your arm?"],["Anna","No. At that time, I was not fighting the robbers."],["Guy","Um-hum."],["Anna","See. I was too far away and I didn't have my own umbrella."],["Guy","So, what happened next?"],["Anna","They grabbed her bag and ran away! So, I grabbed her umbrella and ran after the robbers."],["Guy","Then that is the time that you hurt your arm?"],["Anna","No. I was yelling, \"Stop, robbers! Stop!\" She was yelling, \"Hey, come back with my umbrella!\""],["Guy","Were you afraid?"],["Anna","I had no time to be afraid, Guy. Well, I had time while I was resting on a bench. I had a lot of time."],["Guy","Then what happened?"],["Anna","The robbers got on a bus. So, I ran after the bus."],["A VO","While I was running, I tripped and fell."],["Guy","And that is the time that you hurt your arm?"],["Anna","No. While I was lying on the ground, someone stepped on my arm!"],["Guy","Ouch. That's too bad."],["Anna","Yeah. And they didn't apologize. Well, then the robbers got themselves kicked off the bus."],["Guy","Why?"],["Anna","They didn't pay. You've got to pay when you get on a bus. The police came and took them away."],["Guy","And that's when you hurt your arm!"],["Anna","No."],["Guy","Then, when did you hurt yourself?"],["Anna","Well, Guy, by this time, I was feeling very hungry. So, I went to my office to get a snack."],["Guy","You hurt your arm in a vending machine buying a bag of chips?"],["Anna","I was really hungry and the bag was stuck. I had to -"],["Guy","That's all from News Channel XYZ. This is Guy Newsman saying goodbye."],["Guy","Okay, we have to find ourselves another story, guys."],["Anna","Until next time! Hi Mom!"]]},{"g":"Уровень 1","t":"Lesson 43: Time for Plan B","u":"/a/lets-learn-english-lesson-43-time-for-plan-b/3666458.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/9/9b/9b044a43-6f81-4c9d-9724-f48a5e1a6da7.mp4?cb=edc47a5ce","a":"https://voa-audio.voanews.eu/vle/2017/01/18/b97c84f3-f68d-4b35-bf71-9c369a107e82.mp3","l":[["Anna","Hey there! Tonight, I am teaching my ukulele class. It is far away. So, I am going to ride the Metro. Oh, no! I lost my wallet! It has my Metro card, my credit card and my money! Oh, no!"],["Anna","It's times like this I remember my father's important words. He said, \"Anna, never … \" No wait, \"Always have emergency money.\".\" (Anna pulls an envelope out of her bag and looks inside) It's empty. Time for Plan B. ‘Extra Emergency Money.' (Anna pulls another envelope out of her bag and looks inside)"],["Anna","No! It's empty too! Anna, it's time for Plan C."],["Anna","Hi, Marsha!"],["Marsha","Hi Anna. What's up?"],["Anna","I'm stuck downtown without any money. Would you be able to come downtown? Please?"],["Marsha","Anna, I can't. I'm too busy. I have to give a big presentation in one hour. Sorry!"],["Anna","That's ok. Good luck with your presentation!"],["Marsha","Thanks!"],["Anna","Time for Plan D."],["Anna","Hi, Jonathan! How's it going?"],["Jonathan","Hey, Anna. Things are great. What's up?"],["Anna","Well, I was wondering if you could give me some money."],["Jonathan","What?"],["Anna","See, I lost my wallet and I'm stuck downtown and I --"],["Jonathan","Anna, I wish I could. I'm at the airport with my mother. Her flight leaves in two hours."],["Anna","That's okay. Tell your Mom to have a nice trip!"],["Jonathan","I do wish I could help. Thanks."],["Anna","'Bye."],["Anna","This is serious. Time for … Plan E."],["Ashley","Hello."],["Anna","Hi, Ashley! What are you doing?"],["Ashley","Oh! Hi Anna!"],["Anna","(Anna hears a child crying through the phone.) Ashley, I was wondering, uh, would you be able to come downtown? And could you give me $20?"],["Ashley","Anna, I can't."],["Anna","I'll pay you back the money. I promise."],["Ashley","Anna, I'm not worried about the money. I'm babysitting. (off-camera to niece) That was very, very, bad!"],["Anna","Well, losing your wallet is bad, but it's not the end of the world, Ashley."],["Ashley","I was talking to my niece, Anna."],["Anna","Well, thanks anyway, Ashley!"],["Ashley","Good luck getting money."],["Anna","Good luck babysitting!"],["Ashley","Thanks."],["Anna","Well, Plans A, B, C, D and E did not work. Think, Anna, think. Time for Plan F."],["Anna","(singing) Won't you give, could -- Thank you very much, sir! -- would you give me money, won't you give -- Thank you very much! -- could you give, won't you give me money -- until next time! -- won't you give me money?"]]},{"g":"Уровень 1","t":"Lesson 44: Making Healthy Choices","u":"/a/lets-learn-english-lesson-44-making-healthy-choices/3688552.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/1/1b/1b5c7537-8259-49ea-870c-abec2a1b94d1.mp4?cb=edc47a83a","a":"https://voa-audio.voanews.eu/vle/2017/01/30/e8edcdf8-a252-41eb-af50-d1337bbb614f.mp3","l":[["Anna","Hi there, Ashley!"],["Ashley","Anna! Hi! Where are you going?"],["Ashley","What was that?"],["Anna","I'm hungry. When I'm hungry, I only want to eat junk food! But I know I should eat healthy food. So, I fight with myself. One side says, ‘You should eat healthy food.' The other side says, ‘But I want to eat junk food!'"],["Ashley","Well, Anna, go to the Giant supermarket. You should be able to find all kinds of food there - for all of you."],["Anna","Good idea, Ashley. See you later!"],["Ashley","'Bye, Anna."],["Anna","Wow! This supermarket is huge! Look at all of these fruits and vegetables! I should eat more vegetables."],["Healthy","Good idea, Anna. You must eat more vegetables … like celery!"],["Junky","Celery?! Do you know what the web says about celery?"],["Anna","No, what?"],["Junky","\"Celery is 95 percent water - 100 percent NOT ice cream. I love the web!\""],["Healthy","No, you are!"],["Junky","No, you are."],["Anna","Will you two please be nice to each other? It is important to eat healthy foods. But, a little junk food will not kill me. Hmm, ice cream. Ice cream does sound good."],["Junky","Take this cart to the frozen food aisle!"],["Healthy","No wait, go back! Go back! We forgot fruit. Go back!!"],["Anna","Okay, we are in the frozen food aisle!"],["Junky","Mmm, ice cream!"],["Healthy","Mmm, frozen peas!"],["Junky","Nobody says, ‘Mmm, frozen peas. They say, ‘Mmm, ice cream!"],["Healthy","Mmm, frozen peas!!"],["Junky","Mmm, ice cream!!"],["Anna","I am not going to tell you two again! Stop fighting!"],["Anna","I smell fresh bread! I love the smells of a bakery!"],["Healthy","Oh, Anna, let's buy a fresh loaf of whole wheat, organic bread!"],["Junky","You don't have to buy bread. Buy some donuts, Anna!"],["Healthy","You mustn't buy donuts. They are only fat and sugar."],["Junky","Exactly! You know, you are really no fun at all."],["Healthy","And you must think having high cholesterol is fun."],["Junky","Everyone likes donuts! That is why you don't have friends!"],["Healthy","And that is why your cholesterol is so high!"],["Junky","My cholesterol is none of your business!!"],["Healthy","And I have lots of friends!!"],["Anna","Stop it! Stop it! Stop it! I am sick and tired of the both of you!!"],["Anna","I know what you two need!"],["Junky","Anna! What are you doing?"],["Healthy","Put me down!"],["Anna","You two need to cool off!"],["Anna","I am going to go buy my healthy food and my junk food! Good bye!"],["Anna","Until next time …"],["Note","\"Healthy\" and \"Junky\" are Anna's thoughts about what she should eat."]]},{"g":"Уровень 1","t":"Lesson 45: This Land is Your Land","u":"/a/lesson-45-this-land-is-your-land/3710209.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/6/64/646ddd6d-a051-4cd9-b694-21a0f69a073a.mp4?cb=edc47a9cd","a":"https://voa-audio.voanews.eu/vle/2017/02/07/1fb535dc-77e2-4e0e-930e-b50fab4e45cd.mp3","l":[["Anna","You know I love Washington, D.C. But I want to see more of the United States. My roommate Marsha and I will be on vacation at the same time. So, we are going on a road trip together!"],["Marsha","Hi!"],["Anna","I packed my bags and I am ready to go!"],["Marsha","Did you make a list of all the places you want to see?"],["Anna","I did. I want to see New York City and the Statue of Liberty!"],["Marsha","And I want to see Mount Rushmore!"],["Anna","(Anna writes) Mount Rushmore."],["Marsha","And don't forget the Grand Canyon!"],["Anna","(Anna writes) Let's not forget California's redwood forest! There are so many places to see!"],["Marsha","We will be driving for a long time. So, we might get bored."],["Anna","Bored? No way! We can talk."],["Marsha","Or not talk."],["Anna","We can play word games. We can sing! You know, our trip is like that famous American song. (sings) \"This land is your land, This land is my land …\"*"],["Marsha","(sings) \"…from California to the New York island...\""],["BOTH","\"... to the redwood forest to the Gulf stream waters... this land was made for you and me!\""],["Marsha","Will we be stopping soon?"],["Anna","We won't be stopping soon."],["Marsha","I'm hungry."],["Anna","Marsha, we just left D.C.! We'll be eating lunch in about 2 hours. Can you wait?"],["Marsha","I guess."],["Anna","Here, have an apple. It's organic!"],["Marsha","Thanks."],["Marsha","Okay, we will be arriving in New York City very soon!"],["Anna","I can't wait to see The Big Apple! Marsha, look! There she is!"],["Marsha","The Statue of Liberty!"],["Anna","She is awesome!"],["Anna","Marsha, in ten minutes, guess what we'll be seeing?"],["Marsha","What?"],["Anna","The largest rocking chair in the world!"],["Marsha","No, we won't be seeing that."],["Anna","Marsha, it's on my other list -- Best Roadside Sights."],["Anna","Oh no! We littered! And my list is gone. Don't worry. I brought the book. (lifts up large book, starts reading)"],["Anna","… and that is why I am so afraid of sheep."],["Marsha","(snores a little)"],["Anna","Wow, I feel better. Marsha, you are a great listener."],["Marsha","(waking up) Where are we?"],["Anna","We will be entering North Dakota any minute now!"],["Marsha","North Dakota! We are going in the wrong direction! We want to go to South Dakota!"],["Anna","No problem. I will just exit the highway. We will be going south … in just a minute. There. Done! We're going south! Okay, we will be stopping for gas and a bathroom break in about an hour."],["Marsha","Then we will be very near to Mount Rushmore!"],["Anna","Yay! Dead presidents' heads on the side of a mountain!"],["Anna","We did it, Marsha! We made it to California! It's beautiful!"],["Marsha","And we saw everything on the list!"],["Anna","Well, we saw everything on page 1 of the list."],["Marsha","What do you mean \"page 1?\""],["Anna","Oh. Here are pages 2, 3 and 4! We'll be very busy driving back to Washington, D.C. Until next time …!"]]},{"g":"Уровень 1","t":"Lesson 46: May I Borrow That?","u":"/a/lets-learn-english-lesson-46-may-i-borrow-that/3723588.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/1/13/13db3058-03d4-44b8-910e-d344aa823b34.mp4?cb=edc47aa9c","a":"https://voa-audio.voanews.eu/vle/2017/02/22/8e170a7e-dd5c-4c9b-b214-48b68bc68f47.mp3","l":[["Anna","Have a nice day at work Marsha!"],["Marsha","You too, Anna. Oh, wait. Do you have pen and paper I can borrow?"],["Anna","Of course."],["Marsha","We are meeting at this restaurant tonight."],["Anna","What is happening tonight?"],["Marsha","Today is my birthday. We are celebrating at 7pm tonight. Did you forget?"],["Anna","Sorry, Marsha! I gotta go! See you later!"],["Marsha","Don't forget! Tonight … 7pm!"],["Anna","I forgot Marsha's birthday! And I don't get my paycheck until next week. I know. I'll make her a gift. I'll just have to borrow a couple of things."],["Anna","Amelia, may I borrow your stapler?"],["Amelia","Sure. I can lend you my stapler, Anna. But please return it. It's my favorite stapler."],["Anna","You can trust me. I understand. One time, I loaned my stapler to the wrong person."],["Anna","Thanks, Amelia."],["Amelia","Don't mention it. Bye, stapler!"],["Anna","Jonathan! Can I borrow your scissors?"],["Jonathan","Oh! Hi, Anna! What're you doing?"],["Anna","Can I borrow your scissors? Sorry to bother you."],["Jonathan","Yes, I can lend them to you, but you must return them. These scissors -- they are the sharpest scissors in the office. Watch."],["Anna","Wow, those are sharp. I will be very careful."],["Jonathan","Okay."],["Anna","And I'll bring them back tomorrow."],["Jonathan","Good."],["Anna","Thank you."],["Jonathan","You're welcome."],["Anna","Happy Birthday, Marsha! (gives Marsha a gift)"],["Marsha","Thanks, Anna! I love birthday gifts! Anna, it is … interesting. What is it?"],["Anna","Well, I know you love hats. And you need office supplies. So, this is your own office supply hat!"],["Marsha","Wow! That is a lot of office supplies!"],["Anna","Many people loaned or shared their supplies with me. Some people really love their office supplies. It has paper, pens, tape, erasers, rubber bands, binder clips, paper clips, and a light!"],["Marsha","What is the balloon for?"],["Anna","The balloon will help your friends find you. Let's try it! You get a seat in the restaurant - I will find you!"],["Anna","Sometimes all the money in the world can't buy the perfect gift. Until next time!"]]},{"g":"Уровень 1","t":"Lesson 47: How Can I help?","u":"/a/lets-learn-english-lesson-47-how-can-i-help/3737352.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/5/5c/5cb0595a-5299-4b58-bdcc-b8541b468cf3.mp4?cb=edc47abcb","a":"https://voa-audio.voanews.eu/vle/2017/03/03/8511524b-9e6f-4e73-9fa1-cd3f6b32b495.mp3","l":[["Anna","Hi, Pete. What are you doing?"],["Pete","Oh! Hi, Anna. Right now, I am fixing my car."],["Anna","How's it going?"],["Pete","It's going … not so good."],["Anna","How can I help? I was planning to visit some friends. But if you need help, I can help. I like helping."],["Pete","Anna, I can fix it myself. But thanks."],["Anna","Pete, I think I found your problem. These are spark plugs. (holds them up)"],["Anna","They start the engine."],["Pete","I know that, Anna. But there were too many spark plugs … in there. So I took out the extra ones."],["Anna","There are no extras, Pete. You need all of them. Pete, can you fix a car yourself?"],["Pete","Well, Anna, last night I was watching the online video course, \"You CAN Fix a Car Yourself!\""],["Dan","Yes, you CAN fix your car yourself!"],["Pete","And I watched the first 10 lessons. So, I think I know what I'm doing."],["Anna","How many lessons are there?"],["Pete","Four hundred and fifty."],["Anna","450! That'll take too long! If I fix your car, I'll have it running in 10 to 15 minutes."],["Anna","Where're your tools?"],["Pete","I have this. (puts a useless tool in her hand). And this. (hands her another useless tool)"],["Anna","Great. Um, I'll get my tools. I'll be back in a flash!"],["Pete","But, Anna, I don't need your..."],["Pete","… help."],["Anna","Pete, when I was a teenager, I was fixing cars -- myself. I learned from a master."],["Anna","You can trust me."],["Pete","Okay."],["Anna","Great! But we need teamwork. You sit in the car. When I say \"go,\" you start the engine."],["Anna","Okay, go! ​"],["Anna","Stop!"],["Anna","Okay, go! Huh."],["Pete","It's not starting! It's not starting!"],["Anna","What's wrong?"],["Pete","This car is stupid … stupid, stupid!"],["Anna","Pete, kicking the tires will not help."],["Pete","Well, you did not help, Anna. You did not help!!"],["Anna","Pete, Pete! Pull yourself together, man. Give me the keys. I must feel the key in the ignition and turn it myself."],["Master","Use the key, Anna. Turn the key, Anna. What are you forgetting, Anna?"],["Anna","Pete. Pete."],["Pete","What?"],["Anna","You are out of gas."],["Pete","I can't be out of gas. (looks at gauge) I'm out of gas. Sorry, Anna. I'll go get some."],["Anna","Pete. You relax. Clean your face. You can watch the rest of your online video course. It'll be faster if I go … in a flash. Until next time …"]]},{"g":"Уровень 1","t":"Lesson 48: Have You Ever ...?","u":"/a/lets-learn-english-lesson-48-have-you-ever/3753664.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/0/0a/0a211e31-97d1-4192-b60d-4de9a153000e.mp4?cb=edc47acee","a":"https://voa-audio.voanews.eu/vle/2017/03/09/d11896f1-be6c-47bf-acbc-968ebda02e96.mp3","l":[["Anna","Hello! I have lived in Washington, D.C. for a long time now. And I have done a lot. I feel that I know this city pretty well. (walks off and comes back) That's the wrong way. Where is it again?"],["Anna","(sees a tourist at a sign) Excuse me, can I help you? Have we met before?"],["Jean","I don't think so. I've just flown in from Boston. My name is Jean."],["Anna","Hi, Jean! I'm Anna. I really feel like we've met before. Anyway, how can I help?"],["Jean","I want to see an interesting museum but I don't know which one."],["Anna","I can help with that. I've lived in Washington, D.C. a long time. I think I've seen all the museums."],["Jean","Wow, thanks. So, tell me, which museums are good?"],["Anna","Well, they are all good. But they're all different. There are science museums and history museums and art and culture museums."],["Jean","I want to see an unusual museum."],["Anna","I like the Sculpture Garden. Have you ever seen sculptures in a garden? It is really artistic!"],["Jean","I have never seen a garden of sculptures! I'll write that on my list!"],["Anna","Have you been to the Museum of the American Indian? I've visited that museum many times. It is very peaceful."],["Jean","I have always liked American Indian culture."],["Jean","I'll put that on my list. (writes on list) Do you have any other suggestions?"],["Anna","Well, if you like plants, you can visit the U.S. Botanic Gardens. It's very organic."],["Jean","I have always loved plants. I'll write that on my list, too! Wow, you know so much about D.C.'s museums."],["Anna","Well, I have lived here for over a year."],["Jean","You're so lucky to live in such a beautiful city filled with so many museums and a zoo!"],["Anna","What? D.C. has a zoo?"],["Jean","Yes, and it's beautiful. You've lived here for so long and you haven't been to the zoo?"],["Anna","I've never been to D.C.'s zoo. I've never been to any zoos!"],["Jean","You have never seen zoo animals?"],["Anna","I grew up on a farm, Jean. I've known farm animals my whole life."],["Jean","But the zoo has lions (makes sound of lion roaring) and elephants (makes sound of elephant trumpeting) and zebras (makes no sound)! If you have never seen a real, live elephant, you must. They are so majestic."],["Anna","I will. I will! (writes list) There. I've written my own must-see zoo animal list!"],["Jean","Have fun at the zoo and thanks, Anna!"],["Anna","Have fun at the museums, Jean! And thank YOU!"],["Anna","This has been awesome! And I have seen every animal on my list! Jean, the tourist, helped me see more of my city. But where have I seen her before?"]]},{"g":"Уровень 1","t":"Lesson 49: Operation Spy!","u":"/a/lets-learn-english-lesson-49-operation-spy/3763537.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/a/a4/a49eae09-d90d-4d8e-a62c-0a718b8f32be.mp4?cb=edc47ae38","a":"https://voa-audio.voanews.eu/vle/2017/03/16/fdd6be45-f44e-4a0d-8231-e9cc9e710f44.mp3","l":[["Anna","It is no secret that Washington, D.C. has spies. Well, it should be a secret because spying is secret. But it's not a secret. There's even a spy museum! The International Spy Museum has created an amazing collection of spy things! And today, we will see them! My boss, Ms. Weaver, has sent me here … on a mission!"],["Ms. Weaver","Hello, Anna, are you there?"],["Anna","That's her. Yes, Agent Peacock. This is Agent Flamingo, reporting for duty."],["Ms. Weaver","Agent what? Look, Anna … I mean, Agent Flamingo, I want you to learn all you can about spying."],["Anna","You mean, collect intelligence?"],["Ms. Weaver","Yeah, it's for our new show -- \"D.C. Secrets.\""],["Anna","You've got it, Agent Peacock. The mission is safe with me."],["Ms. Weaver","Oh, okay, great. Just be back by noon."],["Anna","Agent Peacock, I'm at an air duct!"],["Ms. Weaver","Yes, spies sometimes sneak down air ducts."],["Anna","I have never snuck down an air duct. It's dark and small. I'm afraid of dark, small places."],["Ms. Weaver","You can do it, Agent Flamingo. You know, spies aren't afraid of a little darkness."],["Anna","Right. It's just an air duct -- a dark, small air duct. Okay. I'm doing it, Agent Peacock! I am sneaking down a long, dark, small air duct. I'm having a little trouble breathing."],["Ms. Weaver","Just keep going, Agent Flamingo. Think of the team!"],["Anna","Okay, I will think of the team. I'm thinking of the team, Agent Peacock! I did it! I did it! I sneaked down an air duct. That was a little uncomfortable."],["Ms. Weaver","Good!"],["Anna","What's the next mission?"],["Ms. Weaver","Umm … have you ever cracked a code?"],["Anna","No."],["Ms. Weaver","Well, go learn. Spies use their brains."],["Anna","Got it! I've never cracked a code before. Let's try, Agent Flamingo! This is really hard. I'm still trying to crack the code. I've cracked the code! I've cracked the code, Agent Peacock! My brain really hurts."],["Ms. Weaver","Great. Umm, Agent Flamingo, now answer this question: Do spies have to be in good shape?"],["Anna","\"Yes,\" Agent Peacock! Spies have to be in really good shape! Can you hear me?"],["Ms. Weaver","You're breaking up, Flamingo."],["Anna","The International Spy Museum is awesome! Agent Peacock, I completed the mission!"],["Ms. Weaver","Great. Great. Now, I have another very important mission for you."],["Anna","Got it. See you back at H.Q.!"],["Ms. Weaver","Yummy! You brought my lunch! Thanks, Agent Flamingo!"],["Anna","Mission completed. Agent Peacock!"],["Ms. Weaver","Don't ask."]]},{"g":"Уровень 1","t":"Lesson 50: Back to School","u":"/a/lets-learn-english-lesson-50-back-to-school/3771173.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/b/b7/b76551c9-f6b7-4a36-b8b8-013060087617.mp4?cb=edc47b045","a":"https://voa-audio.voanews.eu/vle/2017/04/28/c26515f8-0d7c-4fb4-9646-4dfece722172.mp3","l":[["Anna","Hello, and welcome to Georgetown University in Washington, D.C.! I am going back to school! Georgetown is the oldest Catholic and Jesuit university in the United States. The Jesuits are a religious order known worldwide for their many colleges and universities. Students have been studying here since 1792!"],["Sarah","Hey, are you finished with your report?"],["Taylor","Almost. I have been writing and re-writing since last night! The subject is really interesting to me."],["Sarah","Me too! I have been studying this topic* for a long time."],["Anna","Am I late?"],["Sarah","You're a little late. But don't worry. The professor isn't here yet."],["Anna","How long has the class been waiting?"],["Taylor","We've only been waiting for about 10 minutes."],["Anna","Oh good. Oh, no! I forgot my pencil sharpener. Excuse me, do you have a pencil sharpener I can borrow?"],["Taylor","No, sorry."],["Anna","Oh wait. I found my extra one! Whew, that was close."],["Anna","So, how long have you been studying at Georgetown?"],["Andrew","I've been studying here since 2015."],["Anna","Awesome. You know, I've been wanting to go back to school for a long time. So, here I am!"],["Andrew","Well, you picked a great school. I've been really happy here."],["Anna","Awesome. See, I've been working for several years now. So, going back to school makes me a little nervous."],["Randall","Don't be nervous. Just pay attention and do your best!"],["Anna","That is great advice. You know, I have been paying attention. But sometimes I still feel like I don't understand. Like last week …"],["Anna","What's that?"],["Jada","This is my draft."],["Anna","What draft?"],["Jada","The professor told us to bring our drafts."],["Anna","I think she said \"giraffe.\""],["Jada","No. She didn't."],["Anna","Here comes the professor."],["Dr. Jones","Hello class! Sorry I'm late, but the snow storm made getting here really difficult. I see you've been waiting very patiently. So, let's get started! Who wants to give their talk first?"],["Anna","Oh! Oh! Please, please pick me."],["Dr. Jones","Anna?"],["Anna","Who me? Sure. Thanks."],["Anna","Here is my report on \"Violins in the City.\""],["Anna","People have been looking for a solution to the problem of violins in the city. I say stop! Stop! They are not the problem! In fact, violins are part of the solution!"],["Anna","Violins create beautiful music that can fill a city with hope."],["Dr. Jones","Anna …"],["Anna","If we put a violin in the hands of every child …"],["Dr. Jones","Anna! The topic is \"Violence in the city.\" Violence. Not violins."],["Anna","Until next time …Like I was saying, many people are saying that violence in the city is a problem. A very big problem."]]},{"g":"Уровень 1","t":"Lesson 51: A Good Habit","u":"/a/lets-learn-english-lesson-51-a-good-habit/3773577.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/8/89/89e2abe4-1e50-4a83-b771-b3623fffb590.mp4?cb=edc47b17c","a":"https://voa-audio.voanews.eu/vle/2017/04/06/1f484880-f858-47b5-8e0d-37a063b34a07.mp3","l":[["Anna","D.C. is a popular city for marathons! A marathon is a long race. Many marathons raise money for charity, you know - good works. A marathon is a good fitness goal too. I want to challenge myself in a marathon and maybe win a medal! Hey, there's Ashley. Ashley! Wait for me! It's Anna!"],["Anna","Ash … ley. Ash … ley."],["Ashley","Are you okay, Anna?"],["Anna","I just ran … from over there."],["Ashley","Do you want to sit down, Anna? Do you want some water? (Anna takes the bottle and tries to return it.) No thanks. You keep it."],["Anna","Thanks. I didn't know you like to run."],["Ashley","I love running. In fact, this weekend, I will run in my first marathon."],["Anna","Me … too."],["Ashley","Really? You are running in a marathon?"],["Anna","Yeah. In a couple of days. Why do you ask … like that?"],["Ashley","What do you know about running in a marathon?"],["Anna","I know that there's a lot of running and sometimes you can win a medal."],["Ashley","How long have you been training?"],["Anna","I started today. I've been training for an hour … no, an hour and seven minutes!"],["Ashley","Anna, training a little every day is a good habit to get into. Not all at once!"],["Anna","Thanks for the advice, Ashley. But I'm running in a special race."],["Ashley","What marathon is it?"],["Anna","I don't remember the name. But the website said everyone gets a medal."],["Ashley","Okay, well, good luck, Anna!"],["Anna","Thanks, Ashley. Good luck to you, too."],["Ashley","Thank you."],["Anna","Bye!"],["Ashley","Bye, Anna!"],["Anna","See you!"],["Anna","Hello. I am here to enter the race!"],["Woman","But ma'am you can't enter the race."],["Anna","What? How am I going to meet my goal?"],["Woman","Ma'am, this race is for children. You can't run with the children."],["Anna","Children? Children. That's perfect. I just might win!"],["Woman","No, ma'am. You really can't run with the children."],["Anna","I'm sorry. Of course. I was only thinking of my goal."],["Woman","Well, you can help us with our goal, which is to raise money for sick children. Would you like to help us?"],["Anna","I've just found my new goal. And I get to wear a medal. (to child who finished race) Good job!"]]},{"g":"Уровень 1","t":"Lesson 52: Taking Chances","u":"/a/lets-learn-english-lesson-52-taking-chances/3805454.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/6/6d/6dfd5f69-746e-45bd-86b1-1dba49c23a48.mp4?cb=edc47b2ba","a":"https://voa-audio.voanews.eu/vle/2017/04/14/8259e341-9066-4896-af3d-f62d738d0948.mp3","l":[["Anna","Hello, it's Anna! I did it - Washington, D.C. is my home. Looking back over the past year, I've done so many amazing things! I have met people from all over the world. I've made many good friends. And I have a great job! And I've taken a lot of chances. And now I have some really big news! Wait for it… and 3, 2, 1…"],["Kelly","Hello and welcome to \"Around the Corner and Across the Street from the Actor's Studio!\" Many people dream of becoming actors. But very often, those dreams don't come true."],["Kelly","Well, today we will meet a woman and -- her acting career has really taken off. In fact, she acted in my play, \"The Woods Are Alive!\" Oh. She really brought the part of Tree Number 15 to life! Let's give a warm welcome to Anna Matteo!"],["Anna","Thank you. Thank you so much for having me here."],["Kelly","Please, please, sit down. Here, here, let me help you."],["Anna","Thanks. Thanks. Wow, it is great to see you again, Director Kelly!"],["Kelly","It's great to see you too, Anna. I see you are still wearing your tree costume. Does this have anything to do with your big news?"],["Anna","Yes. Yes, it does."],["Kelly","Well, Anna, please share that news with us."],["Anna","Kelly, I will be acting in three movies."],["Kelly","That is amazing! Anna, tell us more."],["Anna","Well, the first is a science fiction movie. The second is a romantic comedy. And the third is an action movie."],["Kelly","That is so great! Let me guess -- you're playing a tree in all of them!"],["Anna","Yes! This is what happened. To prepare for your play, I had to find out what it was like to BE a tree in the world. I had to find out where to eat, where to shop, where to meet people and how to get around the city."],["Kelly","Amazing. I think big things are going to happen for you, Anna. So, tell me, will you be moving to Hollywood for a career in movies?"],["Anna","No. I'll make the movies and then come back. Washington, D.C. is my home."],["Kelly","I'm sure your family is very proud."],["Anna","Yes, they are. You know, Kelly, not too long ago, I didn't feel very good about my life. I had to make a change. So, I took some chances. Sometimes I succeeded. Sometimes I failed. But I will never stop trying."],["Kelly","Well, thank you for sharing your news and so much more with us, Anna."],["Kelly","Until next time …"]]},{"g":"Уровень 2","t":"Lesson 1: Budget Cuts","u":"/a/lets-learn-english-level-2-lesson1/3960391.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/7/7a/7a055fd0-0345-41e4-b24d-37df1736f3d1.mp4?cb=edc3e694c","a":"https://voa-audio.voanews.eu/vle/2017/08/31/3bf697ff-3ef5-4d59-8dcd-52613e2e7e9d.mp3","l":[["Anna","Hum. Oh! \"Important meeting. Everyone must come.\" Well, back to work! And my boss has called a meeting. I wonder what it's about. Maybe we're all getting raises! Ooo, there's Jonathan! Maybe he knows."],["Professor Bot","Hi! I'm Professor Bot! This video is all about work. People talk about jobs and things that happen at work. Your assignment is to find as many work words as you can. Don't worry, I'll help."],["Anna","So, Jonathan, what do you think today's meeting is about? The email sounded important."],["Jonathan","Well, I have heard people in the building talking about budget cuts."],["Anna","Oh! Budget cuts? Wait, who has been talking about budget cuts?"],["Jonathan","Mark in Accounting."],["Anna","Mark in Accounting? That's one person. That's not \"people.\""],["Jonathan","I know, but Mark knows everything that goes on at The Studio."],["Anna","That is true. But wait, look at us. We shouldn't gossip. That's how rumors start. We'll just go to the meeting and see what happens."],["Jonathan","You're right. No more talk about budget cuts."],["Amelia","Budget cuts? Oh no!"],["Amelia","I just heard Anna and Jonathan talking about budget cuts."],["Kaveh","That must be what the meeting is about. When there are budget cuts, people lose their jobs."],["Amelia","Not you. You're a good reporter."],["Kaveh","And it's not you. You've done a great job as a videographer."],["Amelia","I can't go back to being a detective. Criminals scare me!"],["Kaveh","And I can't go back to being a teacher! High school kids scare me!"],["Professor Bot","Did you hear any work words? They talked about a lot of jobs. You can make the name of a job by adding an ending to a verb! Kaveh reports, so, he's a reporter. Amelia used to detect, so she was a detective. If you teach, you're a teacher. And a videographer….uh, I think you understand. Back to the story."],["Kaveh","Penelope, have you heard the news? Today's meeting is about budget cuts."],["Penelope","That's awful! What should I do?"],["Kaveh","Update your résumé. I've already updated mine. I'll see you at the meeting."],["Ms. Weaver","Hello everyone! Quiet, please. Quiet, please!"],["Ms. Weaver","This meeting won't take long. Then you can all leave."],["Ms. Weaver","What is wrong with everyone? You look like I'm going to fire you. Ha-ha-ha-ha-ha! Seriously, what is wrong with everyone?"],["Anna","Excuse me, Ms. Weaver?"],["Ms. Weaver","Yes, Anna."],["Anna","Well, everyone has been worrying about, you know … We've been worrying that you are going to fire us!"],["Ms. Weaver","I'm not going to fire any of you! No! The reason for this meeting is to tell you what a good job you've been doing and give out new assignments. Budget cuts have been happening. But only one person has lost their job -- Mark in Accounting? Now, let's talk about those new assignments."],["Professor Bot","Ms. Weaver's team is doing a good job! How did you do? Did you find all of the work words? Here's a list you can check."]]},{"g":"Уровень 2","t":"Lesson 2: The Interview","u":"/a/lets-learn-english-level-2-lesson-2/3960471.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/1/17/1706ec69-afcc-40bb-a79c-4a053b5c77ad.mp4?cb=edc3e78b9","a":"https://voa-audio.voanews.eu/vle/2017/09/05/676d9800-cee0-4a59-9e79-b9378e0061ad.mp3","l":[["Anna","Ms. Weaver is giving new assignments out. I am ready to take on anything she gives me. Well, except reporting traffic from a helicopter. Wish me luck."],["Professor Bot","I wonder what Anna's new assignment will be? Professor Bot here! While you are watching, look for phrasal, or two-word verbs. Some stay together, like \"go back\" and some can come apart, like \"give [assignments] out.\" Good luck, Anna!"],["Ms. Weaver","So, as I said at the meeting last week, I have new assignments for everyone at The Studio. Anna, you're good at asking questions. So, I want you to go back to hosting and reporting."],["Anna","That sounds great."],["Ms. Weaver","You're also a team player. So, I want you team up with someone..."],["Anna","That sounds even better!"],["Anna","That sounds... what do you mean \"different\"?"],["Ms. Weaver","Well, you are very cheerful, you're a people person. I want you to team up with someone who... isn't."],["Anna","Ms. Weaver, I will find that person."],["Mimi","Excuse me. Are you using this chair?"],["Pete","Yes."],["Anna","Pete, hi! Thanks for meeting me."],["Pete","Sure. But I don't have lots of time, Anna. I'm busy looking for work."],["Anna","Pete, you can tear these want ads up and throw them away! I have good news!"],["Pete","Anna, I was working on that crossword puzzle."],["Anna","Oh. Sorry. Sorry. Pete, forget about the crossword puzzle. I have a job offer for you!"],["Pete","I'm listening."],["Anna","My boss wants me to team up with someone to host a talk show. But the person must be different from me. So, I thought of you."],["Pete","Different from you? What do you mean?"],["Anna","I'm sorry, Pete, I don't have time right now. Here's my boss's address. Your interview is tomorrow morning at 10 am."],["Pete","But what do you mean \"different\"?"],["Anna","Just be yourself, Pete. Just be yourself."],["Professor Bot","Did you find any two-word verbs? Here's one example. Pete can throw the want ads away! Throw away is a two-word verb."],["Ms. Weaver","Thanks for coming in, Pete."],["Pete","Thanks for the opportunity, Ms. Weaver."],["Ms. Weaver","I need to find out if you have the skills for this job. And I want you to be completely honest."],["Pete","Okay."],["Ms. Weaver","First, let's talk about your personal skills. Pete, are you a people person?"],["Pete","Well, okay, sometimes I think people talk too much."],["Ms. Weaver","Pete, what work of yours are you most proud of?"],["Pete","Last year, I locked myself in a cabin and wrote a book. I didn't speak to anybody the entire time! It was the best two months of my life."],["Ms. Weaver","Okay. I think I've heard enough."],["Anna","Hey! Hey, Pete, how was the interview with Ms. Weaver?"],["Pete","Well, she said I was grumpy and not good with people."],["Anna","And …?"],["Pete","And, I got the job!"],["Anna","I knew it! Congratulations! Let's go celebrate."],["Pete","Okay!"],["Professor Bot","Did you find more two-word verbs? Here is the list."]]},{"g":"Уровень 2","t":"Lesson 3: He Said - She Said","u":"/a/lets-learn-english-level-2-lesson-3/4027340.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/e/ee/ee3e6fb5-9ea6-4f8b-88b4-c24e14fb2780.mp4?cb=edc3e7884","a":"https://voa-audio.voanews.eu/vle/2017/09/15/078ffce1-f691-4e1e-811e-058154119d2d.mp3","l":[["Anna","Today, Pete and I are meeting with a consultant who will help us with our new show. Yesterday, Pete had promised to meet me here at 8:00 am. but he did not come on time."],["Prof Bot","Uh-oh. It's bad to be late for a business meeting. But while we wait for Pete, let's talk about a new verb tense -- past perfect! You know the past tense, right? Like, \"Pete promised to meet me here at 8:00 a.m.\" Past perfect is a little different. When we talk about two things in the past, we can use the past perfect for the first event. Put \"had\" before the past participle. \"Pete had promised he would meet Anna.\" Here's your assignment: find sentences with the past perfect tense. Remember, look for \"had!\""],["Kelly","You two are late -- exactly 43 minutes late! What happened?"],["Anna","He had to get his \"special\" coffee -- SPECIAL coffee!"],["Pete","She had to feed her birds -- HER birds!"],["Kelly","Okay, I can see already that you need my help. You can't both talk at the same time. You have to take turns. Alright, Anna, you go first."],["Anna","Sure. Kelly, see, Pete and I live in the same building. So, we decided to meet at 8:00 a.m. - 8:00 a.m. to come to work together. I had waited 15 minutes when Pete arrived!"],["Anna","After Pete had wasted time waiting for coffee, we were late. I left you a message.*"],["Kelly","Hum. I didn't get that message."],["Anna","Oh. Sorry."],["Kelly","Pete?"],["Prof. Bot","Anna left a message. That's the right thing to do. Did you find some examples of the past perfect sentences? I did. Anna said,"],["Anna","\"After Pete had wasted time waiting for coffee, we were late."],["Pete","Yeah, that's not why we're late. This is why we're late: I had arrived on time at 8:00 a.m. but didn't see Anna. She was standing behind a tree. I think she was hugging it. I always walk to work. But she said that would take too long and that a scooter would be much faster. It was awful. I hated it. And it added too much time to our commute!"],["Kelly","This is what I think. You two see the same event very differently. Does this happen often with you two?"],["Pete","Yes."],["Anna","No."],["Pete","No."],["Anna","Yes."],["Kelly","Okay. This is good. This is good! It's good to see things differently. I have an idea: we will call the show \"He Said, She Said.\" For every story, you tell a different point of view."],["Anna","That is a great idea, Kelly! Pete, we are different. That's why I thought of you for this job!"],["Kelly","I think you two understand perfectly."],["Anna","Let's get to work!"],["Kelly","She named the birds? Really?"],["Pete","Yeah…"]]},{"g":"Уровень 2","t":"Lesson 4: Run Away With the Circus!","u":"/a/lets-learn-english-level-2-lesson-4-run-away-with-the-circus/4034187.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/8/8e/8e6a25fe-1336-4f85-901d-95d0dcabc112.mp4?cb=edc3e78ea","a":"https://voa-audio.voanews.eu/vle/2017/09/19/56dbc988-a70f-4417-8668-c3916f6b73e7.mp3","l":[["Anna","Hello, I'm Anna …"],["Pete","… and I'm Pete. Welcome to \"He Said,"],["Anna","… She Said\"!"],["Pete","Because there are always two sides …"],["Anna","to every story!"],["Anna","Today's show is about Circus Arts!"],["Pete","Circus? That's not an art form."],["Anna","Yes, it is."],["Pete","No, it isn't."],["Anna","Yes, it is."],["Pete","No, it isn't."],["Anna","Yes, it is!"],["Pete","No, it isn't."],["Anna","Yes, it is!"],["Pete","No, it isn't."],["Anna","Yes, it is!"],["Professor Bot","Oh dear. Anna and Pete do not agree about Circus Arts. But that's okay. Today's lesson is about agreeing and disagreeing. Let's listen to how Anna and Pete disagree or agree. Let's hope these two can agree on something."],["Anna","Today, let's run away with the circus!"],["Pete","That looks fun, Anna. But I don't think circus performers are artists. I think they're athletes with interesting skills … and costumes."],["Anna","Hmm, that is a very interesting point of view, Pete. And I completely disagree."],["Pete","Anna, Michelangelo was an artist. Rembrandt was an artist. People who swing from ropes are not artists. I know it's not easy to swing from a bar and catch someone by the hands. You have to be very athletic to do that."],["Anna","That's a good point, Pete. They are athletic. But they are called trapeze artists. Trapeze … ARTISTS."],["Pete","I hear what you're saying, Anna. I do. But where is the art? Look at these guys. They're jugglers."],["Anna","Yes, they are skilled in the art of juggling."],["Pete","They have a special skill. But are they artists?"],["Anna","Yes!"],["Pete","No!"],["Pete","They're just throwing things back and forth."],["Anna","Kind of like you and me, Pete. We're going back and forth on this issue."],["Pete","I don't think we'll ever agree on this one."],["Anna","No, but we can agree that these young people are amazing."],["Pete","Okay, yeah. We can agree on that. But, still, they are very athletic – flipping and throwing each other around."],["Anna","Yes, I agree with you on that point."],["Professor. Bot","They did it! They agreed!! Anna says she agrees that the performers are athletic. \"That's a good point, Pete. They are athletic. I agree with you on that point. \" Now look for other ways they agree."],["Pete","Anna? Anna!!"],["Anna","Sorry! Sorry! But he's an artist too. He is telling a story with his sticks and his costume."],["Pete","What story? What costume?"],["Anna","I see your point, Pete. I really do. But circus performers do more than physical tricks. Look! Look at these amazing performers!"],["Pete","I will admit -- I like their costumes."],["Anna","You know, Pete. Let's let the performers speak for themselves."],["Anna","Kate and Piper tell stories while hanging upside down on a ring!"],["Pete","Was it hard to interview them upside down?"],["Anna","I interviewed them right side up, Pete. Kate says circus performing may be athletic but it's not competitive. With most sports, you compete."],["Kate","It's an art form because like, other sports are competing. This is simply performing and having fun."],["Pete","Okay, Kate made a really good point. In athletics, there is a lot of competition. But still …"],["Anna","Here's Piper, Pete. Please pay attention, Pete."],["Pete","But, I -"],["Anna","Shh."],["Piper","Well, when you're up in the air doing circus you have to perform. And so, we learn to embody characters, and to move fluidly and gracefully … in artistic ways."],["Anna","And that …is why they are artists!"],["Pete","You're right, Anna. Oh, you're right. It's just so beautiful."],["Anna","I know. I know, Pete."],["Professor Bot","Good job you two! I'm so glad that Anna and Pete finally agree! Pete said, \" You're right, Anna.\" I agree, too. Circus arts are beautiful. Remember the website!"]]},{"g":"Уровень 2","t":"Lesson 5: Greatest Vacation of All Time","u":"/a/lets-learn-english-level-2-lesson-5-greatest-vacation/4035571.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/3/3f/3f51d054-13af-46ae-a027-e469d65197b9.mp4?cb=edc3e7908","a":"https://voa-audio.voanews.eu/vle/2017/09/27/11289bfa-a821-47fb-905b-7b4174ae0c5e.mp3","l":[["Anna","\"Do you need a vacation?\" Wow. That was the best vacation I have ever had … in my head. A beach is much better than here. I need a vacation!"],["Professor Bot","I hear you, Anna. I need a vacation too but not at the beach. Sand is not good for robots! When we compare things, we use special forms of adjectives. \"Better\" is a comparative adjective. That is used to compare two things. \"Best\" is a superlative adjective. It shows that one thing has more of...something than ALL of the others. Try to find more of these adjectives. Look for ER or EST at the end."],["Dan","NO! You can't get your money back. I don't care that it was your worst vacation ever!"],["Dan","Hello! Have a seat! Welcome to the World's Best Vacation Travel Agency!"],["Anna","Thank you and congratulations!"],["Dan","For what?"],["Anna","For being the world's best travel agency."],["Dan","Right … thanks."],["Dan","Trudy, hold my calls. I am going to sell our most expensive vacation."],["Trudy","Sure thing, Boss."],["Dan","The Mountain Getaway is good for you. It's a little pricey. But think of it -- you, on top of a mountain for seven days!"],["Anna","I'm afraid of high places."],["Dan","Of course you are. That's why our Deep Sea Adventure is better for you! It is pricier than the Mountain Getaway. Just you and the animals of the sea!"],["Anna","Shark! Shark!"],["Dan","No, there are no sharks in your dream vacation! You need the Safari Camp Out! It is our priciest vacation. But I think it's the best one for you. During the day, you'll see elephants, giraffes and lions. At night, you'll sleep out under the stars."],["Anna","Look, I think this was a bad idea."],["Dan","Sure, you can leave. But then you won't see the latest vacation technology."],["Professor Bot","Did you find all of those adjectives? Dan started with good - The mountain getaway; then he moved to better - The Deep Sea Adventure. And finally, he said the Safari Campout was the best vacation for Anna!"],["Anna","Exactly what is the \"latest vacation technology\" … exactly?"],["Dan","I'm happy you asked. Meet the Travel Max 2000!"],["Anna","Wow."],["Dan","So, tell me, how do you like to travel?"],["Anna","Well, I like travel that is cozy and romantic but still exciting."],["Dan","Great. Tell me more."],["Anna","I like traveling in a plane but not in a helicopter! Planes are a little scary but helicopters are scarier! My favorite way of traveling is by train. Ships can be the scariest! Have you seen the movie \"Titanic\"? Oh, and no horses. But I will ride a camel. And no bike tours. Biking is THE slowest AND least romantic way to travel. Excuse me, but I think the Travel Max 2000 is on fire."],["Dan","Yes, we're both on fire! We really want to sell you the most ex-, I mean, best vacation ever!"],["Anna","No, I mean it's really on fire!"],["Dan","You killed it. You killed the Travel Max 2000!"],["Anna","I am so sorry! Can I help you fix it?"],["Dan","No, no!"],["Anna","Don't cry. I know what you need -- a vacation!"],["Anna","The Safari Campout looks fun. It is the priciest. But I think you deserve it."],["Dan","No, no!"],["Professor Bot","Oh Anna. This is the smokiest lesson yet! There were a lot of comparatives and superlatives but … I can't breathe. Just go to the website to learn the best ways to use them!"]]},{"g":"Уровень 2","t":"Lesson 6: Will It Float?","u":"/a/lesson-6-will-it-float/4064553.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/7/77/776e11ee-dd39-46b3-a75c-6d56c0e4ccdd.mp4?cb=edc3e795c","a":"https://voa-audio.voanews.eu/vle/2017/10/10/4814fa95-feaa-447a-a081-499d11b1d5f3.mp3","l":[["Penelope","Anna, thanks for taking me on a tour of D.C. today."],["Anna","Sure thing, Penelope. You are new to town. And a tour is the best way to see more of the city!"],["Penelope","So, which tour are we taking – the one that goes through the city on a bus? Or the one that goes along the river in a boat?"],["Anna","Both!"],["Penelope","What? Anna, this isn't going to be one of those trips, is it?"],["Anna","No. Follow me."],["Professor Bot","In this lesson, you are going to hear lots of prepositions! What's a preposition, you ask? It's a word that shows relationships between things. Anna says they are going on a tour through the city and along the river. Through and along are both prepositions. Watch for more!"],["Anna","Well, Penelope, there's our ride!"],["Penelope","What is it?"],["Anna","It's the famous DC Ducks -- the boat with wheels! We will ride on the road and then sail on the water!"],["Penelope","Who thinks of these things?"],["Anna","I don't know. But I'm glad they do! Let's get aboard, Sailor!"],["Penelope","(looking at a brochure about the boat) Hey, did you know that this bus … um, boat was created during World War II to carry people and supplies?"],["Anna","Wow. You know, a tour is so much more interesting with Fun Facts, like that one."],["Penelope","I agree. I love Fun Facts!"],["Boy","Did I hear you say you love Fun Facts?"],["Boy","Well, I have tons of Fun Facts for this tour!"],["Anna","Penelope, where are his parents?"],["Penelope","Maybe - maybe he's the Captain's son and he helps his dad on tours!"],["Anna","Oh yeah! It would be so awesome to ride around the city in a boat all day with your dad!"],["Penelope","This is amazing, Anna. There are so many beautiful buildings along this road!"],["Anna","Hey, the Washington Monument is on the left!"],["Professor Bot","I have a Fun Fact too! Did you know that the Washington Monument was damaged in an earthquake? Whoa. Did you feel that?!"],["I heard","\"around the city in a boat,\" \"along this road and \"on the left.\" All of these are prepositions showing place. Let's watch for more places and prepositions!"],["Penelope","Look, Anna, we're across from the White House!"],["Anna","Penelope, the only thing between us and the President is the street … and a park … and a security gate.... and police officers … with guns."],["Boy","Excuse me, do you want to know a Fun Fact about the White House?"],["Boy","Inside the White House there is a swimming pool, a movie theater and 32 bathrooms!"],["Penelope","Thirty-two bathrooms! That's a lot of bathrooms!"],["Boy","I'd be happy with two. I live in a house with my mom, four sisters, two aunts and only one bathroom!"],["Penelope","Oh my! You know, Anna, we should give him a tip!"],["Anna","Of course! It is polite to tip your tour guide! Luckily, I have lots of dollar bills!"],["Penelope","That was a great Fun Fact! Here you go!"],["Boy","Thank you! I can tell you Fun Facts all day!"],["Professor Bot","Did you hear any more prepositions of place? I heard \"between us and the president\" \"inside the White House\" and \"in a house.\""]]},{"g":"Уровень 2","t":"Lesson 7: Tip Your Tour Guide","u":"/a/lesson-7-tip-your-tour-guide/4064769.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/2/26/263b6553-9229-4c76-8c64-90ea037c2a8e.mp4?cb=edc3e7990","a":"https://voa-audio.voanews.eu/vle/2017/10/17/45e008c5-648b-4275-ad2d-d3b058d199a6.mp3","l":[["Professor Bot","Welcome back! Anna and Penelope are taking a tour with DC Ducks. In this lesson, we are looking for prepositions. Listen for in, on, at, under and over - some important prepositions of place."],["Anna","Penelope, the Lincoln Memorial is coming up on your left!"],["Boy","You're going to love my Lincoln Memorial Fun Fact!"],["Anna","Oh, please tell us!"],["Boy","On a wall inside the memorial, the word \"FUTURE\" was carved wrong! They carved \"EUTURE\"!"],["Anna","Well, we all make mistakes."],["Boy","Yeah, but this mistake was carved in stone!"],["Anna","You're right. That is pretty bad. Here's another dollar!"],["Penelope","More fun facts, please! (Crossing the river) I love riding over bridges! The water looks so pretty from here!"],["Anna","Penelope, this is amazing! A minute ago, we were riding along the river, and now we're riding in the river! Awesome."],["Penelope","Hey, we're passing by the Pentagon on our right!"],["Anna","Penelope, you love riding over the water on a bridge. But I love riding under a bridge in a boat!"],["Penelope","Anna, look! An airplane is flying right over our heads!"],["Anna","Wow! This is the closest I've ever been to an airplane in flight. Well, I've been inside a flying airplane. But not outside of an airplane as it flies over my head!"],["Penelope","And now we're driving out of the water. I still can't believe this thing drives and sails!"],["Anna","I know. It's amazing."],["Boy","After we ride along these railroad tracks, you'll see my favorite part of the tour! The U.S. Treasury where they make money!"],["Professor Bot","That young man is making a lot of money, too. Did you hear these prepositions? On your left, on our right, in the river, over bridges, over our heads, over my head, on a bridge. As you watch more, look for 'inside' and 'outside.'"],["Penelope","Look, the U.S. Capitol is coming up!"],["Boy","I have a great Fun Fact about the U.S. Capitol."],["Penelope","What is it?"],["Boy","There are tunnels under the Capitol. They connect the Capitol and office buildings of lawmakers."],["Anna","I bet they built them years ago for secret reasons!"],["Boy","No. The lawmakers did not want to walk around outside in bad weather."],["Anna","Oh."],["Penelope","We're back at Union Station!"],["Boy","Do you want to know a creepy Fun Fact about Union Station? (he points to Union Station)"],["Penelope","The creepier the better!"],["Boy","Many years ago, inside Union Station, there was a funeral home!"],["Anna","A funeral home?! You mean, for dead people?!"],["Boy","Do you know another kind of funeral home?"],["Anna","No!"],["Boy","Well, I've gotta run!"],["Anna","Thanks for giving us the great tour!"],["Anna","Captain, that was awesome! And your son is a great tour guide!"],["Captain","What son?"],["Anna","Him."],["Captain","I've never seen that boy in my life! See ya, ladies!"],["Professor Bot","I learned many new Fun Facts in this lesson. Did you learn about prepositions?"]]},{"g":"Уровень 2","t":"Lesson 8: The Best Barbecue","u":"/a/lets-learn-english-level-2-lesson-8-best-barbecue/4073994.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/6/6a/6a264ff8-5d3a-4460-8d09-b56daf6ebe65.mp4?cb=edc3e79b1","a":"","l":[["Anna","Thanks for meeting me."],["Kelly","Sure."],["Anna","I'd like to get your advice on my latest project."],["Kelly","Of course. I heard you were sent to cover a big food festival that has all kinds of barbecue. So, how did it go?"],["Anna","Well, things started out great! But then, well, maybe you should watch it yourself."],["Prof. Bot","Hi English learners! Your lesson today is about my favorite food -- barbecue! Your assignment is to find passive sentences. What are those, you might ask? In passive sentences the subject receives the action!"],["Anna","Today, a Barbecue Battle is being held in Washington, D.C. This festival, which is known as one of the biggest food festivals in the United States, brings together barbecue lovers from all over the country! Barbecue is meat that is cooked over an open fire or on a grill."],["Anna","So, tell us, what is the secret ingredient in your barbecue sauce?"],["Anna","Sauces are made by the barbecue chefs themselves. Most sauces are made with a tomato sauce, vinegar, and spices."],["Prof. Bot","How many passive sentences did you find? Here is one I found:"],["Anna","There are some areas of the U.S. that are known for their tasty barbecue. The states of Texas, North and South Carolina and the cities of Memphis and Kansas City are known as the Barbecue Belt. People who are loyal to barbecue are really loyal to their favorite barbecue. That is why this festival is called a battle! Let's ask a couple of people which barbecue is best."],["Anna","This is Anna Matteo reporting."],["Anna","Kelly, people feel so strongly about barbecue. Unbelievable! So, what do you think of my project?"],["Kelly","This is what I think. There is no way that Texas has the best barbecue. I am from Kansas City and we have THE best barbecue in the whole country. My mother and father owned a barbecue restaurant, which was really famous! So, I know barbecue! Anna, I know barbecue! I know barbecue! I know barbecue!"],["Prof Bot","Oh my. Kelly knows a lot about barbecue! And you know more about passive sentences! Be sure you go to the website to learn even more! Ah! Now, if you'll excuse me.. I'm hungry"]]},{"g":"Уровень 2","t":"Lesson 9: Pets Are Family, Too!","u":"/a/lets-learn-english-level-2-lesson-9-pets-are-family-too/4074883.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/c/cd/cd492745-6461-4501-9f3e-5e59269f5655.mp4?cb=edc3e79dc","a":"https://voa-audio.voanews.eu/vle/2017/10/25/268efe48-7ad7-48da-8d13-89846a1f681a.mp3","l":[["Anna","Hi Ashley!"],["Ashley","Hey, Anna! How was your weekend?"],["Anna","It was great! I went to the D.C. State Fair."],["Ashley","I would have gone, but I was busy. How was it?"],["Anna","It was awesome! I won first place in a pet contest!"],["Ashley","But, you don't have a pet, do you?"],["Anna","Yes and no. What do you mean by \"pet\"?"],["Prof. Bot","A pet is an animal that lives with you. People love their pets. \"Ashley said, you don't have a pet, do you? She used a tag question, a small question at the end of a sentence. Let's look for more of them!"],["Anna","Look, a pet! Who's this cute little dog?"],["Ashley","Oh, right. You haven't met my dog, have you? This is Dublin."],["Anna","Hi, Dublin! Nice to meet you. He's so cute!"],["Ashley","Thanks! So, tell me about the state fair."],["Anna","Oh, there were the usual things -- fair food, cute babies, music. But there must have been a dozen different contests! And some were pretty strange."],["Anna","There was a contest to see who could spit a watermelon seed the farthest. You should have seen all the people who wanted to spit a watermelon seed! And, it was pretty fun to watch. But Ashley, the pet contests were the best. There was a pet parade. Lots of people walked with their dogs."],["Ashley","That sounds so fun. But Anna, tell me, how did you win a pet contest without a pet?"],["Anna","Okay, the closest thing I have is my pet rock."],["Anna","I know it's silly, but I've had it since I was a little girl. So, for a joke, I brought it to the fair. But then I was invited to enter the \"One-of-Kind Pet\" contest. And I won! (holds up first place ribbon)"],["Ashley","Anna, only you could have won a pet contest with a pet rock. I should have brought Dublin. He would've won a contest!"],["Anna","It's not very easy to win one of these. (shows her the blue ribbon) Does he have a costume?"],["Anna","They had a costume contest. You should have seen this little girl. She and her dog wore matching princess costumes!"],["Ashley","Dublin doesn't wear costumes."],["Anna","Does he know any tricks?"],["Ashley","Come this way. Now, watch this. (Dublin chases a toy)"],["Anna","You caught it, Dublin! And you killed it! Good dog! Ashley, he could have won the Best Catch contest! Aw, good boy! Ashley, pets are fun, aren't they?"],["Ashley","Yes. And they become part of your family. (she drinks from her Dublin mug)"],["Anna","Ashley, I think I want a dog. No. I know I want a dog!"],["Ashley","It's a big responsibility. You may want to spend time with a dog first."],["Anna","That is a great idea. But where can I find a dog?"],["Ashley","You know, Anna, I have some shopping to do. Do you want to watch Dublin for a couple of hours?"],["Anna","Yes! I would! I will take very good care of him!"],["Ashley","I know you will. Here's his leash."],["Anna","Thank you."],["Ashley","(to Dublin) Okay, I'll miss you!"],["Anna","Aw. I don't want you to be lonely. Here, Rocky can stay with you. (puts pet rock on wall)"],["Ashley","Anna, I really don't need … Okay. Thanks, Anna."],["Anna","Sure. Bye, Ashley. (to Dublin) Come on, Dublin! Bye, Rocky!"],["Ashley","Bye!"],["Prof. Bot","Anna's rock is cute, isn't it? Oh, there is another tag question! You found some more, didn't you?"]]},{"g":"Уровень 2","t":"Lesson 10: Visit to Peru","u":"/a/lets-learn-english-lesson-10-visit-to-peru/4079037.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/7/78/785c4ee4-6b29-45d8-a060-65bcfbcc1f16.mp4?cb=edc3e7a33","a":"https://voa-audio.voanews.eu/vle/2017/10/27/863aecf4-1d6a-4fe1-9789-5251ac1e0be1.mp3","l":[["Bruna","Hi, Anna!"],["Anna","Hi, Bruna! What's up?"],["Bruna","I thought we could meet for lunch today."],["Anna","I wish I could, but I can't. I have to research Peru for a story."],["Bruna","How's it going?"],["Anna","Not so good. I've been reading about Peru and listening to Peruvian music. I really want to understand Peru. I hope it's enough."],["Bruna","You should visit Peru."],["Anna","I wish!"],["Bruna","You can!"],["Anna","Bruna, I don't have the money or time to go to Peru. My deadline is tomorrow!"],["Bruna","No, I don't mean to really go there. The museum where I work is having a Peruvian festival today! …. Anna? Anna? Anna, are you there?"],["Prof. Bot","Hello again! Professor Bot here. Today we will hear about wishes and hopes. Bruna asked Anna to go to lunch, but she answered,"],["Bruna","Hi, Anna!"],["Anna","Hi, Bruna! Thanks for telling me about this event."],["Bruna","Sure! It's much better than staring at your computer. I hope it helps with your story."],["Anna","I'm sure it will. So, what should we see first?"],["Bruna","Dance and music are very important to Peruvian culture, so let's watch the dancers."],["Anna","Great! Let's go!"],["Bruna","There's this very special Peruvian dance called Marinera Norteña."],["Anna","I love the Marinera Nortina…!"],["Bruna","Marinera Norteña."],["Anna","Marinera Norten…?"],["Bruna","No. Marinera Norteña."],["Anna","I love the … marriage dance!"],["Anna","Bruna, I read about this dance. But it is much more romantic in person!"],["Bruna","The dancers are giving lessons after their performance. You should try it!"],["Anna","I'd love to. But I'm not ready to get married. I mean, one day I hope to meet the right guy. We'll buy matching motorcycles and ride into the sunset -- the wind blowing through our hair!"],["Bruna","Anna, the dance just shows the courtship tradition. It doesn't mean you will get married."],["Anna","Oh. Well, I'll try anyway."],["Bruna","Don't forget. This festival also shows Peruvian art!"],["Anna","I hope I have time to see everything!"],["Bruna","Anna, I wish I could join you. But I have some work to do."],["Anna","Of course, of course. You go back to work. I'll check out the art."],["Bruna","Okay, I'm hoping to finish in about an hour. Let's meet then."],["Anna","Great. See you then!"],["Bruna","See ya!"],["Prof. Bot","Did you notice any sentences with hope or wish?"],["Anna","Oh, wow! I can make my own Peruvian art!"],["Bruna","Anna, how's it going?"],["Anna","Hi, Bruna!"],["Bruna","You know you're in the kid's section, right?"],["Anna","I'm in the art making section."],["Bruna","I see that. Your art is very nice. I wish I could do art like that."],["Anna","Oh, this one's not mine. This is mine."],["Bruna","Wow! Really? That's really nice!"],["Anna","Thanks! And thanks for telling me about this festival. I learned so much about Peru. Ooh, we still have time!"],["Bruna","Time for what?"],["Anna","Time for Marinera Norteña!"],["Prof. Bot","Do you remember what Anna said? \"I really want to understand Peru.\" I hope you understand Peru a little better now, too. And I wish I could talk with you more about grammar, but that's all the time we have today! Go to the website to learn more!"]]},{"g":"Уровень 2","t":"Lesson 11: The Big Snow","u":"/a/lets-learn-english-level-2-lesson-11-the-big-snow/4102755.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/a/a4/a461d037-2f47-4d6e-b971-86c661a4cb8d.mp4?cb=edc3e7a51","a":"https://voa-audio.voanews.eu/vle/2017/11/21/0117495a-4165-48c3-8972-61491413ad7a.mp3","l":[["Kelly","Hi, Anna. Why do you have all this weather stuff?"],["Anna","I love weather."],["Kelly","Me too! Weather is so important."],["Anna","It is. It affects people's lives!"],["Kelly","Have you ever reported on a big weather event?"],["Anna","I have. I've reported on a blizzard."],["Kelly","Do mean the one last weekend?"],["Anna","Yes! I had been waiting for that blizzard for years. When it came, I was ready."],["Prof. Bot","Welcome to our most perfect lesson! Why is it perfect? Today we are reviewing the present perfect and past perfect verb tenses. These show that an action is completed."],["Kelly","Have you ever reported on a big weather event?"],["Anna","I had been waiting for that blizzard for years."],["Anna","I have wanted to report on a big weather event my whole life."],["Kelly","Who hasn't? Did you report all weekend... by yourself?"],["Anna","No, no. I volunteered Pete to help me."],["Pete","Why am I here on a Saturday? Why are you carrying things? Why? Why?"],["Anna","Pete, these are my supplies – food, a blanket; warm clothing. Where are your supplies?"],["Anna","Pete, Pete, Pete. This could be the \"blizzard of the century.\""],["Pete","It'll be fine."],["Kelly","How else had you prepared?"],["Anna","Well, I had just bought the latest weather forecasting software. So, I brought it!"],["Kelly","Do you mean The Weather Genie Pro?"],["Anna","You know it. Pete thought it was pretty great too."],["Pete","Do you have any games on that thing?"],["Anna","Yes! I have the best weather survival game. Boom!"],["Pete","Sounds fun."],["Anna","It is. But right now, Pete, this computer is a work tool. It will give us the temperature, wind speed, wind direction and amount of snowfall … in real time! Boom, boom!"],["Pete","I can't wait."],["Anna","Pete, we need a name for this blizzard."],["Pete","No, we don't."],["Anna","All the great storms have names."],["Pete","No, they don't."],["Anna","I know -- \"The Big Snow!\""],["Pete","I am not saying \"The Big Snow.\""],["Pete","Welcome to \"The Big Snow.\""],["Kelly","The Big Snow broke all kinds of records, didn't it?"],["Anna","Yes it did. And every time a record was broken, we celebrated!"],["Anna","So far, in Washington, D.C. 29 inches of snow has fallen. That, my dear listeners, is a record! (Honks horn)"],["Anna","We just broke the wind speed record! (Honks horn)"],["Anna","Snow has been falling for 30 hours straight! That's another record! (Honks horn. Pete comes into room and breaks the horn.)"],["Kelly","By Saturday night, stores and restaurants had closed. Did you bring enough food?"],["Anna","I thought I had brought enough food. But I ran out."],["Anna","Hey, Pete, where is my bag of popcorn?"],["Pete","Maybe you ate it already."],["Anna","No, I didn't."],["Pete","I haven't seen it. (Pete has popcorn in his beard. Anna tries to hit him.)"],["Anna","We had reported together for 48 hours straight!"],["Kelly","Wow. That must have been a great team-building exercise for you and Pete."],["Anna","Yeah. You - you could say that."],["Prof. Bot","I hope you found all the sentences with perfect tenses. Learn more on our website!"]]},{"g":"Уровень 2","t":"Lesson 12: Run! Bees!","u":"/a/lets-learn-english-level-2-lesson-12-run-bees/4139015.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/b/b4/b442094f-e869-4a7f-9c14-d335957eafbc.mp4?cb=edc3e7a9e","a":"https://voa-audio.voanews.eu/vle/2017/11/28/260c25bd-1773-42d0-8b8a-54924d27427c.mp3","l":[["Anna","Wow. Did you know that bees are dying?"],["Kaveh","That is bad news. If all the bees died, there would be no food. Bees are very important."],["Anna","Yes, they are. Speaking of bees, one of our little friends is here now."],["Kaveh","You know, Anna, if you ignore it, it will fly away. But if you swat it, it might sting you."],["Anna","I'll ignore it. I can ignore it. See, I'm ignoring it. (she is swatting at the bee)"],["Kaveh","Anna, are you afraid of bees?"],["Anna","What makes you say that?"],["Kaveh","Anna, you should call my friend, Caroline. She is a beekeeper and a bee educator. If you talk to her, she'll probably help you get over your fear of bees."],["Anna","I am not afraid of bees."],["Kaveh","Here's her card."],["Anna","Ahhh!"],["Prof. Bot","In this lesson, you can learn about conditionals. They have \"if\" and \"will\" or \"would.\" There are two kinds of conditional sentences in this lesson."],["Anna","I think I'm at the wrong address. This does not look like a place where bees are kept. ​(knocks on door)"],["Anna","Oh, sorry to bother you. I'm looking for beekeeper Caroline. I'm here to take her \"Learn to Love Bees!\" class."],["Caroline","You're in the right place! I'm Caroline!"],["Anna","Oh, nice to meet you! Um, Caroline, I thought this class used real bees and real hives."],["Caroline","It does! If you look in my backyard, you will see my bees! I'm a home beekeeper!"],["Anna","What? You live with bees? That is really amazing! And at the same time really scary."],["Caroline","It's not scary. If you come, I'll show you."],["Anna","Caroline, how many bees are in that hive?"],["Caroline","About thirty thousand (30,000) in each."],["Anna","What? That's amazing! But, aren't you afraid that they are gonna come out and kill you?"],["Caroline","No, not at all, Anna. Even my children help me. Tell me, why are you afraid of bees?"],["Anna","I don't know. Well, when I was a little girl my mom ran out of honey. And I really wanted honey for my pancakes. So, I climbed high into a tree and hit a beehive with a stick … several times. Then I reached inside with my bare hands to pull the honey out. That's when I got stung … a lot."],["Anna","Caroline, if you hit a beehive with a stick and reach inside, you might get stung."],["Caroline","No, Anna. If you do those things, you will get stung."],["Anna","Yes. I did."],["Caroline","And you know that it was your fault you got stung, don't you?"],["Anna","Yes. I did."],["Caroline","Bees know your feelings. And if you stay calm, the bees will be calm. If you're nervous, the bees will be nervous. And if bees are nervous, they may sting. So, please be calm."],["Anna","I will be calm. I am calm. Okay, I'm ready. I'm ready"],["Caroline","Great. Let's get our equipment on."],["Anna","Wait! Wait! I'm not ready! I'm nervous! Give me a minute to be calm."],["Prof. Bot","Are you ready for one more conditional sentence?"]]},{"g":"Уровень 2","t":"Lesson 13: Save the Bees!","u":"/a/lets-learn-english-level-2-lesson-13-save-the-bees/4145716.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/d/d7/d71f7385-7af3-4032-b1a8-3e543cf0cac0.mp4?cb=edc3e7ade","a":"https://voa-audio.voanews.eu/vle/2017/12/01/104a6627-290a-4472-911e-3bb9349f44f7.mp3","l":[["Prof. Bot","We are back with Anna and Caroline and the bees. Last time, Anna was afraid. (Anna: I'm not afraid of bees!) But Caroline is helping her to stay safe. Look at sentences that start with \"If\" to find more conditional sentences. Remember, Type 1 conditionals use the present tense and \"will,\" and Type 2 use the past tense and \"would.\" Now, let's find out what happens with Anna and the bees."],["Caroline","I have a feeling that your fear of bees will be gone soon. There are things beekeepers do to protect ourselves. For example, we wear protective clothing. This is a beekeeper's veil, suit and gloves. There are other things we can do, too. If I use a smoker, the bees will stay calm."],["Anna","Let's use smoke … lots of smoke."],["Caroline","Okay, Anna, that's enough smoke. Another thing you can do is stay calm. Okay. When I lift the frame, you will see the bees."],["Anna","I'm ready. Let's do this thing!"],["Caroline","Okay, let's put on our protective clothing."],["Caroline","I will carefully take out a frame. This is where the bees live. There are worker bees, drone bees and the queen bee. The bees have different jobs. The queen bee lays the eggs. The worker bees collect nectar and pollen ​from flowers and bring it back to the hive. Then they make honey! Now, you hold the frame. There are the bees."],["Anna","There are so many! And they are so busy! Now I know why we say, \"busy as a bee!\""],["Caroline","Good job, Anna."],["Anna","Caroline, bees are beautiful and important. If I wanted to help the bees, what would I do?"],["Caroline","Great question. You can plant native flowers that bees like. Here's a book to help you know which ones to plant."],["Anna","It's a beautiful book. And look, it tells you which bees like which types of flowers."],["Caroline","It also tells you how the flowers affect the flavor of the honey."],["Anna","Flowers make a big difference to bees. If they don't eat, they won't live."],["Caroline","Buying local honey also helps the bees. If you want to help bees, do those two things."],["Prof Bot","I learned a lot about bees. Hey, if I worked with bees, I would not need protective clothing! Guess what? That was a Type 2 conditional. And I heard a Type 1 conditional, too. (Anna: If they don't eat, they won't live.)"],["Anna","Thanks for the book, Caroline, and the bee puppet and for teaching me about bees. Look … I'm not scared."],["Caroline","Good job, Anna. If you ever want to see the bees again, I'll be here! You have my business card. I'll let you see yourself out."],["Anna","Thanks! Bye! I will plant tons of flowers!"],["Bees","Thanks, Anna. (bees spell out the words)"],["Anna","Sure thing, bees! Oh, and I'm sorry about hitting that hive when I was a little girl."],["Bees","We love you, Anna. (bees make a heart sign.)"],["Anna","Take care, bees! (to herself) Which way is the Metro?"],["Bees","That way. (they draw an arrow)"],["Anna","Thanks!"],["Prof. Bot","So, if I you want to learn more about bees, visit your local beekeeper like Anna did. Maybe you can try some local honey, too."]]},{"g":"Уровень 2","t":"Lesson 14: Made for Each Other","u":"/a/lets-learn-english-level-2-lesson-14-made-for-each-other/4159000.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/b/b0/b0230cad-9353-42b1-8d57-d64a8e5c7c5a.mp4?cb=edc3e7b14","a":"https://voa-audio.voanews.eu/vle/2017/12/12/e2fe076d-3fa7-495a-83ea-9d4d4cba9fad.mp3","l":[["Anna","Hello! What are you guys looking at?"],["Pete","I'm showing Ashley pictures of my girlfriend. We have so much in common -- even small things. She can't whistle and I can't either."],["Ashley","(to Pete) And here's a picture of my boyfriend. (sighs)"],["Ashley","My family is big and so is his. I don't like ball sports and he doesn't either! (sighs) We are made for each other..."],["Pete","… and so are we. (sighs)"],["Anna","Uh… you have found perfect partners … and so have I!"],["Professor Bot","Pete and Ashley are talking about people they love. They are putting two ideas together with connectors."],["Ashley","You met someone, Anna? That's great! What's his name?"],["Anna","His name? His name is uh… (stalling, looks around, sees a bus) Bus … ter. (stalling, looks around, sees a car) Car … ter."],["Ashley","(says it like Anna did) Bus...ter Car...ter?"],["Anna","It's just Buster Carter, Ashley. I like him and he likes me. We're a great couple."],["Ashley","Hey, let's all get dinner tonight, together. You can bring Buster."],["Pete","(laughing) Yeah, I can't wait to meet him."],["Anna","Thanks, Ashley, but he's really busy tonight with his uh, (looks around, sees squirrel) squirrel collection. Bye, guys! Gotta go!"],["Ashley","Squirrel collection?"],["Pete","You know, she made all that up."],["Ashley","That's so sad. She needs to meet someone. Hey, do you know anyone who she might..."],["Pete","No."],["Anna","(to herself) Anna, Anna, you lied! You lied! Now, they think you have a boyfriend - with a squirrel collection. Here, squirrel. (throws food) Well, you need to tell them the truth. You don't have a boyfriend."],["Man","Excuse me, is this seat taken?"],["Anna","Ashley, Pete, I need to talk to you. This morning, I lied."],["Pete","Let me guess. There's no Buster Carter. What a surprise!"],["Anna","I'm sorry. But later I really did meet someone and we have a lot in common!"],["Ashley","He sounds perfect for you, Anna. Can he come tonight?"],["Anna","That's the sad part. You see, he just got a job as a spy, and tonight he leaves on assignment."],["Pete","Of course he does."],["Anna","But that's okay, because now I know that there is someone out there made for me. (looks at the time) Oh, it's late! I have to see him off at the train station. Bye, you guys!"],["Ashley","Bye Anna! Oh dear, she's worse than we thought."],["Pete","She's lost her mind."],["Ashley","What should we do?"],["Pete","(happy, excited) Let's tell her!"],["Ashley","No, Pete. Mr. Right may not be real but he makes her really happy."],["Professor Bot","Did you find any other connectors? Notice how the words are in a different order in the part after \"so.\" \"I am\" becomes \"am I\" and \"he can\" becomes \"can he.\""]]},{"g":"Уровень 2","t":"Lesson 15: Before and After","u":"/a/lets-learn-english-level-2-lesson-15-before-after/4159057.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/5/5c/5c124a10-74f5-4641-a72b-7f8efdbc8fa9.mp4?cb=edc3e7b43","a":"https://voa-audio.voanews.eu/vle/2018/01/04/99ceaa2e-fb25-43a8-8731-0a7f23901d65.mp3","l":[["Anna","Penelope, even though we both love speed walking, could we slow down a bit?"],["Penelope","No way! I think because I'm walking with you, I'm walking faster."],["Anna","Come on, Penelope. Let's take a break. We've been speed walking since 8 a.m.! You're so competitive! You even wore your medals!"],["Penelope","You brought your trophies! You're out of shape. When we were little girls, we could speed walk all day! (pulls ahead)"],["Anna","(chases her) Hey, wait for me! Hey, you know the speed walking rules! If both feet leave the ground, it's running! You ran!"],["Prof. Bot","Anna and Penelope are doing something they both love - speed walking!"],["Penelope","Whew! That was great!"],["Anna","(Anna catches up) Wow, Penelope, you're still really fast! Since I've been working in an office, my speed walking has been much slower."],["Penelope","You are slower, Anna. Maybe you should hire a personal trainer."],["Anna","That will be great. As long as the trainer understands speed walking."],["Penelope","(hands her a business card) Try this company. After you fill out an online application, they will match you to the perfect trainer."],["Anna","As soon as I get home tonight, I'll do it! Thanks."],["Anna","Are you my trainer?"],["Alaskan Albert","If you're Anna, then I'm your trainer -- Alaskan Albert. Because I'm from Alaskan wilderness, I'm skilled in all outdoor activities of the wild."],["Anna","That's great but what about speed walking?"],["Alaskan Albert","Speed walking? That's funny! Since I've been living in the city, I've combined wilderness training with a city workout. I call it \"Call of the Wild Parkour!\" (He howls like a wolf.)"],["Anna","Okay … but seriously, when do we speed walk?"],["Alaskan Albert","Your application did not say how funny you are!"],["Anna","No. But it did say that I'm a speed walker! Did you read it? Forget it. We'll have to cancel."],["Alaskan Albert","Why?"],["Anna","We can't train today because it's too cold and too windy."],["Alaskan Albert","No way! No pain, no gain! When you exercise in really cold weather, you feel alive!"],["Anna","Really? Because right now I just feel cold."],["Alaskan Albert","You're so funny. But seriously, after our training, you will be ready for any extreme physical challenge. Let's get started!"],["Alaskan Albert","Anna, even though you're trying really hard, you're really bad at Call of the Wild Parkour. (he howls)"],["Anna","I'm bad at Call of the Wild Parkour because I don't want to do Call of the Wild Parkour! (she howls) I am a speed walker. It's what I do. It's part of who I am."],["Alaskan Albert","Why didn't you say something?"],["Anna","I did. Several times! You thought I was joking."],["Alaskan Albert","Now I understand. Anna, I can help you., if you follow my advice, I'll put the speed back in your speed walk."],["Alaskan Albert","Go, Anna, go!"],["Prof. Bot","For more about adverb clauses, visit our website!"]]},{"g":"Уровень 2","t":"Lesson 16: Find Your Joy!","u":"/a/lets-learn-english-level-2-lesson-16/4198066.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/e/e2/e28c9b49-99f9-4443-87ab-12329eccbdf1.mp4?cb=edc3e7b80","a":"https://voa-audio.voanews.eu/vle/2018/01/10/95f0ce1f-6cfd-44e4-b83a-e225d7cb0224.mp3","l":[["Anna","Hi, Kaveh! Let's go to lunch!"],["Kaveh","Ooh, I know a great place. When I first started working here, I would go every day!"],["Anna","Great. Oh, no."],["Kaveh","What's wrong?"],["Anna","I lost my key! I just had it this morning."],["Kaveh","You should check the Lost & Found office."],["Anna","Great idea. Where is it?"],["Kaveh","Oh, it used to be across from the cafeteria. But now it's down in the basement next to the elevators. It's really hard to find."],["Anna","The Lost & Found is hard to find. That's funny."],["Kaveh","It is."],["Professor Bot","I hope Anna can find the Lost & Found office!"],["Serenity","Come in! I am Serenity."],["Anna","Hi, Serenity. I'm Anna!"],["Serenity","Please, sit down. How can I help you?"],["Anna","I lost something very important."],["Serenity","Shh. I already know. You need help."],["Anna","Yes. I need help finding the key …"],["Serenity","Shh. You need to find the key – the key that will give you happiness."],["Anna","Yes. Finding this key will make me very happy."],["Serenity","First, Anna, let me tell you a little bit about myself."],["Anna","Okay."],["Serenity","I used to be a very important person with a very important job. I made a lot of money -- I mean a lot."],["Anna","Wow. Good for you!"],["Serenity","No! No, it was bad for me. I lost the most important thing – the key! You've lost it too, haven't you, Anna? Haven't you?"],["Anna","I guess. So, how does this work? Do I have to fill out a form or something?"],["Serenity","No. No forms. Just answer this one question: As a child, what did you use to do to feel happy?"],["Anna","When I was little, I used to sing all the time with my family. Those were good times."],["Serenity","Singing is so joyful! I used to sing. But now that I've started my business, I've just been too busy. Too busy! Anna, why don't you sing again?"],["Anna","I sing everywhere! I sing in the office. I sing on the metro. I sing in the elevators. I sing on the escalators. I sing in the bathroom. Serenity! Serenity! I really need to find my key. Yeah!"],["Serenity","Yes, we need to find the key … the key to happiness."],["Anna","No, no. I just need to find the key to my apartment."],["Serenity","I used to know. But now I don't! Do you, Anna?"],["Anna","I don't know. I think I left it in the ladies' room. You know, this isn't the Lost & Found, is it?"],["Serenity","It could be the Lost & Found. I'm lost! And I used to find joy for people! I used to find joy!"],["Anna","You know, this is a bad time for you. I'll find the Lost & Found myself. Bye, thanks."],["Serenity","I used to find joy. I used to find joy! I used to find joy!"],["Anna","Ah, I found my key!"],["Serenity","I used to find joy!"],["Pofessor Bot","Oh no. Serenity lost her joy. But at least Anna found her key! Check out our website for more!"]]},{"g":"Уровень 2","t":"Lesson 17: Flour Baby, Part 1","u":"/a/lets-learn-english-level-2-lesson-17/4220576.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/9/99/99b14704-c92c-4969-9b69-cba7e81ed310.mp4?cb=edc3e7baf","a":"https://voa-audio.voanews.eu/vle/2018/01/24/4f5af081-e654-4912-9f5d-24cd3fa5170a.mp3","l":[["Ms. Weaver","Anna, Pete, I have a new assignment for you -- a show on single parents! What is it like for a mother or a father to raise a child by herself or himself?"],["Anna","We can interview single parents. They can share their experiences themselves."],["Ms. Weaver","Yes, but you need to experience parenthood yourselves."],["Anna","Ourselves?"],["Peter","Yeah, how do we do that? We're not parents."],["Ms. Weaver","I asked myself the same question. I said, \"Caty, how are they gonna do that?\" Then an idea came to me. I will give you the babies!"],["Professor Bot","You may be asking yourself the same thing that I'm asking myself: what is Ms. Weaver talking about!? I am sure we will find out shortly."],["Ms. Weaver","Here are your babies!"],["Pete","Those are bags of flour."],["Ms. Weaver","No, Pete, for the next six days, this is your baby. Here are your instructions. Do not leave your babies alone. A baby cannot take care of itself. And you two must do everything by yourselves."],["Anna","Pete, look, my baby is organic and whole grain. Your baby is ordinary."],["Anna","(to Pete) Monster! (to Caty) This is a great idea, Ms. Weaver!"],["Pete","This is a terrible idea."],["Anna","Speak for yourself, Pete! We need to throw ourselves into the research! I'm starting right now!"],["Pete","Hey Anna, you forgot your baby!"],["Anna","Come to mama!"],["Anna","Good girl! Good girl!"],["Professor Bot","Singular reflexive pronouns end in \"self.\" Plural ones end in \"selves.\""],["Anna","This is hard! I hope Pete is not doing well. I really need that vacation day!"],["Professor Bot","We will all see how Pete is doing in the next episode. We'll also learn when not to use reflexive pronouns."]]},{"g":"Уровень 2","t":"Lesson 18: Flour Baby, Part 2","u":"/a/lets-learn-english-level-2-lesson-18/4231290.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/2/20/2098556b-efbc-46af-b466-ec35e553d691.mp4?cb=edc3e7c00","a":"https://voa-audio.voanews.eu/vle/2018/01/31/16d806b3-f878-4eff-bd6e-1857ec1241e0.mp3","l":[["Professor Bot","In Part 1 of this two-part lesson, Ms. Weaver gave Anna and Pete an assignment. Ms. Weaver instructed them to do everything by themselves."],["Ms. Weaver","Okay, Pete, let me see your research first."],["Ms. Weaver","That's a heavy binder. And you and your Baby look great."],["Pete","Thanks, Ms. Weaver. We feel great!"],["Ms. Weaver","Anna. Anna, you're next. Anna? Anna wake up!"],["Anna","I'm here, Baby! I'm here! I'm here! Here's your bottle."],["Ms. Weaver","Anna, you and your baby look awful. What happened?"],["Anna","Well, I took her everywhere. Everywhere. And I fed her every three hours. So, I haven't slept since … what day is it?"],["Ms. Weaver","It's Friday. What happened there?"],["Anna","Oh, that. Oh, that. I was making myself a salad and had a little accident with a knife. I put my flour baby in front of me. And then I accidentally stabbed it. But I gave it First Aid!"],["Ms. Weaver","Is that a burn?"],["Anna","Yes. Yes it is. While I was making myself dinner, I put Baby next to me. I accidentally knocked her into the sink. So I put her in the microwave to dry. That's when she caught fire."],["Professor Bot","Okay. So, we use a reflexive pronoun when it refers to the subject of a sentence or clause."],["Ms. Weaver","Anna, Anna, you should be very proud of yourself."],["Pete","Proud? She stabbed and burned her baby!! And she only did one page of research…and it's covered in milk. Ew."],["Ms. Weaver","Yes, Pete. But she followed instructions."],["Pete","Hey, I did..."],["Ms. Weaver","Please, Pete. Anna, I think your baby has lost some weight. Is there something else you want to share?"],["Anna","Yes. I'd like to share … these! I made them myself this morning."],["Pete","You baked your baby? You should be ashamed of yourself!"],["Anna","I baked them at the end of the experiment, Pete. At that point, this was just a bag of flour."],["Pete","It was always just a bag of flour!!"],["Ms. Weaver","Pete, will you listen to yourself?! You sound crazy."],["Pete","I sound crazy! This whole experiment was crazy!! She was the one who carried around and fed it and..."],["Pete","Mmm. That is good."],["Professor Bot","So, what have we learned? We've learned when to use reflexive pronouns and when not to."]]},{"g":"Уровень 2","t":"Lesson 19: Movie Night","u":"/a/lets-learn-english-level-2-lesson-19/4242927.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/7/72/72d73c46-9f5a-47ba-96dc-4a2e460ce714.mp4?cb=edc3e7c66","a":"https://voa-audio.voanews.eu/vle/2018/02/08/aa7b1559-adea-4534-8d4f-649785319a21.mp3","l":[["Anna","Hi, can you tell me how to get to your movie theater?"],["Anna","Oh, that's easy. OK, thank you. Bye."],["Anna","Hi, Pete! Thanks for the movie invitation."],["Pete","Yeah, sure Anna."],["Anna","I love movies. I love the plot! I love the set design! I love the costumes! I love -"],["Pete","Anna, I take movies very seriously. You're not one of those people who talks during a movie, are you?"],["Anna","No."],["Pete","Good."],["Professor Bot","Anna loves movies. And..she loves talking about movies. And Pete doesn't sound happy about that."],["Anna","Can you tell me how to get to your movie theater?"],["Anna","I love the smell of popcorn. I love seats that rock."],["Pete","I love when people are quiet."],["Anna","Ooh look, the previews are starting. I love to see what movies are coming out. Oh, this one looks good!"],["Pete","Anna, the previews are part of the movie experience. So, would you mind not talking?"],["Anna","Oh, sure, sure."],["Pete","Anna, I was wondering: are you almost finished with that?"],["Anna","No. There's still a lot of milkshake at the bottom."],["Pete","Anna, do you mind not drinking so loudly?"],["Anna","I'll try. But it's really thick."],["Pete","Anna, what are you doing?!"],["Person in audience","Shh!"],["Pete","I'm not the one making all the noise."],["Person in audience","Shhh!"],["Anna","I'm done now."],["Pete","Anna, would you mind opening that a little bit more quietly?"],["Anna","I'll try."],["Pete","Anna, just give it to me!"],["Person in audience","Shhh!"],["Pete","(to the person) It's not mine. I'm opening it for her. Here."],["Person in audience","Shhhhhh!!"],["Pete","Here!"],["Anna","Thanks, Pete."],["Pete","Now, would you mind being more quiet?"],["Pete","Excuse me, would you mind turning down your phone light?"],["Anna","Oh, sorry! I forgot to turn my phone off."],["Anna","Oh no! I dropped it. Where is it?"],["Pete","Anna, can you please turn off your phone?"],["Anna","Excuse me, would you mind lending me your phone light for a minute?"],["Pete","No! I'll get it!"],["Person in audience","Shhhhh!"],["Pete","Look, people, I'm not the noisy one here! So, you all need to shush the right person. And I should know about shushing! I shush people all the time!!"],["Security guard","Excuse me, sir. You can't yell in a movie theater. Would you mind coming with me?"],["Pete","You're kicking me out? Me? But I'm always the quiet one in the movie!"],["Anna","Pete should know better. You have to be quiet in a movie theater. Shh, the movie's starting!"],["Professor Bot","Well, that's a surprise! I thought Anna would be the noisy one."]]},{"g":"Уровень 2","t":"Lesson 20: The Test Drive","u":"/a/lets-learn-english-level-2-lesson-20/4254704.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/a/ab/ab7dd50e-b4fa-412f-b50d-e7b0e81221ff.mp4?cb=edc3e8012","a":"https://voa-audio.voanews.eu/vle/2018/02/15/8b42c321-07ea-4eb1-a1f9-e7cc6019606e.mp3","l":[["Anna","(to Penelope) That's a great idea. (to Rick) Rick, I think we should use this as the opening shot."],["Penelope","Anna, did Ms. Weaver give us instructions for covering the car show?"],["Anna","She did. She said that we need to show lots of cars. She said we need to interview people. And she also said that we should have fun."],["Penelope","Those were her exact words?"],["Anna","Yeah. She said, \"Have fun, Anna!\" And she is the boss."],["Anna","(to Rick) Okay, Rick, are you - are you ready? OK. Hello, I'm Anna Matteo. Welcome to the Washington Car Show!"],["Anna","People all over town are saying that if you like cars, this is the place to be! So, let's see what people are talking about. (at Rick) How was that? Okay? Is that Good?"],["Professor Bot","Anna, Penelope and Rick are making a news story about the Washington Car Show. Ms. Weaver gave them instructions."],["Anna tells Penelope","She said that we need to show lots of cars."],["Anna","This car show has many styles of vehicles. There are utility vehicles, classic cars, trucks, sports cars, and everyday vehicles."],["Penelope","Okay, I think we got good interviews."],["Anna","Me too! People had very different opinions. But they all said they loved cars."],["Penelope","Anna, look -- a robot!"],["Anna","A robot!"],["Penelope","A robot!"],["Anna","Rick, we have to use the robot in the show!"],["Robot","What is your first name?"],["Anna","Anna! Anna!"],["Robot","Anna, you know, what an effort. What an effort to robot dance. How about a round of applause for Anna! I've never seen anyone try so hard."],["Anna","Penelope, did you hear that? Hank the Robot said that he has never seen anyone dance like me."],["Penelope","Uh, I think many people here are saying that, Anna."],["Anna","That was fun. You know what someone told me? You can test drive a Jaguar at this car show."],["Penelope","Now, that sounds fun."],["Anna","Let's go."],["Penelope","Okay."],["Anna","This course is smooth. So you can drive faster."],["Anna","He said...that I can't drive, unfortunately."],["Anna","Oh my gosh…reverse."],["Anna","That was great. This is awesome."],["Kurt","Are you ready to go on the rollercoaster?"],["Anna","I'm ready."],["Kurt","Here we go!"],["Anna","That's awesome."],["Anna","That was...That was awesome! I just want to go one more time. I promise. That's it. Just one more time."],["Anna","This course is bumpy and uneven. I was told that I could drive this course. So I am."],["Anna","(to Rick) Okay, Rick, are you rolling? Awesome. Okay, this course is uneven. But I think the ride will be smooth."],["Anna","Ooh. This hill is really steep."],["Anna","Oh my gosh. I can't tell you how much fun this is."],["Anna","Penelope, that was so much fun! I think I need to go again."],["Penelope","Uh, Anna, I think we have enough test drive video."],["Anna","Ms. Weaver said to get a lot. So, I think I should go again. (to Rick) Rick, I'm going to go again. Until next time!"],["Penelope","But I want to get lunch, Anna!"],["Professor Bot","Penelope said she wants to go to lunch. But I don't think that's going to happen soon. Visit our website for more!"]]},{"g":"Уровень 2","t":"Lesson 21: Trash to Treasure, Part 1","u":"/a/lets-learn-english-level-2-lesson-21/4273059.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/3/33/33288430-6fd2-49ab-aa0d-e7bcca6f13d8.mp4?cb=edc3e8066","a":"https://voa-audio.voanews.eu/vle/2018/03/06/fabffd67-3af1-480c-925c-0b87e11fe82b.mp3","l":[["Anna","(on phone, to Pete) Got it. Pete, I promise. I won't tell anyone. (to herself) Bye. He is so strange."],["Ashley","Hey, Anna!"],["Anna","Hi, Ashley!"],["Ashley","Are you talking to yourself again?"],["Anna","No, not this time. I was talking to Pete."],["Ashley","How's he doing?"],["Anna","Good. He has a birthday coming up! But he told me not to tell anyone."],["Ashley","Why?"],["Anna","Well, from the way he was speaking, I don't think he likes cake or presents or fun."],["Ashley","That sounds like Pete."],["Anna","Well, I don't care. I'm getting him a present. Do you know where I can buy something unique?"],["Ashley","I do -- Tanglewood Works. You will definitely find something unique there."],["Anna","Great. I'll go this weekend. Now, speaking of Pete's birthday, what else should I do? I know. I'll rent him a clown!"],["Ashley","Yeah, he'll never speak to you again."],["Professor Bot","Did you hear Ashley and Anna using the words talk and speak?"],["Sue","Hey there. Welcome to Tanglewood Works! I'm Sue. How can I help you today?"],["Anna","Hi Sue, I'm Anna. A friend told me about your store. She said, \"Anna, this place is really unique!\""],["Sue","We are! Here at Tanglewood Works, we focus on things that are handmade, reclaimed and recycled."],["Anna","Wow! That is really good for the environment."],["Sue","It's good for you too. Local artists made all of these one-of-a-kind pieces. And I paint most of the furniture."],["Anna","Can I look around?"],["Sue","Oh, please do."],["Sue","So, Anna, do you like to make things?"],["Anna","Me? Oh, no. Every time I try to make something, something goes wrong."],["Anna","Oh, sorry. Sorry."],["Sue","It's okay. Anna, everybody can make something."],["Anna","Sue, this piece is very interesting!"],["Sue","You know, when I found these pieces, they were broken and in a dumpster. But they spoke to me. And they said, \"Save me, Sue! Save me!\""],["Anna","Sue, what do you mean they \"spoke\" to you?"],["Sue","When I see something special that someone has thrown away, I can almost hear it talk."],["Anna","It's not saying anything!"],["Sue","Anna, it's not easy to see the treasure in trash."],["Anna","Or hear it talk."],["Sue","But you can learn. In fact, I teach private classes. And one is called Turning Trash to Treasure."],["Sue","Next week, bring in some trash and we'll turn it into treasure. Just remember – pick some trash that \"speaks\" to you."],["Anna","Got it! I'll see you next week!"],["Professor Bot","Will Anna find trash that \"speaks\" to her? What will it say? We'll find out next week!"]]},{"g":"Уровень 2","t":"Lesson 22: Trash to Treasure, Part 2","u":"/a/lets-learn-english-level-2-lesson-22/4283017.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/d/d1/d122dfe7-5f99-4ef9-980f-1ac4aa6a4865.mp4?cb=edc3e82fc","a":"https://voa-audio.voanews.eu/vle/2018/03/06/0fd0e840-fff7-4d90-aaeb-eba188526184.mp3","l":[["Sue","Welcome to class, Anna. I can't wait to see your trash!"],["Sue","Oh, okay. Alright, it's a -- it's a net with a … oh, it's got a hole in it. Tell me about that."],["Anna","This net said to me, \"Anna, I used to catch stuff. I don't anymore. So, use me, Anna.\" That's what it said. It said, \"Use me, Anna.\""],["Sue","Okay. So...it's a plastic helmet."],["Anna","This plastic helmet said, \"Anna. Hey, Anna, find me a head.\""],["Sue","Okay, um...and a broken toy."],["Anna","This broken toy … this broken toy said to me – it said, \"Anna, help me find fun.\" \"Help me, Anna\" is what it said."],["Sue","Anna, this stuff is not saying anything to you or me or anyone. It's what we like to call in the business … garbage."],["Anna","But you said to bring in trash."],["Sue","Sometimes trash is treasure. Sometimes it's just trash."],["Sue","Anna, don't worry. Next week, I could teach you decoupage."],["Anna","Decoupage. Decoupage. That's fun to say."],["Sue","All you need to bring is a clean shoe box. A box that held shoes."],["Anna","I got it. I got it! See you next week!"],["Prof. Bot","Ut oh. It looks like Anna doesn't know the difference between treasure and trash. She thinks those things are telling her something!"],["Prof. Bot","The words tell and say have similar meanings. But we use them in different ways."],["Prof Bot","Tell means \"to inform or instruct someone with words\" and is almost always followed by an indirect object. For example, Sue says, \"Tell me about that.\""],["Prof. Bot","The word me is the indirect object and tells us who is being told."],["Prof. Bot","Say means \"to express something with words\" and focuses more on the words used. For example, Anna says, \"That's what it said. It said, ‘Use me, Anna.'\""],["Prof. Bot","Listen for when Anna and Sue use tell and say."],["Sue","Anna, welcome to Decoupage class. Decoupage is just gluing pretty pictures onto stuff."],["Sue","Anna, I've got to talk to this person. I'll be right back. Don't start without me."],["Anna","Got it."],["Anna","Okay. I can fix this."],["Sue","Anna, what happened? I told you to wait for me!"],["Anna","Actually, you told me not to start without you, which I didn't. Your glue is really sticky."],["Sue","Next week, let's try lamp making. There's – there's no glue. Here's a flier."],["Anna","Thanks. See you next week."],["Sue","Anna, you did really well this week. I think lamp making might be your thing!"],["Anna","Thanks, Sue. I did everything you told me to do."],["Sue","Remember: I said to read the instructions really carefully. Where are those instructions?"],["Anna","Let's just plug it in!"],["Anna","So, what class will you be teaching next week?"],["Prof. Bot","Too bad Anna didn't follow instructions! Visit our website for more on tell and say!"]]},{"g":"Уровень 2","t":"Lesson 23: Rock Star","u":"/a/lets-learn-english-level-2-lesson-23/4287922.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/0/0e/0e75964c-a547-4867-81bc-23c1a81ac2e2.mp4?cb=edc48ea85","a":"https://voa-audio.voanews.eu/vle/2018/03/15/b53a7e2c-2dd1-4623-b4d0-92efba982191.mp3","l":[["Anna","Hello?"],["Ms. Weaver","Anna, this is Ms. Weaver."],["Anna","Ms. Weaver!"],["Ms. Weaver","Tomorrow, you'll be interviewing musician Emma G."],["Anna","Emma G?! I will be talking to Emma G?!"],["Ms. Weaver","Anna? Anna, are you there?"],["Professor Bot","Anna and Ms. Weaver used the future continuous verb tense to talk about the interview."],["Prof. Bot","We use future continuous to talk about actions that will be in progress at or around a time in the future."],["Prof. Bot","For example, Ms. Weaver says, \"Tomorrow, you'll be interviewing musician Emma G.\""],["Prof. Bot","There are two options for future continuous. The first is: will be + the -ing form of the verb"],["Prof. Bot","And the second is: be + going to be + the -ing form of the verb. Keep watching for more!"],["Anna","Hello and welcome to The Music! Today, musician Emma G will be joining us here!"],["Anna","She is a wonderful songwriter and an amazing singer. And I love her! Let's give a warm welcome to Emma G!"],["Anna","Hi. Thank you for coming on the show, Emma G."],["Emma G","Of course. It's great to be here."],["Anna","Well, we can't wait to hear you sing. I listen to your music a lot. So, I feel like I know you. Is that strange?"],["Emma G","Anna, listening to music can be a very personal experience. So, no, that's not strange."],["Anna","Good because I made something for you -- a video scrapbook of our friendship."],["Anna","I took photos of you and added myself. I worked on it all weekend."],["Emma G","Well, that -- that's strange. Is that even -- is that even legal?"],["Anna","Now, Emma, let's talk about your schedule. Tell me... I mean, tell us exactly where you will be and when. Exactly."],["Emma G","Sure. Well, in early June, I'll be performing at several venues across Austin, Texas."],["Anna","That's my vacation week. I can meet you there! We can tour the city. We can have lunch."],["Emma G","Um, yeah maybe. Then in mid-July, I'm going to be teaching at a music camp in Chicago."],["Anna","I'll be visiting my sister then. She only lives about six hours from Chicago! I could drive over. We could hang out."],["Emma G","Yeah, uh maybe. You know, maybe now is a good time for some music."],["Anna","That's a great idea. Now, let's hear a song from Emma G.!"],["Emma G","I wrote this song a couple of years ago. It's called \"Wary.\""],["Emma G","Do you believe in happy endings?"],["Anna","Endings..."],["Emma G","Do you really believe that we could be…"],["Anna","Be..."],["Emma G","I think something is wrong. I hear a voice in the background."],["Anna","Sorry. Sorry, Emma. That was me. I'm just so excited."],["Emma G","No problem. I'm glad you like the song."],["Anna","You go ahead. You go ahead."],["Emma G","Okay. Do you believe in happy endings?"],["Emma G","Anna, there's no tambourine in this."],["Anna","I'm so sorry. I'm so sorry, Emma. See, I've always wanted to sing with you."],["Emma G","Well, come on over then and we can sing a song together first."],["Anna","No, I couldn't."],["Emma G","Come on. It'll be fun."],["Anna","Okay! Here. I brought my favorite song."],["Emma G","Oh, uh okay. Actually, I like this song. Um, are you ready?"],["Anna","Yes! Yes!"],["Emma G","Okay."]]},{"g":"Уровень 2","t":"Lesson 24: I Feel Super!","u":"/a/lets-learn-english-level-2-lesson-24/4307612.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/5/52/5234adeb-50d6-4f72-8a68-42beb3b26a82.mp4?cb=edc48eb81","a":"https://voa-audio.voanews.eu/vle/2018/03/23/f1f4841a-c2cb-4ee3-9cbe-2a132ffb5c8e.mp3","l":[["ANNA","Hi! I see you like superhero culture. Me too."],["ANNA","In fact, tonight I'm going to the big superhero convention. Are you going?"],["YOUNG MAN","Um, I don't know."],["ANNA","Well, you'd better decide soon. Last year, it sold out."],["ANNA","So, since we're talking about superheroes: would you rather become a superhero by accident, like Spiderman, or be born a superhero, like Wonder Woman?"],["ANNA","Take your time. It's a big question. I thought about it for days –"],["YOUNG MAN","Okay. If I had to choose, I'd rather be born a superhero."],["ANNA","I'd rather become a superhero by an unexpected accident!"],["YOUNG MAN","Aren't all accidents unexpected?"],["ANNA","Well, yeah."],["YOUNG MAN","What was that!? Are you okay?"],["ANNA","I'm better than okay. I feel super!"],["PROF. BOT","Oh No! Anna was just hit by lightning. She had better get help."],["PROF. BOT","We use had better to give advice. It is very informal and stronger than should and ought to. For example, Anna says: \"You'd better decide soon. Last year, it sold out.\""],["PROF. BOT","When we use had better, we usually shorten the word had for personal pronouns."],["PROF. BOT","We use would rather to say what we or someone else prefers to do or have. For example, the boy says: \"Okay. If I had to choose, I'd rather be born a superhero."],["PROF. BOT","With would rather, we also shorten the word would when used with personal pronouns. Keep watching and listen for had better and would rather."],["YOUNG MAN","You'd better see a doctor."],["ANNA","I've never felt better!"],["YOUNG MAN","You were just struck by lightning!! And what happened to your hair and your clothes?"],["ANNA","I don't know. Wait, I do know. This is my super suit! And this is my origin story."],["YOUNG MAN","What are you talking about?"],["ANNA","An origin story tells the beginning of a superhero. You should know that."],["YOUNG MAN","You're not making any sense, lady."],["ANNA","I would rather be called Lightning Bolt Lady! It'll sound great in a theme song: Lightning Bolt Lady!"],["ANNA","Now, I need to find my superpowers --"],["YOUNG MAN","Um, I really think --"],["ANNA","Wait. Don't tell me. I'll read your mind. You are thinking you'd like to be my super helper."],["YOUNG MAN","I was not thinking that."],["YOUNG MAN","No."],["ANNA","… that you should eat more vegetables."],["YOUNG MAN","Please, stop talking. You really should get some help."],["ANNA","Mind reading is not my superpower. Maybe I can become invisible. I … am … invisible!"],["ANNA","You can't see me. Who am I? I'm not here. You can't see me."],["YOUNG MAN","I can see you and so can everybody else."],["ANNA","No power of invisibility. Maybe I can create a force field. I feel it working. Nothing can hurt –"],["ANNA","Ow, that wasn't very nice. I see I have a lot of work to do. Well, goodbye, non-super person!"],["YOUNG MAN","Wait. I'd better go with you. You might get worse…if that's even possible."],["ANNA","That's very nice of you, ordinary human. But I'd rather go by myself. This is a quest."],["YOUNG MAN","Every time you speak, I get more confused."],["ANNA","A quest is a part of all superhero stories. You really need to work on your superhero studies. Now, stand back. I've never flown before."],["YOUNG MAN","And you're not flying now."],["ANNA","Flying is also not my superpower. That's too bad. It's going to be expensive to Uber everywhere. You know, I'd rather walk. It's a nice day. Goodbye, non-super person."],["YOUNG MAN","I am not talking to strangers again."],["ANNOUNCER","Will Lightning Bolt Lady find her superpowers … ever? Ouch! Did that brick wall hurt? Will the young man ever talk to a stranger again?"],["ANNOUNCER","Find out on the next episode of Let's Learn English!"]]},{"g":"Уровень 2","t":"Lesson 25: Only Human","u":"/a/lets-learn-english-level-2-lesson-25/4322773.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/4/4d/4d8e7b5e-ee13-4a0e-a743-5db22ceb979c.mp4?cb=edc48ec98","a":"https://voa-audio.voanews.eu/vle/2018/03/30/a591e14e-e65c-4370-91fb-06e8f9cad590.mp3","l":[["ANNOUNCER","When last we saw Anna, she had made a new friend. And they had been talking about superheroes for a while when suddenly Anna became Lightning Bolt Lady!"],["ANNOUNCER","She tried to find her superpowers. But it did not go well."],["ANNOUNCER","She can't fly, become invisible or create a force field. And she really cannot walk through walls. Ouch, Lightning Bolt Lady."],["ANNOUNCER","She had been walking into that wall for about 15 minutes when she had a great idea."],["LIGHTNING BOLT LADY","I just had a great idea!"],["ANNOUNCER","I can't wait to hear this one! But first, let's talk about grammar."],["ANNOUNCER","Professor Bot is on vacation this week. I'm the announcer. So, I'm going to tell you about the past perfect continuous."],["ANNOUNCER","We use this verb tense to show that an action started in the past and continued to another time or action in the past."],["ANNOUNCER","For example, I said, \"She had been walking into that wall for about 15 minutes when she had a great idea.\""],["ANNOUNCER","Had been walking is the past perfect continuous of the verb walk. It's had been plus the -ing form of the verb."],["ANNOUNCER","You'll hear me use this verb tense a few more times today."],["ANNOUNCER","Now, what am I forgetting? Oh right! Lightning Bolt Lady's great idea."],["LIGHTNING BOLT LADY","If I want to know my superpowers, I'll need to learn about lightning!"],["ANNOUNCER","So, she read many books about lightning."],["LIGHTNING BOLT LADY","Wow. A lightning strike usually lasts less than a second."],["LIGHTNING BOLT LADY","Lightning is really fast and I like speed walking. So, maybe one of my superpowers is super-speed walking! (to stranger) Bye!"],["LIGHTNING BOLT LADY","Check! Super-speed walking is definitely one of my superpowers."],["LIGHTNING BOLT LADY","Lightning has millions of volts of electricity. Amazing!"],["LIGHTNING BOLT LADY","Wow! I can charge a lot of batteries with this superpower!"],["ANNOUNCER","She had been looking for hours for someone to help when she found her chance."],["WOMAN","Hello? Hello? I'm sorry. I'm going to have to call you back. My phone is dying."],["LIGHTNING BOLT LADY","Excuse me, I can charge your phone."],["WOMAN","Really? Thanks!"],["LIGHTNING BOLT LADY","I'm Lightning Bolt Lady!"],["ANNOUNCER","She had been practicing her superpowers all day. Suddenly, she heard a terrible sound – a child's disappointment."],["ANNOUNCER","These children tried to light a fire for over an hour. But then, they gave up."],["PARENT","Hey kids, that wood will never burn. It'is too wet."],["LIGHTNING BOLT LADY","Small humans, what is wrong?"],["CHILD","Stranger danger!"],["LIGHTNING BOLT LADY","I'm Lightning Bolt Lady!"],["YOUNG MAN","Oh no. It's you."],["LIGHTNING BOLT LADY","(to YOUNG MAN:) We meet again. And guess what: I found my superpowers."],["CHILD","Well, we need a fire to toast the marshmallows to make S'mores."],["LIGHTNING BOLT LADY","I can help."],["YOUNG MAN","We don't need a super-speed walker but thanks!"],["LIGHTNING BOLT LADY","Super-speed walking is just one of my superpowers. I can also do this!"],["LIGHTNING BOLT LADY","Sorry! Let me do it again."],["CHILDREN","Thanks, Lightning Bolt Lady!"],["YOUNG MAN","Lightning Bolt Lady"],["LIGHTNING BOLT LADY","You're welcome. But you don't have enough firewood. Using my super-speed walking, I will get more."],["PARENT","Lightning Bolt Lady, come back! A lightning storm is coming!"],["LIGHTNING BOLT LADY","Not a chance! There's not a cloud in the …"],["CHILD","Lightning Bolt Lady, are you okay?"],["CHILD","Where's your super-suit?"],["ANNA","Oh no! I've lost my superpowers!"],["YOUNG MAN","It's starting to rain. Do you want to go inside and eat some S'mores?"],["ANNA","You read my mind."],["ANNA","You know, I thought mind reading would be one of my superpowers. But it wasn't."],["CHILD","That'd be a cool superpower."],["CHILD","But I'd rather be able to talk to animals."]]},{"g":"Уровень 2","t":"Lesson 26: Look-alikes","u":"/a/lets-learn-english-level-2-lesson-26/4350607.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/d/de/de2c2542-eef8-44b2-b2c0-baf24135549a.mp4?cb=ede5e8c19","a":"https://voa-audio.voanews.eu/vle/2018/04/25/3b556bb7-8c37-4c22-a390-d79b9f34fd24.mp3","l":[["Anna","This article is so interesting. Pete, listen to this: \"Somewhere in the world there is someone who looks just like you.\""],["Pete","No one is this handsome."],["Anna","Oh Pete, there's something between your teeth."],["Pete","It is gone?"],["Anna","No. No. It's still there. There. You got it. But think of it: There could be two of us in the world!"],["Pete","Two Annas?"],["Pete","Actually, Anna, maybe your silly article is right. Yesterday at work, I met a woman who looks just like you."],["Anna","Really? Wait, are you making fun of me?"],["Pete","Not this time."],["Pete","She's tall and has curly hair. But even her face looks like yours. I think she's a career consultant."],["Anna","I bet she has a lot of great advice. I can't wait to meet her."],["Pete","Yes, you can. I met her and she is very difficult."],["Anna","Pete, she's just new. We have to give her a chance. What's her name?"],["Pete","Evelyna or something like that. You can't miss her. She always wears a hat."],["Penelope","So, Anna, have you met the new consultant yet?"],["Anna","No. But I've already heard. We look alike, don't we?"],["Penelope","Yeah, but you don't act alike. You're much nicer than she is."],["Anna","Maybe she gets nervous at new jobs. Or maybe she's shy. Let's not judge, Penelope."],["Penelope","She's not nervous or shy. She's mean."],["Anna","You know, we should get to know her better. Let's invite her to lunch!"],["Penelope","Sorry but I'm busy that day."],["Anna","Oh, that's too bad. Hey, I haven't picked a day yet!"],["Anna","This is going to be so much fun. Boy, I can't wait to play this game."],["Evilana","How much longer are you going to be?"],["Anna","We'll be just a minute …"],["Anna","You must be Evelana. I'm Anna. We are look-alikes!"],["Evilana","No, we're not. And my name is pronounced \"Evil-ana.\""],["Pete","Oh. This is going to be fun."],["Evilana","You had better hurry up. I need this room for a lecture. It's called: \"If You Want to Win, Others Must Lose.\" What is all this stuff, anyway?"],["Anna","It's a game. We're going to play at lunch."],["Evilana","It's a stupid child's game!"],["Anna","It's a fun game. But yes, it is for children."],["Evilana","Well, you may be childish but I'm not. And you look stupid with that thing on your head."],["Anna","Well, you look serious with that look on your face. Come on, Pete. Let's play somewhere else."],["Pete","Actually, I'm going to stay for Evilana's lecture."],["Anna","Fine. You can learn new ways to beat people."],["Evilana","He will. He will."],["Anna","Okay. Am I a food?"],["Penelope","Nope."],["Pete","Hey, do you guys have room for one more?"],["Penelope","Sure, Pete! Come on over. What happened to your eye?"],["Pete","Evilana \"accidentally\" hit me. And she didn't even say sorry. She's so mean!"],["Penelope","I told you so."],["Anna","Here, Pete. Put on this headband. You'll feel better. Penelope, you're right. Evilana is an awful person!"],["Penelope","And violent. And now we have to work with her!"],["Anna","Haven't you heard? She's gone! She was given another assignment."],["Penelope","What assignment?"],["Anna","I'm not sure. I think it has something to do with outdoors. Anyway, let's play! Pete it's your turn."]]},{"g":"Уровень 2","t":"Lesson 27: Fish out of Water","u":"/a/lets-learn-english-level-2-lesson-27/4374632.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/1/1f/1f94874c-4395-4a61-b536-714406498f46.mp4?cb=ede5e8c91","a":"https://voa-audio.voanews.eu/vle/2018/05/03/198277fc-1de6-487a-8196-dc808623e1b6.mp3","l":[["ANNA","Hello, Ms. Weaver!"],["MS. WEAVER","Oh, Anna. I've invited some people to dinner Saturday. We're going to that new seafood restaurant -- Fish on a Dish."],["MS. WEAVER","Why don't you join us? My treat."],["ANNA","Thanks, Ms. Weaver. But I already have plans. My friend has invited me to her houseboat."],["MS. WEAVER","Houseboat, really? That's unique."],["ANNA","Yes, it is. In fact, I'm thinking of living on a houseboat."],["MS. WEAVER","Aren't you too tall and klutzy to live on a houseboat?"],["ANNA","I am not too tall!"],["PROF. BOT VO","Is Anna really ready for a houseboat?"],["PROF. BOT","Ms. Weaver invited Anna to dinner. When we make friendly, informal invitations, we use phrases like \"Why don't…?\""],["PROF. BOT","For example, Ms. Weaver said, \"Why don't you join us? My treat!\" That's: Why don't plus the subject plus the simple form of the verb."],["PROF. BOT","Anna responded to the invitation by saying, \"Thanks, but I already have plans.\" Keep watching for more examples of informal invitations!"],["FANNY","Anna, I'm so glad you could come!"],["ANNA","Hi, Fanny!"],["FANNY","Hi, this is my son, Phoenix."],["ANNA","Hi, Phoenix."],["FANNY","How about you give Anna a tour and I will make some lunch?"],["PHOENIX","Aye, aye, captain!"],["FANNY","Great!"],["ANNA","Do you really call her \"captain\"?"],["PHOENIX","I kind of have to."],["ANNA","So, Phoenix, I think I'd like to live on a houseboat. Do you like living here?"],["PHOENIX","I love it! It's much different than living in a house."],["ANNA","Oh, I bet. I bet you had to get rid of a lot of stuff, didn't you?"],["PHOENIX","No way! We moved from a 3-story house to a boat! So, we really had to downsize!"],["ANNA","I'd have to get rid of a lot of stuff. I have a rock collection and I have some really big rocks."],["ANNA","Can you stop this boat from rocking for a minute?"],["PHOENIX","No. We're floating on water. I can't do that."],["ANNA","Well, since you live on the water, aren't you afraid of great white sharks?"],["PHOENIX","No, not really. They don't live in these waters."],["ANNA","… that you know of. What about killer whales?"],["PHOENIX","No."],["ANNA","Electric eels?"],["PHOENIX","No."],["ANNA","Barracudas?"],["PHOENIX","No."],["ANNA","Piranhas?"],["PHOENIX","Uh-uh."],["FANNY","You know, Anna, if you're afraid of sea life, maybe you shouldn't live on a houseboat. Do you have any boating experience?"],["ANNA","Oh, oh yeah, Fanny. I have battled the great waters before -- once on a swan boat and once in a duck boat... bus. It was a boat that turned into a bus."],["FANNY","Yeah, I don't think that counts."],["ANNA","Fanny, does this rocking ever bother you?"],["FANNY","No, I love it. It goes up and down and side to side and up and down. Anna, I love it!"],["FANNY","Anna, are you feeling okay?"],["ANNA","Yeah, yeah. You know, I just need some fresh air."],["FANNY","Let me open a window for you."],["ANNA","No, I need some fresh land air. I mean, I need to breathe air on land. Oh, is that the time? I should really be going."],["ANNA","Thanks for lunch, Fanny, and a tour of your houseboat. It's given me a great idea!"],["FANNY","You're going to live on a houseboat?"],["ANNA","Sort of. Thanks again!"],["ANNA","Hi! How would you like to hang out on my boat? Great! See you then!"],["ANNA","…and this is my shark net."],["MS. WEAVER","Thank you for the invitation, Anna."],["ANNA","Of course, would you like more orange juice?"],["MS. WEAVER","Uh.."],["ANNA","(to young man) Ahoy!"]]},{"g":"Уровень 2","t":"Lesson 28: For the Birds","u":"/a/lets-learn-english-level-2-lesson-28/4396849.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/b/bb/bb0da721-de99-49ad-be0b-2441ad716410.mp4?cb=ede5e8cd0","a":"https://voa-audio.voanews.eu/vle/2018/05/17/48003699-cb0b-4cb7-8002-27bb38944ebf.mp3","l":[["KELLY","Oh, Anna, there you are! I am so glad we joined the Great City Bird Count! Aren't you?"],["ANNA","No. Today has been a bust … a flop … a bummer!"],["KELLY","I'm sensing a little disappointment."],["ANNA","A little?"],["KELLY","My official bird-watching form is almost full!"],["ANNA","I've only seen pigeons... lots and lots of pigeons! But I did write down some other valuable information."],["KELLY","Did you find a bird's nest?!"],["ANNA","No."],["ANNA","I found 10 ice cream trucks in this five-block area.​ Their music seems to follow me everywhere."],["KELLY","We're supposed to be counting birds, not ice cream trucks. This is important scientific work!"],["ANNA","Well, when you want ice cream, my data will be pretty important."],["KELLY","Anna, birds are everywhere! I'm sure you'll find something. Use your imagination! But, make sure that you put it on the official form."],["PROF. BOT","Anna was supposed to find birds, but she didn't."],["PROF. BOT","Kelly says, \"We're supposed to be counting birds, not ice cream trucks.\" To be supposed to means you are expected to do something."],["PROF. BOT","It's different from have to and ought to. Have to means you must do something. And ought to means you should do it but you don't have to."],["PROF. BOT","Keep watching for have to and ought to!"],["ANNA","No birds. Oh wait, there's another ice cream truck! Anna, focus on birds. Aw, but that truck has my favorite flavor... banana!"],["ANNA","That man is in the way. I can't see the price. I wonder what flavor he's getting."],["ANNA","Strawberry? He doesn't seem like a strawberry kind of guy."],["ANNA","In fact, he doesn't seem like an ice cream truck kind of guy. That suit looks expensive."],["ANNA","Maybe he's a spy! You know what that means: The ice cream truck driver is a spy, too!"],["ANNA","Genius! It's a perfect disguise."],["ANNA","What?! The man in the suit left his briefcase at the ice cream truck!"],["ANNA","I was right! He is a spy! And, he just dropped off top-secret information! I ought to do something. Something needs to be done! I need to do something."],["ANNA","I did it! I took the spy's briefcase!"],["ANNA","What's that?! The ice cream truck -- it's following me! It wants the case back! I have to hide."],["ANNA","This is my life now -- running, scared, alone."],["ANNA","That awful music -- it's following me everywhere!"],["MAN","Hey! You found my briefcase."],["ANNA","You caught me! I mean, I caught you!"],["MAN","Well, I just want my briefcase. All my poems are in there."],["ANNA","Poems? You're a poet?"],["MAN","Well, I'm a lawyer. But I write poems, too."],["ANNA","So, you're not a spy?"],["MAN","You look disappointed."],["ANNA","No, that's okay. It's not your fault. Poems are nice, too. I guess."],["MAN","Well, would you like me to read my latest one?"],["ANNA","Why not?"],["MAN","On sunny day walks, my hand reaches for ice cream from fragaria."],["ANNA","I love your poem!"],["MAN","I love ice cream."],["ANNA","Me too."],["MAN","What's your favorite flavor?"],["ANNA","Banana."],["MAN","Well, my favorite flavor is..."],["ANNA","Strawberry!"],["MAN","How did you know that?"],["ANNA","A little bird told me."]]},{"g":"Уровень 2","t":"Lesson 29: Where There's Smoke...","u":"/a/lets-learn-english-level-2-lesson-29/4423736.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2018/06/1/15/15611607-f9f6-4091-ab7b-7252258452fa_hq.mp4?cb=ed2bc555c","a":"https://voa-audio.voanews.eu/vle/2018/06/08/c954b93d-aacb-40b2-8c20-423d8c100045.mp3","l":[["PENELOPE","Hey, Anna. What are you reading?"],["ANNA","I'm reading about fire safety. Ms. Weaver named me fire safety monitor."],["PENELOPE","But the only time we have a fire emergency is when someone burns a piece of toast."],["ANNA","That is true. But fire safety is very serious – very serious. If there is a fire emergency, I have to help everyone out of the building."],["PENELOPE","Well then, if I were you, I'd learn as much as possible."],["ANNA","You're right. And I know just who to call!"],["PROF. BOT","Hmm, I wonder where Anna's going. Today we are reviewing conditionals and learning helpful language for emergencies."],["PROF. BOT","If Anna studies hard, she'll be a great fire safety monitor! That's a conditional. It uses \"if\" to show that something is true only when something else is true."],["PROF. BOT","Let's find out where Anna is going. And if you want to learn fire emergency language, keep watching!"],["ANNA","Hi, Firefighter Jones."],["FIREFIGHTER JONES","Hey, how are you, Anna?"],["ANNA","I'm well, thanks. How are you? Hi, Firefighter Hatcher."],["FIREFIGHTER HATCHER","Hi, Anna. How are you?"],["ANNA","I'm well, thanks."],["FF H","Welcome to our firehouse."],["ANNA","Thank you."],["FF H","Come on in."],["ANNA","Thanks."],["FF H","This is where the firefighters eat. This is where we rest. This is where we exercise. This is where the firetrucks are parked and maintained."],["ANNA","This place is beautiful."],["FF H","You know, the firehouse is a firefighter's second home."],["ANNA","Firefighter Jones, Firefighter Hatcher: Can you tell me some ways to prepare for a fire emergency?"],["FF H","Sure, Anna. There's one really important thing you can do: Install a fire alarm. Test it monthly and make sure the batteries are fully charged."],["ANNA","Let's talk about those emergency exits."],["FF J","In your home, office and schools, know where your emergency exits are located."],["ANNA","What about fire extinguishers?"],["FF J","Everyone should know how to use a fire extinguisher. Have one handy and practice using it."],["ANNA","What if we need to get out?"],["FF J","You should have an evacuation plan. And practice getting out safely with fire drills."],["ANNA","If I am in a building and it's on fire, should I use the elevator?"],["FF H","No. Always use the stairs."],["ANNA","What other safety tips should I know?"],["FF J","Stay low. Smoke rises. The air is clearer close to the ground."],["ANNA","Stay low. Anything else?"],["FF H","If you touch a door and it's hot, don't open it. There might be a fire on the other side."],["ANNA","What do I do if my clothes catch on fire?"],["FF H","Do not run. If you run, the fire will burn faster. You must stop, drop and roll."],["ANNA","Thanks so much! I've learned a lot. And I can't wait to share this information with others."],["FF H","Thanks for coming, Anna."],["FF J","It's been a pleasure meeting you."],["PENELOPE","So, Anna, how was the visit to the fire station?"],["ANNA","I learned a lot! And firefighters have a very difficult job."],["PENELOPE","Do you smell smoke?"],["ANNA","No. So, like I was saying, I learned how to …"],["PENELOPE","Anna, I smell smoke."],["ANNA","If you smell smoke, call the fire department!"],["ANNA","If you smell smoke, get out of the building. Come on people, we have a fire emergency! Leave your things and evacuate calmly and quickly. Very good. Very good."],["ANNA","We have a fire emergency. No, take the stairs Let's get out. Let's get out safely."],["ANNA","We got out in less than 6 minutes! Good job, people! Wait. Where's Pete?"],["PENELOPE","I know where he is. I'll go get him."],["ANNA","No! Never go back into a burning building! The fire department is coming. Stay calm, Pete. Help is on the way! Help is on the way!"]]},{"g":"Уровень 2","t":"Lesson 30: Dream a Little Dream","u":"/a/lets-learn-english-level-2-lesson-30/4465315.html","v":"https://voa-video-ns.akamaized.net/pangeavideo/2021/02/2/24/243c881f-4bee-45a7-b181-d3c8b4156c30.mp4?cb=ede5e8d21","a":"https://voa-audio.voanews.eu/vle/2018/07/06/931150ac-ddf3-42db-9247-b3ac4aec6180.mp3","l":[["Ashley","Anna, where are you going in such a hurry?"],["Anna","Hi, Ashley. The nurse's office. Today I get the results from my blood test."],["Ashley","I'm sure you're fine. Don't worry."],["Anna","You know, I used to dream of being a nurse. It is such an honorable career. Is there something you've dreamed of doing?"],["Ashley","Sure! I would love to be a dog trainer. Actually, I've taught my dog, Dublin, lots of tricks!"],["Anna","Well, I'm off to the nurse. Bye, Ashley."],["Ashley","Bye, Anna."],["Anna","Bye, Dublin."],["Nurse","I'm looking at her test results and they're not good. In fact, I'm afraid she's not going to make it."],["Anna","What?! I'm not going to make it? I'm dying??"],["Nurse","Anna, come in. How are you?"],["Anna","I guess..not so good. I'm dying!?"],["Nurse","What are you talking about?"],["Anna","I just heard you on the phone. Just tell me: How much longer do I have?"],["Nurse","I wasn't talking about you. A student of mine didn't do well on her science test. So, she won't be able to make it... to graduation."],["Anna","Whew. Thank goodness! For a minute, my whole life passed before my eyes. There are so many things I haven't done yet."],["Anna","I couldn't agree more."],["Nurse","Now, let's talk about your blood test. Your cholesterol is really low."],["Anna","Awesome!"],["Jonathan","Okay, Anna, say something and I'll check your sound level."],["Anna","Testing 1, 2, 3. Testing. Jonathan, I've been wondering something: What's at the top of your bucket list?"],["Jonathan","That's easy. I'd love to win the World Karaoke Contest."],["Anna","This is so strange. I just saw on Twitter that they are having auditions in D.C. this weekend!"],["Jonathan","Are you serious? Can you read the story by yourself?"],["Anna","Sure, absolutely."],["Jonathan","Thanks!"],["Anna","You go."],["Anna","Penelope, I was wondering if you still dream of being a dancer."],["Penelope","Only every day!"],["Anna","Well, guess what: A famous dancer is having a flash mob around the corner! Hundreds of people are dancing together!"],["Penelope","No way!"],["Anna","Way! If you leave right now, you can join them! Bye!"],["Anna","Pete, what's one of your dreams?"],["Pete","Well, last night I dreamt I was in a spaceship. I was flying through outer space with these two beautiful..."],["Anna","Pete -- not that kind of dream. I mean your hopes for the future."],["Anna","That's going to be difficult."],["Pete","It's my agent! Hello? Uh-huh. Sure! I can be in Los Angeles tomorrow!"],["Anna","Well, good job, Anna! My work here is done … almost."],["MUSIC","You can search but you won't find the answer without a dream. You can reach for the stars but you won't get there without a dream...without a dream."],["Ms. Weaver","Anna, what's going on? Where is everybody?"],["Anna","I don't know. Maybe something is, uh, going around the office."],["Ms. Weaver","You mean germs? Anna, you'd better use some of this hand cleaner. You don't want to get sick, too."],["Anna","Right. Okay, thanks. Not germs – dreams, Ms. Weaver. Dreams."],["Ms. Weaver","What did you say, Anna?"],["Anna","Nothing. Nothing."],["Prof. Bot","We hope you have enjoyed Level 2 of Let's Learn English. Everyone is following their dreams, big and small."],["Prof. Bot","What are your dreams? Our dream is for you to keep learning English! Thanks for watching."]]}];
